static bool kv_cache_store_live_prefix_text(server *s, const ds4_tokens *tokens,
                                            int store_len, const char *reason,
                                            const char *cache_text_override,
                                            uint8_t cache_text_ext,
                                            const char *cache_text_key) {
    char err[160] = {0};
    ds4_kvstore_trailer_hooks hooks = kv_cache_tool_map_hooks(s, NULL);
    /* Serial-tier record: keyed by the session's ACTUAL ctx (the payload's
     * geometry) -- under v0.5.2 right-sizing this can be smaller than -c,
     * and the store's <=-ctx restore filter keeps such records portable
     * upward into any bigger later session. */
    return ds4_kvstore_store_live_prefix_text(&s->kv, s->engine, s->session,
                                              ds4_session_ctx(s->session),
                                              tokens, store_len, reason,
                                              cache_text_override,
                                              cache_text_ext,
                                              cache_text_key,
                                              &hooks, NULL, err, sizeof(err));
}

static bool kv_cache_store_live_prefix(server *s, const ds4_tokens *tokens,
                                       int store_len, const char *reason) {
    return kv_cache_store_live_prefix_text(s, tokens, store_len, reason,
                                           NULL, 0, NULL);
}

static void kv_cache_store_current(server *s, const char *reason) {
    const ds4_tokens *tokens = ds4_session_tokens(s->session);
    if (!tokens) return;

    char *visible_text = NULL;
    uint8_t visible_ext = 0;
    const char *visible_key = NULL;
    pthread_mutex_lock(&s->tool_mu);
    if (s->responses_live.valid &&
        s->responses_live.live_tokens == tokens->len &&
        s->responses_live.visible_text &&
        s->responses_live.visible_text[0])
    {
        visible_text = xstrdup(s->responses_live.visible_text);
        visible_ext = KV_EXT_RESPONSES_VISIBLE;
        visible_key = "responses-visible";
    } else if (s->thinking_live.valid &&
               s->thinking_live.live_tokens == tokens->len &&
               s->thinking_live.visible_text &&
               s->thinking_live.visible_text[0])
    {
        visible_text = xstrdup(s->thinking_live.visible_text);
        visible_ext = KV_EXT_THINKING_VISIBLE;
        visible_key = "thinking-visible";
    }
    pthread_mutex_unlock(&s->tool_mu);

    /* A visible live checkpoint can contain hidden reasoning that the client
     * intentionally does not replay.  For disk recovery after a session switch,
     * key that payload by the visible protocol transcript, not by rendering the
     * hidden sampled tokens.  On load, DS4 restores the hidden KV payload and
     * tokenizes only the visible suffix that follows this key. */
    if (visible_text) {
        kv_cache_store_live_prefix_text(s, tokens, tokens->len, reason,
                                        visible_text, visible_ext, visible_key);
        free(visible_text);
    } else {
        kv_cache_store_live_prefix(s, tokens, tokens->len, reason);
    }
}

/* v0.3 durable pinned banks: persist one cont bank's state to the disk KV
 * store before its warm record is destroyed (reason "bank-evict", pin tier
 * only: min_committed = warm_pin_min) or at shutdown (reason
 * "bank-shutdown", min_committed = 1: every valid record).  min_committed
 * <= 0 disables the call site's tier.  The record's rendered text is the
 * store key, so a later request byte-prefix-matches it exactly like a live
 * warm record; the payload restores through
 * ds4_kvstore_try_restore_bank_text at admission.  Runs on the worker
 * thread under gen_mu (evict sites) or after client drain (shutdown) --
 * the bank is idle by construction at both. */
static void kv_cache_store_bank(server *s, int bank, const char *reason,
                                int min_committed) {
    if (min_committed <= 0) return;
    if (!s->kv.enabled || !s->batch_ctx || !s->warm) return;
    if (bank < 0 || bank >= s->batch_ctx_max_seq || !s->warm[bank].valid) return;
    if (!s->warm[bank].text || s->warm[bank].len == 0) return;
    const int *htok = NULL;
    const int hl = ds4_batch_ctx_bank_committed(s->batch_ctx, bank, &htok);
    if (!htok || hl < min_committed) return;
    char err[160] = {0};
    ds4_session_payload_file staged = {0};
    if (ds4_cont_bank_stage_payload(s->batch_ctx, (uint32_t)bank, &staged,
                                    err, sizeof(err)) != 0) {
        server_log(DS4_LOG_KVCACHE,
                   "ds4-server: bank persist skipped bank=%d reason=%s: %s",
                   bank, reason, err);
        return;
    }
    ds4_tokens tokens = { (int *)htok, (int)hl, (int)hl };
    ds4_kvstore_trailer_hooks hooks = kv_cache_tool_map_hooks(s, NULL);
    /* Bank-tier record: keyed by the SERVING ctx (the bank's geometry),
     * never the serial session's -- v0.5.2 right-sizing can shrink that
     * session, and a bank record must keep restoring across boots at -c. */
    const bool ok = ds4_kvstore_store_live_prefix_text(&s->kv, s->engine,
                        s->session, s->serial_boot_ctx,
                        &tokens, (int)hl, reason,
                        s->warm[bank].text, 0, "bank",
                        &hooks, &staged, err, sizeof(err));
    ds4_session_payload_file_free(&staged);
    if (ok) {
        s->warm[bank].stored_tokens = hl;   /* v0.5.1 inc3b pacing marker */
        server_log(DS4_LOG_KVCACHE,
                   "ds4-server: bank persisted bank=%d tokens=%u reason=%s",
                   bank, hl, reason);
    }
}

