static void test_anthropic_tool_use_parses_before_role(void) {
    server s = {0};
    pthread_mutex_init(&s.tool_mu, NULL);

    /* GitHub #127 regression: Crush can replay full Anthropic history with
     * message objects serialized as {"content": ..., "role": ...}.  The parser
     * must still remember prior assistant tool_use ids, otherwise old
     * tool_result blocks are mistaken for live-only continuations and rejected
     * once the live frontier has moved on to newer tool calls. */
    /* Inc 5a: a LIVE binding now lives in the continuation registry. */
    {
        tool_calls calls = {0};
        tool_call tc = {0};
        tc.id = xstrdup("toolu_current");
        tool_calls_push(&calls, tc);
        cont_registry_publish_serial(&s, API_ANTHROPIC, &calls, 5, 100);
        tool_calls_free(&calls);
    }

    const char *json =
        "["
        "{\"content\":["
        "{\"type\":\"tool_use\",\"id\":\"toolu_old\",\"name\":\"Bash\","
        "\"input\":{\"command\":\"ls\"}}"
        "],\"role\":\"assistant\"},"
        "{\"role\":\"user\",\"content\":["
        "{\"type\":\"tool_result\",\"tool_use_id\":\"toolu_old\",\"content\":\"ok\"}"
        "]},"
        "{\"role\":\"user\",\"content\":\"continue\"}"
        "]";
    const char *p = json;
    chat_msgs msgs = {0};
    TEST_ASSERT(parse_anthropic_messages(&p, &msgs));
    TEST_ASSERT(msgs.len == 3);
    TEST_ASSERT(msgs.v[0].calls.len == 1);
    TEST_ASSERT(msgs.v[0].calls.v[0].id &&
                !strcmp(msgs.v[0].calls.v[0].id, "toolu_old"));

    bool needs_live_tool_state = false;
    char err[160] = {0};
    TEST_ASSERT(anthropic_validate_tool_results(&s, &msgs,
                                                &needs_live_tool_state,
                                                err, sizeof(err)));
    TEST_ASSERT(!needs_live_tool_state);

    chat_msgs_free(&msgs);
    cont_registry_free(&s);
    pthread_mutex_destroy(&s.tool_mu);
}

/* Inc 5a: registry core semantics -- publish/resolve with exact execution
 * reference equality (generation + frontier), protocol namespace isolation,
 * set-equality on ids, and the LIVE -> REPLAY_ONLY demotion. */
static void test_cont_registry_publish_resolve_demote(void) {
    server s = {0};
    pthread_mutex_init(&s.tool_mu, NULL);

    tool_calls calls = {0};
    tool_call a = {0};
    a.id = xstrdup("toolu_regA");
    tool_calls_push(&calls, a);
    tool_call b = {0};
    b.id = xstrdup("toolu_regB");
    tool_calls_push(&calls, b);
    cont_registry_publish_serial(&s, API_ANTHROPIC, &calls, 7, 100);
    tool_calls_free(&calls);

    /* LIVE visibility is protocol-scoped (plan §4.6 collision/bleed). */
    TEST_ASSERT(anthropic_live_has_call_id(&s, "toolu_regA"));
    TEST_ASSERT(anthropic_live_has_call_id(&s, "toolu_regB"));
    TEST_ASSERT(!responses_live_has_call_id(&s, "toolu_regA"));

    stop_list ids = {0};
    id_list_push_unique(&ids, "toolu_regA");
    id_list_push_unique(&ids, "toolu_regB");
    TEST_ASSERT(cont_registry_resolve_serial(&s, API_ANTHROPIC, &ids, 7, 100));
    /* The ABA the singletons could not catch: same position, new content
     * generation.  And the frontier check both ways. */
    TEST_ASSERT(!cont_registry_resolve_serial(&s, API_ANTHROPIC, &ids, 8, 100));
    TEST_ASSERT(!cont_registry_resolve_serial(&s, API_ANTHROPIC, &ids, 7, 101));
    TEST_ASSERT(!cont_registry_resolve_serial(&s, API_RESPONSES, &ids, 7, 100));
    /* Exact set equality: subset and superset both refuse. */
    stop_list sub = {0};
    id_list_push_unique(&sub, "toolu_regA");
    TEST_ASSERT(!cont_registry_resolve_serial(&s, API_ANTHROPIC, &sub, 7, 100));
    stop_list sup = {0};
    id_list_push_unique(&sup, "toolu_regA");
    id_list_push_unique(&sup, "toolu_regB");
    id_list_push_unique(&sup, "toolu_regC");
    TEST_ASSERT(!cont_registry_resolve_serial(&s, API_ANTHROPIC, &sup, 7, 100));

    /* Demote: LIVE lookups and resolve refuse; the ids stay reserved for
     * mint uniqueness (a REPLAY_ONLY record's ids must never be re-minted). */
    cont_registry_demote_serial(&s);
    TEST_ASSERT(!anthropic_live_has_call_id(&s, "toolu_regA"));
    TEST_ASSERT(!cont_registry_resolve_serial(&s, API_ANTHROPIC, &ids, 7, 100));
    TEST_ASSERT(cont_registry_id_known(&s, "toolu_regA"));
    TEST_ASSERT(tool_id_in_use(&s, "toolu_regA"));

    id_list_free(&ids);
    id_list_free(&sub);
    id_list_free(&sup);
    cont_registry_free(&s);
    pthread_mutex_destroy(&s.tool_mu);
}

/* Inc 5a: one record per serial turn (a new publication supersedes the old
 * LIVE record) and the bounded store's oldest-REPLAY_ONLY-first cap. */
static void test_cont_registry_supersede_and_cap(void) {
    server s = {0};
    pthread_mutex_init(&s.tool_mu, NULL);
    s.creg.max_records = 4;

    char idbuf[32];
    for (int t = 1; t <= 2; t++) {
        tool_calls calls = {0};
        tool_call tc = {0};
        snprintf(idbuf, sizeof(idbuf), "toolu_turn%d", t);
        tc.id = xstrdup(idbuf);
        tool_calls_push(&calls, tc);
        cont_registry_publish_serial(&s, API_ANTHROPIC, &calls,
                                     3, 50 * t);
        tool_calls_free(&calls);
    }
    /* Turn 2 superseded turn 1: exactly one LIVE record. */
    TEST_ASSERT(!anthropic_live_has_call_id(&s, "toolu_turn1"));
    TEST_ASSERT(anthropic_live_has_call_id(&s, "toolu_turn2"));
    TEST_ASSERT(s.creg.n_live == 1);
    TEST_ASSERT(s.creg.n_records == 2);

    /* Push past the cap: oldest REPLAY_ONLY records evict (their ids drop
     * from the index atomically); the LIVE tip always survives. */
    for (int t = 3; t <= 8; t++) {
        tool_calls calls = {0};
        tool_call tc = {0};
        snprintf(idbuf, sizeof(idbuf), "toolu_turn%d", t);
        tc.id = xstrdup(idbuf);
        tool_calls_push(&calls, tc);
        cont_registry_publish_serial(&s, API_ANTHROPIC, &calls,
                                     3, 50 * t);
        tool_calls_free(&calls);
    }
    TEST_ASSERT(s.creg.n_records <= 4);
    TEST_ASSERT(!cont_registry_id_known(&s, "toolu_turn1"));
    TEST_ASSERT(!cont_registry_id_known(&s, "toolu_turn2"));
    TEST_ASSERT(anthropic_live_has_call_id(&s, "toolu_turn8"));
    TEST_ASSERT(s.creg.n_live == 1);

    cont_registry_free(&s);
    pthread_mutex_destroy(&s.tool_mu);
}

/* Inc 5a: while LIVE_FRONTIER a record's strong references keep its exact
 * DSML out of the tool-memory LRU's reach; demotion releases them. */
static void test_cont_registry_pins_exact_dsml(void) {
    server s = {0};
    pthread_mutex_init(&s.tool_mu, NULL);
    s.tool_mem.max_entries = 2;

    tool_memory_put(&s, "toolu_pinned", "<dsml sampled live bytes>");
    {
        tool_calls calls = {0};
        tool_call tc = {0};
        tc.id = xstrdup("toolu_pinned");
        tool_calls_push(&calls, tc);
        cont_registry_publish_serial(&s, API_ANTHROPIC, &calls, 9, 40);
        tool_calls_free(&calls);
    }
    /* Flood the tiny LRU: the pinned entry is the tail yet survives; the
     * prune walks past it and evicts the next-oldest unpinned entry. */
    tool_memory_put(&s, "toolu_fill2", "<dsml 2>");
    tool_memory_put(&s, "toolu_fill3", "<dsml 3>");
    TEST_ASSERT(tool_memory_has_id(&s, "toolu_pinned"));
    TEST_ASSERT(!tool_memory_has_id(&s, "toolu_fill2"));
    TEST_ASSERT(tool_memory_has_id(&s, "toolu_fill3"));

    /* Demote unpins: the next prune reclaims the old frontier's bytes. */
    cont_registry_demote_serial(&s);
    tool_memory_put(&s, "toolu_fill4", "<dsml 4>");
    TEST_ASSERT(!tool_memory_has_id(&s, "toolu_pinned"));
    TEST_ASSERT(tool_memory_has_id(&s, "toolu_fill3"));
    TEST_ASSERT(tool_memory_has_id(&s, "toolu_fill4"));

    cont_registry_free(&s);
    tool_memory_free(&s.tool_mem);
    pthread_mutex_destroy(&s.tool_mu);
}

/* Inc 5b: the serial-admission hold matrix -- grace sheds non-continuing
 * work, continuations pass, expiry ends the grace, a queued T2's hard pin
 * holds beyond grace, the pin deadline bounds it, and teardown releases. */
static void test_cont_registry_grace_and_pin_hold(void) {
    server s = {0};
    pthread_mutex_init(&s.tool_mu, NULL);
    s.creg.grace_s = 60.0;
    s.creg.ttl_s = 300.0;
    s.creg.pin_deadline_s = 60.0;
    s.creg.hold_shed_s = 5.0;   /* v0.5.6.1 seat-shed window */

    {
        tool_calls calls = {0};
        tool_call tc = {0};
        tc.id = xstrdup("toolu_hold");
        tool_calls_push(&calls, tc);
        cont_registry_publish_serial(&s, API_ANTHROPIC, &calls, 4, 70);
        tool_calls_free(&calls);
    }

    request unrelated;
    request_init(&unrelated, REQ_CHAT, 64);
    int retry = 0;
    /* Inside the seat-shed window: non-continuing serial work sheds, and
     * Retry-After is the WINDOW remainder (<= 5), never the grace. */
    TEST_ASSERT(cont_registry_serial_hold(&s, &unrelated, now_sec(), &retry));
    TEST_ASSERT(retry >= 1 && retry <= 5);

    /* The continuation itself passes the hold. */
    request t2;
    request_init(&t2, REQ_CHAT, 64);
    t2.api = API_ANTHROPIC;
    id_list_push_unique(&t2.anthropic_live_call_ids, "toolu_hold");
    TEST_ASSERT(!cont_registry_serial_hold(&s, &t2, now_sec(), &retry));

    /* v0.5.6.1 (codex compaction kill): past the seat window but INSIDE
     * grace, a non-continuing request takes the seat instead of shedding
     * -- the record itself stays LIVE for id resolution. */
    pthread_mutex_lock(&s.tool_mu);
    s.creg.serial_live->publish_time -= 10.0;
    pthread_mutex_unlock(&s.tool_mu);
    TEST_ASSERT(!cont_registry_serial_hold(&s, &unrelated, now_sec(), &retry));
    pthread_mutex_lock(&s.tool_mu);
    TEST_ASSERT(s.creg.serial_live != NULL &&
                s.creg.serial_live->state == CONT_REC_LIVE_FRONTIER);
    pthread_mutex_unlock(&s.tool_mu);

    /* Grace over, no pin: unrelated work passes (and would demote). */
    pthread_mutex_lock(&s.tool_mu);
    s.creg.serial_live->publish_time -= 120.0;
    pthread_mutex_unlock(&s.tool_mu);
    TEST_ASSERT(!cont_registry_serial_hold(&s, &unrelated, now_sec(), &retry));

    /* A queued T2's hard pin holds past grace. */
    request_acquire_cont_pin(&s, &t2);
    TEST_ASSERT(t2.cont_pin != NULL && t2.cont_pin_srv == &s);
    TEST_ASSERT(cont_registry_serial_hold(&s, &unrelated, now_sec(), &retry));
    TEST_ASSERT(retry >= 1);

    /* The queue deadline bounds the pin's hold power. */
    pthread_mutex_lock(&s.tool_mu);
    s.creg.serial_live->pin_expiry = now_sec() - 1.0;
    pthread_mutex_unlock(&s.tool_mu);
    TEST_ASSERT(!cont_registry_serial_hold(&s, &unrelated, now_sec(), &retry));

    /* Teardown releases exactly once. */
    request_free(&t2);
    pthread_mutex_lock(&s.tool_mu);
    TEST_ASSERT(s.creg.serial_live->hard_refs == 0);
    pthread_mutex_unlock(&s.tool_mu);

    request_free(&unrelated);
    cont_registry_free(&s);
    pthread_mutex_destroy(&s.tool_mu);
}

/* Inc 5b: lazy soft-TTL -- an unclaimed LIVE record demotes at the next
 * read; the ids stay reserved for mint uniqueness. */
static void test_cont_registry_ttl_expire(void) {
    server s = {0};
    pthread_mutex_init(&s.tool_mu, NULL);
    s.creg.ttl_s = 300.0;

    {
        tool_calls calls = {0};
        tool_call tc = {0};
        tc.id = xstrdup("toolu_ttl");
        tool_calls_push(&calls, tc);
        cont_registry_publish_serial(&s, API_ANTHROPIC, &calls, 4, 70);
        tool_calls_free(&calls);
    }
    TEST_ASSERT(anthropic_live_has_call_id(&s, "toolu_ttl"));

    pthread_mutex_lock(&s.tool_mu);
    s.creg.serial_live->publish_time -= 301.0;
    pthread_mutex_unlock(&s.tool_mu);

    TEST_ASSERT(!anthropic_live_has_call_id(&s, "toolu_ttl"));
    TEST_ASSERT(s.creg.n_live == 0);
    stop_list ids = {0};
    id_list_push_unique(&ids, "toolu_ttl");
    TEST_ASSERT(!cont_registry_resolve_serial(&s, API_ANTHROPIC, &ids, 4, 70));
    TEST_ASSERT(cont_registry_id_known(&s, "toolu_ttl"));

    id_list_free(&ids);
    cont_registry_free(&s);
    pthread_mutex_destroy(&s.tool_mu);
}

/* Inc 5b: a REPLAY_ONLY record participates in the tool-memory LRU as a
 * UNIT -- when the prune reaches one member entry, the whole record (all
 * entries + all call-id index rows) drops atomically. */
static void test_cont_registry_record_unit_eviction(void) {
    server s = {0};
    pthread_mutex_init(&s.tool_mu, NULL);
    s.tool_mem.max_entries = 2;

    tool_memory_put(&s, "toolu_u1", "<dsml unit turn>");
    tool_memory_put(&s, "toolu_u2", "<dsml unit turn>");
    {
        tool_calls calls = {0};
        tool_call a = {0};
        a.id = xstrdup("toolu_u1");
        tool_calls_push(&calls, a);
        tool_call b = {0};
        b.id = xstrdup("toolu_u2");
        tool_calls_push(&calls, b);
        cont_registry_publish_serial(&s, API_ANTHROPIC, &calls, 6, 90);
        tool_calls_free(&calls);
    }
    cont_registry_demote_serial(&s);   /* REPLAY_ONLY, unpinned */

    /* One over budget: the tail entry belongs to the record, so the WHOLE
     * record evicts -- both entries and both index rows, atomically. */
    tool_memory_put(&s, "toolu_u3", "<dsml 3>");
    TEST_ASSERT(!tool_memory_has_id(&s, "toolu_u1"));
    TEST_ASSERT(!tool_memory_has_id(&s, "toolu_u2"));
    TEST_ASSERT(tool_memory_has_id(&s, "toolu_u3"));
    TEST_ASSERT(!cont_registry_id_known(&s, "toolu_u1"));
    TEST_ASSERT(!cont_registry_id_known(&s, "toolu_u2"));
    TEST_ASSERT(s.creg.n_records == 0);

    cont_registry_free(&s);
    tool_memory_free(&s.tool_mem);
    pthread_mutex_destroy(&s.tool_mu);
}

/* Inc 5c: send_all's capture redirect -- when t_capture_buf is set every
 * emitter byte lands in the private buffer and NOTHING touches the socket;
 * cleared, the same call writes the fd.  This is what lets the terminal
 * transaction build exact terminal bytes through unmodified emitters. */
static void test_send_all_capture_redirect(void) {
    int sv[2];
    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);

    buf cap = {0};
    t_capture_buf = &cap;
    TEST_ASSERT(send_all(sv[0], "abc", 3));
    t_capture_buf = NULL;
    TEST_ASSERT(cap.len == 3 && memcmp(cap.ptr, "abc", 3) == 0);
    char rb[8];
    TEST_ASSERT(recv(sv[1], rb, sizeof(rb), MSG_DONTWAIT) < 0);   /* socket untouched */

    TEST_ASSERT(send_all(sv[0], "de", 2));
    TEST_ASSERT(recv(sv[1], rb, sizeof(rb), MSG_DONTWAIT) == 2 &&
                memcmp(rb, "de", 2) == 0);

    buf_free(&cap);
    close(sv[0]);
    close(sv[1]);
}

/* Inc 5c: the §4.6 terminal transaction failure ladder --
 * reserve -> publish -> commit as one visibility step;
 * reservation failure publishes NOTHING; a transport death detected
 * between publish and commit demotes to REPLAY_ONLY; a clean commit
 * leaves the record LIVE with the exact bytes on the wire. */
static void test_serial_terminal_commit_ladder(void) {
    server s = {0};
    pthread_mutex_init(&s.tool_mu, NULL);
    ds4_metrics *m = ds4_metrics_get();
    const uint64_t backlog0 = ds4_metric_read(&m->out_backlog_bytes);
    const uint64_t shed0 =
        ds4_metric_read(&m->requests_shed[DS4_SHED_SLOW_READER]);

    int sv[2];
    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
    job j = {0};
    j.fd = sv[0];

    buf tb = {0};
    buf_puts(&tb, "HTTP/1.1 200 OK\r\n\r\n{\"terminal\":1}");

    /* Leg A -- clean commit: record LIVE, exact bytes delivered, the
     * reservation charge fully released. */
    {
        tool_calls calls = {0};
        tool_call tc = {0};
        tc.id = xstrdup("toolu_txnA");
        tool_calls_push(&calls, tc);
        serial_terminal_commit(&s, &j, API_ANTHROPIC, &calls, 3, 50, &tb, "t");
        tool_calls_free(&calls);
    }
    TEST_ASSERT(anthropic_live_has_call_id(&s, "toolu_txnA"));
    TEST_ASSERT(!j.client_gone && j.outcome == JOB_OUT_COMPLETED);
    TEST_ASSERT(ds4_metric_read(&m->out_backlog_bytes) == backlog0);
    {
        char rb[128];
        ssize_t n = recv(sv[1], rb, sizeof(rb), MSG_DONTWAIT);
        TEST_ASSERT(n == (ssize_t)tb.len && memcmp(rb, tb.ptr, tb.len) == 0);
    }

    /* Leg B -- reservation failure publishes NOTHING: no record, no bytes,
     * slow-reader shed accounting, job marked gone + SHED. */
    {
        const uint64_t cap_save = g_out_agg_cap;
        g_out_agg_cap = 4;   /* tb.len is far over: reservation must refuse */
        tool_calls calls = {0};
        tool_call tc = {0};
        tc.id = xstrdup("toolu_txnB");
        tool_calls_push(&calls, tc);
        serial_terminal_commit(&s, &j, API_ANTHROPIC, &calls, 4, 60, &tb, "t");
        tool_calls_free(&calls);
        g_out_agg_cap = cap_save;
    }
    TEST_ASSERT(!cont_registry_id_known(&s, "toolu_txnB"));
    TEST_ASSERT(anthropic_live_has_call_id(&s, "toolu_txnA"));   /* prior tip untouched */
    TEST_ASSERT(j.client_gone && j.outcome == JOB_OUT_SHED);
    TEST_ASSERT(ds4_metric_read(&m->requests_shed[DS4_SHED_SLOW_READER]) ==
                shed0 + 1);
    TEST_ASSERT(ds4_metric_read(&m->out_backlog_bytes) == backlog0);
    {
        char rb[8];
        TEST_ASSERT(recv(sv[1], rb, sizeof(rb), MSG_DONTWAIT) < 0);
    }

    /* Leg C -- transport dead between publish and commit: the record
     * publishes, the pre-commit probe finds the peer gone, and the record
     * rolls to REPLAY_ONLY (ids stay reserved for mint uniqueness). */
    j.client_gone = false;
    j.outcome = JOB_OUT_COMPLETED;
    close(sv[1]);   /* orderly FIN: client_disconnected() sees it */
    {
        tool_calls calls = {0};
        tool_call tc = {0};
        tc.id = xstrdup("toolu_txnC");
        tool_calls_push(&calls, tc);
        serial_terminal_commit(&s, &j, API_ANTHROPIC, &calls, 5, 70, &tb, "t");
        tool_calls_free(&calls);
    }
    TEST_ASSERT(!anthropic_live_has_call_id(&s, "toolu_txnC"));
    TEST_ASSERT(cont_registry_id_known(&s, "toolu_txnC"));
    TEST_ASSERT(s.creg.n_live == 0);   /* leg C's publish superseded leg A */
    TEST_ASSERT(j.client_gone);        /* Inc 2c law: settle counts CANCELED */
    TEST_ASSERT(ds4_metric_read(&m->out_backlog_bytes) == backlog0);

    buf_free(&tb);
    close(sv[0]);
    cont_registry_free(&s);
    pthread_mutex_destroy(&s.tool_mu);
}

/* Inc 5c: BATCH_BANK publication + claim -- per-bank supersession, owner
 * isolation from the serial tip, the caller-side generation/frontier
 * equality that refuses the queued-eviction ABA, and lazy TTL covering
 * bank records. */
static void test_cont_registry_bank_publish_claim(void) {
    server s = {0};
    pthread_mutex_init(&s.tool_mu, NULL);

    {
        tool_calls calls = {0};
        tool_call tc = {0};
        tc.id = xstrdup("toolu_bk1");
        tool_calls_push(&calls, tc);
        cont_registry_publish_bank(&s, API_ANTHROPIC, &calls, 2, 7, 100);
        tool_calls_free(&calls);
    }
    TEST_ASSERT(anthropic_live_has_call_id(&s, "toolu_bk1"));
    TEST_ASSERT(!responses_live_has_call_id(&s, "toolu_bk1"));
    TEST_ASSERT(s.creg.serial_live == NULL);   /* bank tips never claim the serial slot */

    /* Claim returns the record's exact execution reference; the Inc 6
     * caller admits only on equality with the LIVE bank state -- a bumped
     * generation (bank evicted/reused since publication: the ABA) or a
     * moved frontier refuses. */
    stop_list ids = {0};
    id_list_push_unique(&ids, "toolu_bk1");
    int bank = -1;
    uint64_t gen = 0;
    int frontier = 0;
    TEST_ASSERT(cont_registry_bank_claim(&s, API_ANTHROPIC, &ids,
                                         &bank, &gen, &frontier));
    TEST_ASSERT(bank == 2 && gen == 7 && frontier == 100);
    TEST_ASSERT(!(gen == 8 && frontier == 100));    /* evicted bank: refuse */
    TEST_ASSERT(!(gen == 7 && frontier == 101));    /* moved frontier: refuse */
    TEST_ASSERT(!cont_registry_bank_claim(&s, API_RESPONSES, &ids,
                                          NULL, NULL, NULL));
    /* The serial resolve never matches a bank record (owner check). */
    TEST_ASSERT(!cont_registry_resolve_serial(&s, API_ANTHROPIC, &ids, 7, 100));

    /* A serial publication coexists with the bank tip; demoting the serial
     * tip leaves the bank record LIVE. */
    {
        tool_calls calls = {0};
        tool_call tc = {0};
        tc.id = xstrdup("toolu_ser1");
        tool_calls_push(&calls, tc);
        cont_registry_publish_serial(&s, API_ANTHROPIC, &calls, 9, 40);
        tool_calls_free(&calls);
    }
    TEST_ASSERT(s.creg.n_live == 2);
    cont_registry_demote_serial(&s);
    TEST_ASSERT(s.creg.n_live == 1);
    TEST_ASSERT(anthropic_live_has_call_id(&s, "toolu_bk1"));

    /* Per-bank supersession: a new turn on bank 2 demotes its old tip; a
     * turn on bank 3 lives beside it. */
    {
        tool_calls calls = {0};
        tool_call tc = {0};
        tc.id = xstrdup("toolu_bk2");
        tool_calls_push(&calls, tc);
        cont_registry_publish_bank(&s, API_ANTHROPIC, &calls, 2, 8, 120);
        tool_calls_free(&calls);
    }
    TEST_ASSERT(!anthropic_live_has_call_id(&s, "toolu_bk1"));
    TEST_ASSERT(anthropic_live_has_call_id(&s, "toolu_bk2"));
    {
        tool_calls calls = {0};
        tool_call tc = {0};
        tc.id = xstrdup("toolu_bk3");
        tool_calls_push(&calls, tc);
        cont_registry_publish_bank(&s, API_RESPONSES, &calls, 3, 2, 80);
        tool_calls_free(&calls);
    }
    TEST_ASSERT(s.creg.n_live == 2);

    /* Publish refuses a dead reference (gen 0 = no live generation, the
     * no-graph stub; frontier 0 = nothing committed). */
    {
        tool_calls calls = {0};
        tool_call tc = {0};
        tc.id = xstrdup("toolu_bk_dead");
        tool_calls_push(&calls, tc);
        cont_registry_publish_bank(&s, API_ANTHROPIC, &calls, 4, 0, 100);
        cont_registry_publish_bank(&s, API_ANTHROPIC, &calls, 4, 5, 0);
        tool_calls_free(&calls);
    }
    TEST_ASSERT(!cont_registry_id_known(&s, "toolu_bk_dead"));

    /* Lazy TTL walks bank records too (they have no eager demote sites). */
    s.creg.ttl_s = 300.0;
    pthread_mutex_lock(&s.tool_mu);
    for (cont_record *rec = s.creg.head; rec; rec = rec->next)
        if (rec->state == CONT_REC_LIVE_FRONTIER)
            rec->publish_time -= 301.0;
    pthread_mutex_unlock(&s.tool_mu);
    TEST_ASSERT(!anthropic_live_has_call_id(&s, "toolu_bk2"));
    TEST_ASSERT(s.creg.n_live == 0);
    TEST_ASSERT(cont_registry_id_known(&s, "toolu_bk2"));

    id_list_free(&ids);
    cont_registry_free(&s);
    pthread_mutex_destroy(&s.tool_mu);
}

/* Inc 6c: bank retention protection -- LIVE-only, grace-scoped, extended by
 * a valid hard pin, never by a demoted record; the hold Retry-After answers
 * the soonest protection lapse. */
static void test_cont_registry_bank_protection(void) {
    server s = {0};
    pthread_mutex_init(&s.tool_mu, NULL);
    s.creg.grace_s = 60.0;
    s.creg.ttl_s = 300.0;
    s.creg.pin_deadline_s = 60.0;

    {
        tool_calls calls = {0};
        tool_call tc = {0};
        tc.id = xstrdup("toolu_prot1");
        tool_calls_push(&calls, tc);
        cont_registry_publish_bank(&s, API_ANTHROPIC, &calls, 5, 3, 200);
        tool_calls_free(&calls);
    }
    const double now = now_sec();
    /* In grace: the record's bank is protected; other banks are not. */
    TEST_ASSERT(cont_registry_bank_protected(&s, 5, now));
    TEST_ASSERT(!cont_registry_bank_protected(&s, 4, now));
    /* Honest Retry-After: bounded by the grace remaining. */
    const int ra = cont_registry_bank_hold_retry(&s, now);
    TEST_ASSERT(ra >= 1 && ra <= 61);
    /* Grace lapsed, no pin: unprotected (still LIVE until TTL -- the claim
     * keeps working; only VICTIM protection ends with grace). */
    pthread_mutex_lock(&s.tool_mu);
    for (cont_record *rec = s.creg.head; rec; rec = rec->next)
        rec->publish_time -= 61.0;
    pthread_mutex_unlock(&s.tool_mu);
    TEST_ASSERT(!cont_registry_bank_protected(&s, 5, now));
    /* A queued T2's hard pin re-protects past grace until its deadline. */
    void *pin = cont_registry_pin_live(&s, API_ANTHROPIC, "toolu_prot1");
    TEST_ASSERT(pin != NULL);
    TEST_ASSERT(cont_registry_bank_protected(&s, 5, now));
    cont_registry_unpin(&s, pin);
    TEST_ASSERT(!cont_registry_bank_protected(&s, 5, now));
    /* A demoted record never protects, pinned or not (state gate first). */
    pin = cont_registry_pin_live(&s, API_ANTHROPIC, "toolu_prot1");
    TEST_ASSERT(pin != NULL);
    pthread_mutex_lock(&s.tool_mu);
    for (cont_record *rec = s.creg.head; rec; rec = rec->next)
        if (rec->state == CONT_REC_LIVE_FRONTIER)
            cont_registry_demote_locked(&s, rec);
    pthread_mutex_unlock(&s.tool_mu);
    TEST_ASSERT(!cont_registry_bank_protected(&s, 5, now));
    cont_registry_unpin(&s, pin);

    cont_registry_free(&s);
    pthread_mutex_destroy(&s.tool_mu);
}

static void test_tool_checkpoint_canonicalization_gate_exact_replay(void) {
    server s;
    memset(&s, 0, sizeof(s));

    tool_calls calls = {0};
    tool_call tc = {0};
    tc.id = xstrdup("call_exact");
    tc.name = xstrdup("bash");
    tc.arguments = xstrdup("{}");
    tool_calls_push(&calls, tc);
    calls.raw_dsml = xstrdup(
        "\n\n" DS4_TOOL_CALLS_START "\n"
        "<｜DSML｜invoke name=\"bash\">\n"
        "</｜DSML｜invoke>\n"
        DS4_TOOL_CALLS_END);

    TEST_ASSERT(!should_canonicalize_tool_checkpoint(&s, &calls));

    s.disable_exact_dsml_tool_replay = true;
    TEST_ASSERT(should_canonicalize_tool_checkpoint(&s, &calls));

    s.disable_exact_dsml_tool_replay = false;
    free(calls.raw_dsml);
    calls.raw_dsml = NULL;
    TEST_ASSERT(should_canonicalize_tool_checkpoint(&s, &calls));

    tool_calls_free(&calls);
}

static void test_responses_live_tail_renders_tool_outputs_only(void) {
    request r;
    request_init(&r, REQ_CHAT, 128);
    r.api = API_RESPONSES;
    r.think_mode = DS4_THINK_LOW;

    chat_msgs msgs = {0};
    chat_msg assistant = {0};
    assistant.role = xstrdup("assistant");
    tool_call tc = {0};
    tc.id = xstrdup("call_live");
    tc.name = xstrdup("exec_command");
    tc.arguments = xstrdup("{\"cmd\":\"pwd\"}");
    tool_calls_push(&assistant.calls, tc);
    chat_msgs_push(&msgs, assistant);

    chat_msg tool = {0};
    tool.role = xstrdup("tool");
    tool.tool_call_id = xstrdup("call_live");
    tool.content = xstrdup("/tmp");
    chat_msgs_push(&msgs, tool);

    responses_prepare_live_continuation(&r, &msgs, NULL);
    TEST_ASSERT(r.responses_live_call_ids.len == 1);
    TEST_ASSERT(!strcmp(r.responses_live_call_ids.v[0], "call_live"));
    TEST_ASSERT(r.responses_live_suffix_text != NULL);
    TEST_ASSERT(!strncmp(r.responses_live_suffix_text,
                         "<｜end▁of▁sentence｜><｜User｜><tool_result>",
                         strlen("<｜end▁of▁sentence｜><｜User｜><tool_result>")));
    TEST_ASSERT(strstr(r.responses_live_suffix_text, "/tmp</tool_result>") != NULL);
    TEST_ASSERT(strstr(r.responses_live_suffix_text, "<｜Assistant｜><think>") != NULL);
    TEST_ASSERT(strstr(r.responses_live_suffix_text, "exec_command") == NULL);

    chat_msgs_free(&msgs);
    request_free(&r);
}

