static void test_thinking_checkpoint_canonical_matches_future_prompt(void) {
    /* Simulate: user sends a single message, thinking mode on, no tools.
     * Model generates reasoning + content.  The next request will drop the
     * reasoning from this turn.  Verify that:
     *   prompt_text[:-len("<think>")] + "</think>" + content + "<|eos|>"
     * equals what render_chat_prompt_text produces for the history. */

    chat_msgs prefix_msgs = {0};
    chat_msg user1 = {0};
    user1.role = xstrdup("user");
    user1.content = xstrdup("What is 2+2?");
    chat_msgs_push(&prefix_msgs, user1);

    /* This is what prompt_text looks like for the first generation */
    char *prompt_text = render_chat_prompt_text(&prefix_msgs, NULL, NULL, DS4_THINK_LOW);
    /* prompt_text should end with <think> */
    size_t pt_len = strlen(prompt_text);
    TEST_ASSERT(pt_len >= 7);
    TEST_ASSERT(!memcmp(prompt_text + pt_len - 7, "<think>", 7));

    /* The model generates: reasoning + </think> + content */
    const char *reasoning = "Let me think... 2+2 = 4";
    const char *content = "The answer is 4.";

    /* Build the canonical checkpoint text (what we'd produce after canonicalization) */
    buf canonical = {0};
    buf_append(&canonical, prompt_text, pt_len - 7);  /* strip <think> */
    buf_puts(&canonical, "</think>");
    buf_puts(&canonical, content);
    buf_puts(&canonical, "<" "\xef\xbd\x9c" "end" "\xe2\x96\x81" "of" "\xe2\x96\x81" "sentence" "\xef\xbd\x9c" ">");

    request r;
    request_init(&r, REQ_CHAT, 128);
    r.think_mode = DS4_THINK_LOW;
    r.prompt_text = xstrdup(prompt_text);
    char *visible = build_toolless_thinking_visible_text(&r, content);
    TEST_ASSERT(visible != NULL);
    TEST_ASSERT(!strcmp(visible, canonical.ptr));
    free(visible);
    request_free(&r);

    /* Now build what the NEXT request would render: history includes this
     * assistant message, plus a new user message.  Extract just the prefix
     * up to and including the eos of the assistant turn. */
    chat_msgs history_msgs = {0};
    chat_msg h_user1 = {0};
    h_user1.role = xstrdup("user");
    h_user1.content = xstrdup("What is 2+2?");
    chat_msgs_push(&history_msgs, h_user1);
    chat_msg h_asst = {0};
    h_asst.role = xstrdup("assistant");
    h_asst.reasoning = xstrdup(reasoning);
    h_asst.content = xstrdup(content);
    chat_msgs_push(&history_msgs, h_asst);
    chat_msg h_user2 = {0};
    h_user2.role = xstrdup("user");
    h_user2.content = xstrdup("Thanks!");
    chat_msgs_push(&history_msgs, h_user2);

    char *future_prompt = render_chat_prompt_text(&history_msgs, NULL, NULL, DS4_THINK_LOW);

    /* The future prompt should START with our canonical text */
    size_t clen = canonical.len;
    TEST_ASSERT(strlen(future_prompt) > clen);
    TEST_ASSERT(!memcmp(future_prompt, canonical.ptr, clen));

    /* And what comes after is the new user turn + assistant prefix */
    const char *rest = future_prompt + clen;
    TEST_ASSERT(strstr(rest, "Thanks!") != NULL);
    TEST_ASSERT(strstr(rest, "<think>") != NULL);  /* new turn starts thinking */

    /* Verify reasoning is NOT in the future prompt for this turn */
    const char *asst_turn = strstr(future_prompt, "<" "\xef\xbd\x9c" "Assistant" "\xef\xbd\x9c" ">");
    TEST_ASSERT(asst_turn != NULL);
    TEST_ASSERT(strstr(future_prompt, reasoning) == NULL);  /* reasoning dropped */

    free(future_prompt);
    buf_free(&canonical);
    free(prompt_text);
    chat_msgs_free(&prefix_msgs);
    chat_msgs_free(&history_msgs);
}

static void test_thinking_canonical_empty_content(void) {
    /* Edge case: model thinks but produces empty content (e.g. tool-less
     * thinking where answer is entirely in reasoning).  Canonical should
     * still be valid: prompt_text[:-7] + "</think><|eos|>" */
    chat_msgs msgs = {0};
    chat_msg user = {0};
    user.role = xstrdup("user");
    user.content = xstrdup("Think about life");
    chat_msgs_push(&msgs, user);

    char *prompt_text = render_chat_prompt_text(&msgs, NULL, NULL, DS4_THINK_LOW);
    size_t pt_len = strlen(prompt_text);

    /* Build canonical with empty content */
    buf canonical = {0};
    buf_append(&canonical, prompt_text, pt_len - 7);
    buf_puts(&canonical, "</think>");
    /* empty content */
    buf_puts(&canonical, "<" "\xef\xbd\x9c" "end" "\xe2\x96\x81" "of" "\xe2\x96\x81" "sentence" "\xef\xbd\x9c" ">");

    /* Future prompt with empty content assistant message */
    chat_msgs history = {0};
    chat_msg h_u = {0};
    h_u.role = xstrdup("user");
    h_u.content = xstrdup("Think about life");
    chat_msgs_push(&history, h_u);
    chat_msg h_a = {0};
    h_a.role = xstrdup("assistant");
    h_a.reasoning = xstrdup("Deep thoughts about existence...");
    h_a.content = xstrdup("");
    chat_msgs_push(&history, h_a);
    chat_msg h_u2 = {0};
    h_u2.role = xstrdup("user");
    h_u2.content = xstrdup("Continue");
    chat_msgs_push(&history, h_u2);

    char *future = render_chat_prompt_text(&history, NULL, NULL, DS4_THINK_LOW);
    TEST_ASSERT(strlen(future) > canonical.len);
    TEST_ASSERT(!memcmp(future, canonical.ptr, canonical.len));
    /* reasoning dropped */
    TEST_ASSERT(strstr(future, "Deep thoughts") == NULL);

    free(future);
    buf_free(&canonical);
    free(prompt_text);
    chat_msgs_free(&msgs);
    chat_msgs_free(&history);
}

static void test_thinking_canonical_multi_turn(void) {
    /* Multi-turn: 3 user messages, 2 assistant responses with reasoning.
     * Both prior assistant turns should have reasoning dropped.
     * The canonical after the SECOND generation should produce text that
     * matches the start of a 3rd-turn future prompt. */
    chat_msgs turn2_prefix = {0};
    chat_msg u1 = {0};
    u1.role = xstrdup("user");
    u1.content = xstrdup("Hello");
    chat_msgs_push(&turn2_prefix, u1);
    chat_msg a1 = {0};
    a1.role = xstrdup("assistant");
    a1.reasoning = xstrdup("first reasoning");
    a1.content = xstrdup("Hi there");
    chat_msgs_push(&turn2_prefix, a1);
    chat_msg u2 = {0};
    u2.role = xstrdup("user");
    u2.content = xstrdup("How are you?");
    chat_msgs_push(&turn2_prefix, u2);

    /* prompt_text for the 2nd generation (includes 1st assistant turn) */
    char *prompt_text = render_chat_prompt_text(&turn2_prefix, NULL, NULL, DS4_THINK_LOW);
    size_t pt_len = strlen(prompt_text);
    TEST_ASSERT(!memcmp(prompt_text + pt_len - 7, "<think>", 7));

    /* 1st turn reasoning is already dropped in this prompt_text */
    TEST_ASSERT(strstr(prompt_text, "first reasoning") == NULL);
    TEST_ASSERT(strstr(prompt_text, "Hi there") != NULL);

    /* After 2nd generation: canonical drops 2nd reasoning too */
    const char *content2 = "I'm doing well";
    buf canonical = {0};
    buf_append(&canonical, prompt_text, pt_len - 7);
    buf_puts(&canonical, "</think>");
    buf_puts(&canonical, content2);
    buf_puts(&canonical, "<" "\xef\xbd\x9c" "end" "\xe2\x96\x81" "of" "\xe2\x96\x81" "sentence" "\xef\xbd\x9c" ">");

    /* Future: 3rd user message arrives */
    chat_msgs future_msgs = {0};
    chat_msg fu1 = {0}; fu1.role = xstrdup("user"); fu1.content = xstrdup("Hello");
    chat_msgs_push(&future_msgs, fu1);
    chat_msg fa1 = {0}; fa1.role = xstrdup("assistant");
    fa1.reasoning = xstrdup("first reasoning");
    fa1.content = xstrdup("Hi there");
    chat_msgs_push(&future_msgs, fa1);
    chat_msg fu2 = {0}; fu2.role = xstrdup("user"); fu2.content = xstrdup("How are you?");
    chat_msgs_push(&future_msgs, fu2);
    chat_msg fa2 = {0}; fa2.role = xstrdup("assistant");
    fa2.reasoning = xstrdup("second reasoning");
    fa2.content = xstrdup(content2);
    chat_msgs_push(&future_msgs, fa2);
    chat_msg fu3 = {0}; fu3.role = xstrdup("user"); fu3.content = xstrdup("Great");
    chat_msgs_push(&future_msgs, fu3);

    char *future = render_chat_prompt_text(&future_msgs, NULL, NULL, DS4_THINK_LOW);
    /* Both reasonings dropped */
    TEST_ASSERT(strstr(future, "first reasoning") == NULL);
    TEST_ASSERT(strstr(future, "second reasoning") == NULL);
    /* Canonical is a prefix of future */
    TEST_ASSERT(strlen(future) > canonical.len);
    TEST_ASSERT(!memcmp(future, canonical.ptr, canonical.len));

    free(future);
    buf_free(&canonical);
    free(prompt_text);
    chat_msgs_free(&turn2_prefix);
    chat_msgs_free(&future_msgs);
}

static void test_thinking_canonical_with_tools_preserves_reasoning(void) {
    /* When tools ARE present, reasoning is preserved in re-render.
     * The toolless thinking live binding should NOT fire (has_tools gate),
     * and the tool-call replay path handles it.  Verify the template
     * preserves reasoning when tool_context is true. */
    const char *tool_schemas = "{\"name\":\"bash\"}";

    chat_msgs msgs = {0};
    chat_msg u = {0};
    u.role = xstrdup("user");
    u.content = xstrdup("run ls");
    chat_msgs_push(&msgs, u);

    char *prompt_text = render_chat_prompt_text(&msgs, tool_schemas, NULL, DS4_THINK_LOW);
    size_t pt_len = strlen(prompt_text);
    TEST_ASSERT(!memcmp(prompt_text + pt_len - 7, "<think>", 7));

    /* With tools, next render KEEPS reasoning */
    chat_msgs history = {0};
    chat_msg hu = {0}; hu.role = xstrdup("user"); hu.content = xstrdup("run ls");
    chat_msgs_push(&history, hu);
    chat_msg ha = {0}; ha.role = xstrdup("assistant");
    ha.reasoning = xstrdup("I should run bash");
    ha.content = xstrdup("Here you go");
    chat_msgs_push(&history, ha);
    chat_msg hu2 = {0}; hu2.role = xstrdup("user"); hu2.content = xstrdup("thanks");
    chat_msgs_push(&history, hu2);

    char *future = render_chat_prompt_text(&history, tool_schemas, NULL, DS4_THINK_LOW);
    /* Reasoning IS preserved when tools present */
    TEST_ASSERT(strstr(future, "I should run bash") != NULL);
    TEST_ASSERT(strstr(future, "<think>I should run bash</think>") != NULL);

    free(future);
    free(prompt_text);
    chat_msgs_free(&msgs);
    chat_msgs_free(&history);
}

static void test_thinking_canonical_non_thinking_mode_noop(void) {
    /* When thinking is disabled (deepseek-chat), prompt_text ends with
     * </think> not <think>.  The toolless thinking live binding is a no-op
     * (early return on memcmp check). */
    chat_msgs msgs = {0};
    chat_msg u = {0};
    u.role = xstrdup("user");
    u.content = xstrdup("Hello");
    chat_msgs_push(&msgs, u);

    char *prompt_text = render_chat_prompt_text(&msgs, NULL, NULL, DS4_THINK_NONE);
    size_t pt_len = strlen(prompt_text);
    /* Should end with </think>, not <think> */
    TEST_ASSERT(pt_len >= 8);
    TEST_ASSERT(!memcmp(prompt_text + pt_len - 8, "</think>", 8));
    /* Does NOT end with <think> */
    TEST_ASSERT(memcmp(prompt_text + pt_len - 7, "<think>", 7) != 0);

    free(prompt_text);
    chat_msgs_free(&msgs);
}

static void test_version_newer_comparisons(void) {
    TEST_ASSERT(version_newer("v0.5.3", "v0.5.2"));
    TEST_ASSERT(version_newer("v1.0.0", "v0.9.9"));
    TEST_ASSERT(!version_newer("v0.5.2", "v0.5.2"));
    TEST_ASSERT(!version_newer("v0.4.9", "v0.5.2"));
    TEST_ASSERT(!version_newer("garbage", "v0.5.2"));
    TEST_ASSERT(version_newer("v0.5.3", "unknown"));
    TEST_ASSERT(!version_newer("v0.5.2", "v0.5.2-14-gabc123"));  /* dev past tag */
    TEST_ASSERT(version_newer("v0.5.3", "v0.5.2-14-gabc123"));
}

/* =========================================================================
 * v0.5.6 Inc 0a: frozen projection oracle.
 *
 * A deterministic token/text TAPE is replayed through each wire surface's
 * CURRENT projector, and the emitted bytes are checked by protocol EVENT
 * VALIDATORS.  These fixtures freeze today's projection behavior so the
 * later typed extraction can prove "old and new projectors consume the same
 * captured tape and emit the same bytes".  They are NOT live-sampled
 * goldens: continuous temp-0 output jitters run-to-run, so live bytes can
 * never be a byte oracle (see local/docs/ds4-api-surface-matrix reference in
 * docs/).  One fixture is deliberately NEGATIVE: the continuous lane
 * projects legacy-Completion streams with the CHAT delta machine; those
 * bytes are recorded as the defect, with the serial projector as the oracle.
 * ========================================================================= */

typedef struct { int token_id; const char *piece; } tape_step;

/* Shared tapes.  The thinking tape starts INSIDE reasoning (the serving
 * prompt ends with the assistant "<think>" primer, so generated text never
 * begins with the open tag).  The UTF-8 tape splits e-acute (0xC3 0xA9)
 * across two steps to freeze the hold-back behavior. */
static const tape_step tape_plain[] = {
    {11, "Hel"}, {12, "lo"}, {13, " wor"}, {14, "ld."},
};
static const tape_step tape_thinking[] = {
    {21, "plan"}, {22, "</think>"}, {23, "Answer"}, {24, " done."},
};
static const tape_step tape_utf8[] = {
    {31, "caf"}, {32, "\xC3"}, {33, "\xA9"}, {34, " ok"},
};

static int test_count_substr(const char *hay, const char *needle) {
    int n = 0;
    const size_t step = strlen(needle);
    while ((hay = strstr(hay, needle)) != NULL) { n++; hay += step; }
    return n;
}

/* Every "data: " record except [DONE] must contain `must_contain` (and not
 * `must_not_contain`); [DONE] must exist and be the last record. */
static void sse_assert_every_data_object(const char *out, const char *must_contain,
                                         const char *must_not_contain) {
    const char *p = out;
    bool saw_done = false;
    int records = 0;
    while ((p = strstr(p, "data: ")) != NULL) {
        p += 6;
        const char *end = strstr(p, "\n\n");
        size_t len = end ? (size_t)(end - p) : strlen(p);
        char *rec = xstrndup(p, len);
        if (!strcmp(rec, "[DONE]")) {
            saw_done = true;
            TEST_ASSERT(strstr(p + len, "data: ") == NULL);
        } else {
            records++;
            TEST_ASSERT(strstr(rec, must_contain) != NULL);
            if (must_not_contain)
                TEST_ASSERT(strstr(rec, must_not_contain) == NULL);
        }
        free(rec);
        p = end ? end + 2 : p + len;
    }
    TEST_ASSERT(records > 0);
    TEST_ASSERT(saw_done);
}

/* Anthropic streams: every "event: NAME" line's data record must declare
 * "type":"NAME", message_start comes first, message_stop last, and block
 * opens/closes balance. */
static void sse_validate_anthropic_stream(const char *out) {
    const char *start = strstr(out, "event: message_start");
    const char *stop = strstr(out, "event: message_stop");
    TEST_ASSERT(start != NULL);
    TEST_ASSERT(stop != NULL);
    TEST_ASSERT(start < stop);
    TEST_ASSERT(test_count_substr(out, "event: content_block_start") ==
                test_count_substr(out, "event: content_block_stop"));
    const char *mdelta = strstr(out, "event: message_delta");
    TEST_ASSERT(mdelta != NULL);
    TEST_ASSERT(mdelta < stop);
    const char *p = out;
    while ((p = strstr(p, "event: ")) != NULL) {
        char name[48] = {0};
        p += 7;
        size_t n = strcspn(p, "\r\n");
        if (n >= sizeof(name)) n = sizeof(name) - 1;
        memcpy(name, p, n);
        const char *data = strstr(p, "data: ");
        TEST_ASSERT(data != NULL);
        const char *rec_end = strstr(data, "\n\n");
        char *rec = xstrndup(data, rec_end ? (size_t)(rec_end - data) : strlen(data));
        char typekey[64];
        snprintf(typekey, sizeof(typekey), "\"type\":\"%s\"", name);
        TEST_ASSERT(strstr(rec, typekey) != NULL);
        free(rec);
    }
}

/* Responses streams: response.created first, response.completed last,
 * item added/done balanced, and the per-event sequence_number Codex
 * consumes is contiguous from 0. */
static void sse_validate_responses_stream(const char *out) {
    const char *created = strstr(out, "\"type\":\"response.created\"");
    const char *completed = strstr(out, "\"type\":\"response.completed\"");
    TEST_ASSERT(created != NULL);
    TEST_ASSERT(completed != NULL);
    TEST_ASSERT(created < completed);
    TEST_ASSERT(strstr(out, "\"type\":\"response.") < completed);
    TEST_ASSERT(test_count_substr(out, "\"type\":\"response.output_item.added\"") ==
                test_count_substr(out, "\"type\":\"response.output_item.done\""));
    int expect = 0;
    const char *p = out;
    while ((p = strstr(p, "\"sequence_number\":")) != NULL) {
        p += strlen("\"sequence_number\":");
        TEST_ASSERT(atoi(p) == expect);
        expect++;
    }
    TEST_ASSERT(expect > 0);
}

/* The LEGACY predicates, frozen as the route oracle (plan Inc 0a: "record
 * current route decisions").  job_is_batchable excludes Anthropic and
 * Responses by API identity alone -- the pre-promotion table.  Since Inc 3a
 * DISPATCH no longer matches this for Anthropic buffered (see
 * route_expected_oracle, the legacy tree plus exactly one promotion); these
 * predicates must stay frozen so the exhaustive gate can still name every
 * unintended lane change.  The surface classifier must also keep OpenAI
 * Chat and legacy Completion apart -- they project different stream objects
 * (review gap G1). */
static void test_route_decisions_record_current_dispatch(void) {
    request r;

    /* Anthropic: never batchable, never static -- by API identity alone. */
    request_init(&r, REQ_CHAT, 128);
    r.api = API_ANTHROPIC;
    r.temperature = 0.0f;
    r.think_mode = DS4_THINK_NONE;
    TEST_ASSERT(!job_is_batchable(&r));
    TEST_ASSERT(!job_is_static_batchable(&r));
    r.stream = true;
    TEST_ASSERT(!job_is_batchable(&r));
    TEST_ASSERT(route_metrics_surface(&r) == ROUTE_SURFACE_ANTHROPIC_MESSAGES);
    request_free(&r);

    /* Responses: same exclusion, same line. */
    request_init(&r, REQ_CHAT, 128);
    r.api = API_RESPONSES;
    r.temperature = 0.0f;
    r.think_mode = DS4_THINK_NONE;
    TEST_ASSERT(!job_is_batchable(&r));
    TEST_ASSERT(!job_is_static_batchable(&r));
    TEST_ASSERT(route_metrics_surface(&r) == ROUTE_SURFACE_OPENAI_RESPONSES);
    request_free(&r);

    /* OpenAI chat: batchable; static only when buffered+greedy+non-thinking
     * with no stops/tools. */
    request_init(&r, REQ_CHAT, 128);
    r.api = API_OPENAI;
    r.temperature = 0.0f;
    r.think_mode = DS4_THINK_NONE;
    TEST_ASSERT(job_is_batchable(&r));
    TEST_ASSERT(job_is_static_batchable(&r));
    TEST_ASSERT(route_metrics_surface(&r) == ROUTE_SURFACE_OPENAI_CHAT);
    r.stream = true;
    TEST_ASSERT(job_is_batchable(&r));
    TEST_ASSERT(!job_is_static_batchable(&r));
    r.stream = false;
    r.temperature = 0.7f;
    TEST_ASSERT(!job_is_static_batchable(&r));
    r.temperature = 0.0f;
    r.think_mode = DS4_THINK_LOW;
    TEST_ASSERT(!job_is_static_batchable(&r));
    request_free(&r);

    /* OpenAI legacy completion: batchable (that is what makes the negative
     * fixture below reachable on the continuous lane); distinct surface. */
    request_init(&r, REQ_COMPLETION, 128);
    r.api = API_OPENAI;
    r.stream = true;
    TEST_ASSERT(job_is_batchable(&r));
    TEST_ASSERT(route_metrics_surface(&r) == ROUTE_SURFACE_OPENAI_COMPLETION);
    request_free(&r);
}

/* Inc 2a: the two surface classifiers (Inc 0a metrics enum, Inc 1 wire enum)
 * are the same (api, kind) mapping -- their index orders were aligned by
 * construction, and routing now consumes both interchangeably. */
static void test_route_surface_mapping_agrees(void) {
    static const api_style apis[] = { API_OPENAI, API_ANTHROPIC, API_RESPONSES };
    static const req_kind kinds[] = { REQ_CHAT, REQ_COMPLETION };
    for (size_t a = 0; a < sizeof(apis) / sizeof(apis[0]); a++) {
        for (size_t k = 0; k < sizeof(kinds) / sizeof(kinds[0]); k++) {
            request r;
            request_init(&r, kinds[k], 128);
            r.api = apis[a];
            TEST_ASSERT(route_metrics_surface(&r) == (int)wire_surface_for(&r));
            request_free(&r);
        }
    }
}

/* Inc 2a: request_compute_needs bit by bit, including the two documented
 * scoping decisions (CORRECTIVE_RECOVERY non-OpenAI-only, PREFILL_ONLY
 * Anthropic-only) and the never-computed DURABLE bit. */
static void test_request_compute_needs_matrix(void) {
    request r;

    request_init(&r, REQ_CHAT, 128);
    r.api = API_OPENAI; r.temperature = 0.0f; r.think_mode = DS4_THINK_NONE;
    TEST_ASSERT(request_compute_needs(&r) == 0);
    r.stream = true;
    TEST_ASSERT(request_compute_needs(&r) == DS4_NEED_STREAMING);
    r.temperature = 0.7f;
    TEST_ASSERT(request_compute_needs(&r) ==
                (DS4_NEED_STREAMING | DS4_NEED_PER_ROW_SAMPLING));
    r.stream = false; r.temperature = 0.0f;
    r.think_mode = DS4_THINK_LOW;
    TEST_ASSERT(request_compute_needs(&r) == DS4_NEED_THINKING);
    r.think_mode = DS4_THINK_NONE;
    id_list_push_unique(&r.stops, "STOP");
    TEST_ASSERT(request_compute_needs(&r) == DS4_NEED_STOP_SCAN);
    stop_list_clear(&r.stops);
    r.return_token_ids = true;
    TEST_ASSERT(request_compute_needs(&r) == DS4_NEED_TOKEN_IDS);
    r.return_token_ids = false;
    /* OpenAI tools: TOOL_SCAN alone -- no continuation/corrective bits (the
     * v0.2 shipped continuous-tools scoping). */
    r.has_tools = true;
    TEST_ASSERT(request_compute_needs(&r) == DS4_NEED_TOOL_SCAN);
    r.has_tools = false;
    /* OpenAI explicit-zero budget is NOT the Anthropic prewarm contract. */
    r.max_tokens_set = true; r.max_tokens = 0;
    TEST_ASSERT(request_compute_needs(&r) == 0);
    request_free(&r);

    request_init(&r, REQ_CHAT, 128);
    r.api = API_ANTHROPIC; r.temperature = 0.0f; r.think_mode = DS4_THINK_NONE;
    r.has_tools = true;
    TEST_ASSERT(request_compute_needs(&r) ==
                (DS4_NEED_TOOL_SCAN | DS4_NEED_CONTINUATION_PUBLISH |
                 DS4_NEED_CORRECTIVE_RECOVERY));
    r.stream = true;   /* streaming tool gen: no buffered corrective retry */
    TEST_ASSERT(request_compute_needs(&r) ==
                (DS4_NEED_STREAMING | DS4_NEED_TOOL_SCAN |
                 DS4_NEED_CONTINUATION_PUBLISH));
    r.stream = false; r.has_tools = false;
    r.anthropic_requires_live_tool_state = true;
    TEST_ASSERT(request_compute_needs(&r) == DS4_NEED_LIVE_FRONTIER);
    /* Inc 6b: a BANK-owned pin flips the bit to the cont lane's frontier. */
    r.live_state_bank_owned = true;
    TEST_ASSERT(request_compute_needs(&r) == DS4_NEED_BANK_FRONTIER);
    r.live_state_bank_owned = false;
    r.anthropic_requires_live_tool_state = false;
    /* Anthropic cache-prewarm: explicit zero = prefill-only; the omitted
     * default (parser preloads max_tokens) is not. */
    r.max_tokens_set = true; r.max_tokens = 0;
    TEST_ASSERT(request_compute_needs(&r) == DS4_NEED_PREFILL_ONLY);
    r.max_tokens_set = false; r.max_tokens = 128;
    TEST_ASSERT(request_compute_needs(&r) == 0);
    request_free(&r);

    request_init(&r, REQ_CHAT, 128);
    r.api = API_RESPONSES; r.temperature = 0.0f; r.think_mode = DS4_THINK_NONE;
    r.responses_requires_live_tool_state = true;
    TEST_ASSERT(request_compute_needs(&r) == DS4_NEED_LIVE_FRONTIER);
    /* Inc 6b: bank-owned -> the cont frontier bit ... */
    r.live_state_bank_owned = true;
    TEST_ASSERT(request_compute_needs(&r) == DS4_NEED_BANK_FRONTIER);
    /* ... but live REASONING state is serial-only visible-state machinery,
     * so it keeps the serial bit even alongside a bank-owned pin. */
    r.responses_requires_live_reasoning = true;
    TEST_ASSERT(request_compute_needs(&r) == DS4_NEED_LIVE_FRONTIER);
    r.responses_requires_live_reasoning = false;
    r.live_state_bank_owned = false;
    r.responses_requires_live_tool_state = false;
    r.responses_requires_live_reasoning = true;
    TEST_ASSERT(request_compute_needs(&r) == DS4_NEED_LIVE_FRONTIER);
    request_free(&r);
}

/* Inc 2a, plan §6.2: route_decide's LANE equals the legacy worker_main tree
 * over the exhaustive coherent feature cross-product and every availability
 * scenario.  The oracle reproduces the old dispatch verbatim from the
 * retained predicates -- if either side drifts, a row names the shape. */
static int route_legacy_oracle(const request *r, bool coalesce_on,
                               bool have_cont, int seq_cap) {
    if (coalesce_on && job_is_batchable(r)) {
        if (have_cont && r->prompt.len > 0 && r->prompt.len <= seq_cap)
            return ROUTE_LANE_CONTINUOUS;
        if (job_is_static_batchable(r)) return ROUTE_LANE_STATIC;
        return ROUTE_LANE_SERIAL;
    }
    return ROUTE_LANE_SERIAL;
}

/* Inc 3a/3b/3d/4b/4c: the expected table is the LEGACY tree plus EXACTLY
 * the promoted-surface rows -- Anthropic and Responses non-tool shapes,
 * buffered (3a/3b) AND streaming (4b/4c), ride continuous when they fit,
 * and their NEEDS-FREE shapes take the same static fallbacks (3d; the
 * static writer is surface-typed).  Token-id echo keeps its
 * streaming-chat-only projection constraint on every surface.  Everything
 * else must stay bit-identical to the legacy oracle, which is the
 * strongest statement of "no other request changed lane".
 * Inc 6a: this is now the table the TOOL switches alone must restore. */
static int route_inc5_oracle(const request *r, bool coalesce_on,
                             bool have_cont, int seq_cap) {
    const uint32_t needs = request_compute_needs(r);
    if (coalesce_on && (r->api == API_ANTHROPIC || r->api == API_RESPONSES) &&
        (needs & ~ROUTE_CONT_MASK) == 0 &&
        !(needs & DS4_NEED_TOKEN_IDS)) {
        if (have_cont && r->prompt.len > 0 && r->prompt.len <= seq_cap)
            return ROUTE_LANE_CONTINUOUS;
        if (needs == 0) return ROUTE_LANE_STATIC;   /* Inc 3d */
    }
    return route_legacy_oracle(r, coalesce_on, have_cont, seq_cap);
}

/* Inc 6a/6b: the Inc 5 table plus EXACTLY two promotions -- a STREAMING
 * tool turn on a promoted surface rides continuous (publication is the 5c
 * bank publish at the cont finalize), and a BANK-owned continuation rides
 * continuous (the claim admission is its consumer).  Buffered tool turns
 * keep the serial corrective hold; serial-owned live frontiers stay
 * serial. */
static int route_expected_oracle(const request *r, bool coalesce_on,
                                 bool have_cont, int seq_cap) {
    const uint32_t needs = request_compute_needs(r);
    uint32_t mask = ROUTE_CONT_MASK | DS4_NEED_BANK_FRONTIER;
    if (r->stream) mask |= DS4_NEED_CONTINUATION_PUBLISH;
    if (coalesce_on && (r->api == API_ANTHROPIC || r->api == API_RESPONSES) &&
        (needs & ~mask) == 0 &&
        !(needs & DS4_NEED_TOKEN_IDS)) {
        if (have_cont && r->prompt.len > 0 && r->prompt.len <= seq_cap)
            return ROUTE_LANE_CONTINUOUS;
        if (needs == 0) return ROUTE_LANE_STATIC;   /* Inc 3d */
    }
    return route_legacy_oracle(r, coalesce_on, have_cont, seq_cap);
}

static void test_route_decide_matches_legacy_exhaustive(void) {
    static const struct { api_style api; req_kind kind; } surfs[] = {
        { API_OPENAI, REQ_CHAT }, { API_OPENAI, REQ_COMPLETION },
        { API_ANTHROPIC, REQ_CHAT }, { API_RESPONSES, REQ_CHAT },
    };
    static const int lens[] = { 0, 16, 4096, 4097 };
    static const struct { bool coalesce, have_cont; } envs[] = {
        { true, true }, { true, false }, { false, true }, { false, false },
    };
    int rows = 0;
    for (size_t sf = 0; sf < sizeof(surfs) / sizeof(surfs[0]); sf++)
    for (int stream = 0; stream < 2; stream++)
    for (int hot = 0; hot < 2; hot++)
    for (int think = 0; think < 2; think++)
    for (int stops = 0; stops < 2; stops++)
    for (int tools = 0; tools < 2; tools++)
    for (int echo = 0; echo < 2; echo++)
    for (int live = 0; live < 2; live++)
    for (int bankown = 0; bankown < 2; bankown++)
    for (int zero = 0; zero < 2; zero++) {
        /* Field coherence: live-continuation evidence exists only on the
         * surfaces whose parsers produce it; a bank-owned pin (Inc 6b)
         * exists only alongside that evidence. */
        if (live && surfs[sf].api == API_OPENAI) continue;
        if (bankown && !live) continue;
        request r;
        request_init(&r, surfs[sf].kind, 128);
        r.api = surfs[sf].api;
        r.stream = stream != 0;
        r.temperature = hot ? 0.7f : 0.0f;
        r.think_mode = think ? DS4_THINK_LOW : DS4_THINK_NONE;
        if (stops) id_list_push_unique(&r.stops, "STOP");
        r.has_tools = tools != 0;
        r.return_token_ids = echo != 0;
        if (live) {
            if (r.api == API_ANTHROPIC) r.anthropic_requires_live_tool_state = true;
            else                        r.responses_requires_live_tool_state = true;
            r.live_state_bank_owned = bankown != 0;
        }
        if (zero) { r.max_tokens_set = true; r.max_tokens = 0; }
        const uint32_t needs = request_compute_needs(&r);
        TEST_ASSERT((needs & DS4_NEED_DURABLE_RESPONSE) == 0);
        for (size_t li = 0; li < sizeof(lens) / sizeof(lens[0]); li++) {
            r.prompt.len = lens[li];   /* length drives routing; tokens never do */
            for (size_t ei = 0; ei < sizeof(envs) / sizeof(envs[0]); ei++) {
                ds4_route_env env = {
                    .coalesce = envs[ei].coalesce, .have_cont = envs[ei].have_cont,
                    .cont_anthropic = true, .cont_responses = true,
                    .cont_tools_anthropic = true, .cont_tools_responses = true,
                    .seq_cap = 4096, .prompt_len = lens[li],
                };
                ds4_route_decision d = route_decide(needs, wire_surface_for(&r), &env);
                TEST_ASSERT(d.lane != ROUTE_LANE_NONE);
                TEST_ASSERT(d.lane == route_expected_oracle(&r, envs[ei].coalesce,
                                                            envs[ei].have_cont, 4096));
                /* Inc 6a: the TOOL switches alone restore the Inc 5 table. */
                env.cont_tools_anthropic = false;
                env.cont_tools_responses = false;
                d = route_decide(needs, wire_surface_for(&r), &env);
                TEST_ASSERT(d.lane == route_inc5_oracle(&r, envs[ei].coalesce,
                                                        envs[ei].have_cont, 4096));
                /* The §7 kill switches restore the LEGACY table exactly
                 * (tool switches without their base do nothing). */
                env.cont_anthropic = false;
                env.cont_responses = false;
                env.cont_tools_anthropic = true;
                env.cont_tools_responses = true;
                d = route_decide(needs, wire_surface_for(&r), &env);
                TEST_ASSERT(d.lane == route_legacy_oracle(&r, envs[ei].coalesce,
                                                          envs[ei].have_cont, 4096));
                rows++;
            }
        }
        r.prompt.len = 0;
        request_free(&r);
    }
    /* Inc 6b: the bankown dimension (coherent only alongside live) grows
     * the promoted surfaces from 256 to 384 coherent shapes each. */
    TEST_ASSERT(rows == (2 * 128 + 2 * 384) * 16);
}

/* Inc 2a, plan §6.2: exact {lane, first-reason} rows for the canonical
 * shapes -- the refusal/fallback reason is contract now, not just the lane. */
static void test_route_decide_reason_table(void) {
    const ds4_route_env on     = { .coalesce = true,  .have_cont = true,  .cont_anthropic = true, .cont_responses = true, .cont_tools_anthropic = true, .cont_tools_responses = true, .seq_cap = 4096, .prompt_len = 16 };
    const ds4_route_env no_ctx = { .coalesce = true,  .have_cont = false, .cont_anthropic = true, .cont_responses = true, .cont_tools_anthropic = true, .cont_tools_responses = true, .seq_cap = 0,    .prompt_len = 16 };
    const ds4_route_env off    = { .coalesce = false, .have_cont = true,  .cont_anthropic = true, .cont_responses = true, .cont_tools_anthropic = true, .cont_tools_responses = true, .seq_cap = 4096, .prompt_len = 16 };
    ds4_route_env big = on;   big.prompt_len = 4097;
    ds4_route_env empty = on; empty.prompt_len = 0;
    ds4_route_env anth_off = on; anth_off.cont_anthropic = false;
    ds4_route_env resp_off = on; resp_off.cont_responses = false;
    ds4_route_decision d;

    d = route_decide(0, DS4_WIRE_OPENAI_CHAT, &on);
    TEST_ASSERT(d.lane == ROUTE_LANE_CONTINUOUS && d.reason == ROUTE_REASON_CONT);
    d = route_decide(DS4_NEED_STREAMING, DS4_WIRE_OPENAI_CHAT, &no_ctx);
    TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_CONT_UNAVAILABLE);
    d = route_decide(0, DS4_WIRE_OPENAI_CHAT, &no_ctx);
    TEST_ASSERT(d.lane == ROUTE_LANE_STATIC && d.reason == ROUTE_REASON_STATIC_NO_CONT);
    d = route_decide(0, DS4_WIRE_OPENAI_CHAT, &big);
    TEST_ASSERT(d.lane == ROUTE_LANE_STATIC && d.reason == ROUTE_REASON_STATIC_PROMPT_BOUNDS);
    d = route_decide(0, DS4_WIRE_OPENAI_CHAT, &empty);
    TEST_ASSERT(d.lane == ROUTE_LANE_STATIC && d.reason == ROUTE_REASON_STATIC_PROMPT_BOUNDS);
    d = route_decide(0, DS4_WIRE_OPENAI_CHAT, &off);
    TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_COALESCE_OFF);
    /* token-id echo: continuous only as streaming chat */
    d = route_decide(DS4_NEED_TOKEN_IDS | DS4_NEED_STREAMING, DS4_WIRE_OPENAI_CHAT, &on);
    TEST_ASSERT(d.lane == ROUTE_LANE_CONTINUOUS && d.reason == ROUTE_REASON_CONT);
    d = route_decide(DS4_NEED_TOKEN_IDS, DS4_WIRE_OPENAI_CHAT, &on);
    TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_TOKEN_IDS_PROJECTION);
    d = route_decide(DS4_NEED_TOKEN_IDS | DS4_NEED_STREAMING, DS4_WIRE_OPENAI_COMPLETION, &on);
    TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_TOKEN_IDS_PROJECTION);
    /* tools: chat rides continuous (v0.2 shipped); completion kind stays serial */
    d = route_decide(DS4_NEED_TOOL_SCAN, DS4_WIRE_OPENAI_CHAT, &on);
    TEST_ASSERT(d.lane == ROUTE_LANE_CONTINUOUS && d.reason == ROUTE_REASON_CONT);
    d = route_decide(DS4_NEED_TOOL_SCAN, DS4_WIRE_OPENAI_COMPLETION, &on);
    TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_TOOLS_COMPLETION);
    /* Inc 3a: Anthropic BUFFERED rides continuous (thinking/stops/sampling
     * included -- all inside the cont mask); the kill switch restores the
     * legacy surface refusal. */
    d = route_decide(0, DS4_WIRE_ANTHROPIC, &on);
    TEST_ASSERT(d.lane == ROUTE_LANE_CONTINUOUS && d.reason == ROUTE_REASON_CONT);
    d = route_decide(DS4_NEED_THINKING | DS4_NEED_STOP_SCAN | DS4_NEED_PER_ROW_SAMPLING,
                     DS4_WIRE_ANTHROPIC, &on);
    TEST_ASSERT(d.lane == ROUTE_LANE_CONTINUOUS && d.reason == ROUTE_REASON_CONT);
    d = route_decide(0, DS4_WIRE_ANTHROPIC, &anth_off);
    TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_SURFACE);
    /* Inc 3b: Responses BUFFERED rides continuous; its kill switch is
     * independent of Anthropic's. */
    d = route_decide(0, DS4_WIRE_RESPONSES, &on);
    TEST_ASSERT(d.lane == ROUTE_LANE_CONTINUOUS && d.reason == ROUTE_REASON_CONT);
    d = route_decide(DS4_NEED_THINKING | DS4_NEED_PER_ROW_SAMPLING, DS4_WIRE_RESPONSES, &on);
    TEST_ASSERT(d.lane == ROUTE_LANE_CONTINUOUS && d.reason == ROUTE_REASON_CONT);
    d = route_decide(0, DS4_WIRE_RESPONSES, &resp_off);
    TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_SURFACE);
    d = route_decide(0, DS4_WIRE_ANTHROPIC, &resp_off);   /* switches are per-surface */
    TEST_ASSERT(d.lane == ROUTE_LANE_CONTINUOUS && d.reason == ROUTE_REASON_CONT);
    d = route_decide(0, DS4_WIRE_RESPONSES, &anth_off);
    TEST_ASSERT(d.lane == ROUTE_LANE_CONTINUOUS && d.reason == ROUTE_REASON_CONT);
    /* Inc 4b: Anthropic no-tool STREAMING rides continuous (thinking/stops
     * inside the cont mask ride with it); the kill switch still restores
     * the legacy refusal, and a streaming shape that cannot ride cont goes
     * SERIAL (never static -- STREAMING is outside the static mask). */
    d = route_decide(DS4_NEED_STREAMING, DS4_WIRE_ANTHROPIC, &on);
    TEST_ASSERT(d.lane == ROUTE_LANE_CONTINUOUS && d.reason == ROUTE_REASON_CONT);
    d = route_decide(DS4_NEED_STREAMING | DS4_NEED_THINKING | DS4_NEED_STOP_SCAN,
                     DS4_WIRE_ANTHROPIC, &on);
    TEST_ASSERT(d.lane == ROUTE_LANE_CONTINUOUS && d.reason == ROUTE_REASON_CONT);
    d = route_decide(DS4_NEED_STREAMING, DS4_WIRE_ANTHROPIC, &anth_off);
    TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_SURFACE);
    d = route_decide(DS4_NEED_STREAMING, DS4_WIRE_ANTHROPIC, &no_ctx);
    TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_CONT_UNAVAILABLE);
    d = route_decide(DS4_NEED_STREAMING, DS4_WIRE_ANTHROPIC, &big);
    TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_CONT_UNAVAILABLE);
    /* Inc 4c: Responses no-tool STREAMING rides continuous under its own
     * switch; unfit streaming shapes go SERIAL, never static. */
    d = route_decide(DS4_NEED_STREAMING, DS4_WIRE_RESPONSES, &on);
    TEST_ASSERT(d.lane == ROUTE_LANE_CONTINUOUS && d.reason == ROUTE_REASON_CONT);
    d = route_decide(DS4_NEED_STREAMING | DS4_NEED_THINKING, DS4_WIRE_RESPONSES, &on);
    TEST_ASSERT(d.lane == ROUTE_LANE_CONTINUOUS && d.reason == ROUTE_REASON_CONT);
    d = route_decide(DS4_NEED_STREAMING, DS4_WIRE_RESPONSES, &resp_off);
    TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_SURFACE);
    d = route_decide(DS4_NEED_STREAMING, DS4_WIRE_RESPONSES, &no_ctx);
    TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_CONT_UNAVAILABLE);
    d = route_decide(DS4_NEED_STREAMING, DS4_WIRE_RESPONSES, &big);
    TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_CONT_UNAVAILABLE);
    /* Inc 3d: a promoted surface that cannot ride cont takes the same
     * static fallbacks for NEEDS-FREE shapes (the static writer has been
     * surface-typed since Inc 1); any cont-mask need still means SERIAL
     * (CONT_UNAVAILABLE -- static is argmax-only with no scanning), and a
     * switched-off surface drops out of BOTH batched lanes (legacy). */
    d = route_decide(0, DS4_WIRE_ANTHROPIC, &big);
    TEST_ASSERT(d.lane == ROUTE_LANE_STATIC && d.reason == ROUTE_REASON_STATIC_PROMPT_BOUNDS);
    d = route_decide(0, DS4_WIRE_ANTHROPIC, &no_ctx);
    TEST_ASSERT(d.lane == ROUTE_LANE_STATIC && d.reason == ROUTE_REASON_STATIC_NO_CONT);
    d = route_decide(0, DS4_WIRE_RESPONSES, &big);
    TEST_ASSERT(d.lane == ROUTE_LANE_STATIC && d.reason == ROUTE_REASON_STATIC_PROMPT_BOUNDS);
    d = route_decide(DS4_NEED_STOP_SCAN, DS4_WIRE_ANTHROPIC, &no_ctx);
    TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_CONT_UNAVAILABLE);
    d = route_decide(DS4_NEED_THINKING, DS4_WIRE_RESPONSES, &big);
    TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_CONT_UNAVAILABLE);
    {
        ds4_route_env anth_off_noctx = no_ctx; anth_off_noctx.cont_anthropic = false;
        d = route_decide(0, DS4_WIRE_ANTHROPIC, &anth_off_noctx);
        TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_SURFACE);
        ds4_route_env resp_off_noctx = no_ctx; resp_off_noctx.cont_responses = false;
        d = route_decide(0, DS4_WIRE_RESPONSES, &resp_off_noctx);
        TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_SURFACE);
    }
    /* Inc 6a: a STREAMING tool turn on a tool-promoted surface rides cont;
     * the per-feature switch, the base surface switch, and missing/unfit
     * cont each restore the hold (semantic reason when a switch holds it,
     * cont_unavailable when the lane itself cannot take it).  BUFFERED tool
     * turns stay serial even fully switched on (the corrective contract). */
    {
        const uint32_t stream_tools = DS4_NEED_STREAMING | DS4_NEED_TOOL_SCAN |
                                      DS4_NEED_CONTINUATION_PUBLISH;
        d = route_decide(stream_tools, DS4_WIRE_ANTHROPIC, &on);
        TEST_ASSERT(d.lane == ROUTE_LANE_CONTINUOUS && d.reason == ROUTE_REASON_CONT);
        d = route_decide(stream_tools | DS4_NEED_THINKING | DS4_NEED_PER_ROW_SAMPLING |
                         DS4_NEED_STOP_SCAN, DS4_WIRE_ANTHROPIC, &on);
        TEST_ASSERT(d.lane == ROUTE_LANE_CONTINUOUS && d.reason == ROUTE_REASON_CONT);
        d = route_decide(stream_tools, DS4_WIRE_RESPONSES, &on);
        TEST_ASSERT(d.lane == ROUTE_LANE_CONTINUOUS && d.reason == ROUTE_REASON_CONT);
        ds4_route_env tools_off_a = on; tools_off_a.cont_tools_anthropic = false;
        d = route_decide(stream_tools, DS4_WIRE_ANTHROPIC, &tools_off_a);
        TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_NEED_CONTINUATION_PUBLISH);
        d = route_decide(stream_tools, DS4_WIRE_RESPONSES, &tools_off_a);   /* per-surface */
        TEST_ASSERT(d.lane == ROUTE_LANE_CONTINUOUS && d.reason == ROUTE_REASON_CONT);
        ds4_route_env tools_off_r = on; tools_off_r.cont_tools_responses = false;
        d = route_decide(stream_tools, DS4_WIRE_RESPONSES, &tools_off_r);
        TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_NEED_CONTINUATION_PUBLISH);
        d = route_decide(stream_tools, DS4_WIRE_ANTHROPIC, &anth_off);   /* base off wins */
        TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_NEED_CONTINUATION_PUBLISH);
        d = route_decide(stream_tools, DS4_WIRE_ANTHROPIC, &no_ctx);
        TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_CONT_UNAVAILABLE);
        d = route_decide(stream_tools, DS4_WIRE_ANTHROPIC, &big);
        TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_CONT_UNAVAILABLE);
        d = route_decide(stream_tools, DS4_WIRE_ANTHROPIC, &off);
        TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_COALESCE_OFF);
        /* Inc 6b: BANK-owned continuations ride cont when tool-promoted,
         * with a DISTINCT accept reason (the gate's engagement oracle);
         * switched off (or no cont) they degrade to the serial lane, whose
         * resolve answers the honest 409.  A buffered T2 that redeclares
         * tools keeps the buffered corrective hold (documented mixed-shape
         * degrade: 409 -> full replay). */
        d = route_decide(DS4_NEED_BANK_FRONTIER, DS4_WIRE_ANTHROPIC, &on);
        TEST_ASSERT(d.lane == ROUTE_LANE_CONTINUOUS && d.reason == ROUTE_REASON_CONT_BANK);
        d = route_decide(DS4_NEED_BANK_FRONTIER | stream_tools, DS4_WIRE_RESPONSES, &on);
        TEST_ASSERT(d.lane == ROUTE_LANE_CONTINUOUS && d.reason == ROUTE_REASON_CONT_BANK);
        d = route_decide(DS4_NEED_BANK_FRONTIER | DS4_NEED_TOOL_SCAN |
                         DS4_NEED_CONTINUATION_PUBLISH | DS4_NEED_CORRECTIVE_RECOVERY,
                         DS4_WIRE_ANTHROPIC, &on);
        TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_NEED_CONTINUATION_PUBLISH);
        d = route_decide(DS4_NEED_BANK_FRONTIER, DS4_WIRE_ANTHROPIC, &tools_off_a);
        TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_NEED_LIVE_FRONTIER);
        d = route_decide(DS4_NEED_BANK_FRONTIER, DS4_WIRE_ANTHROPIC, &anth_off);
        TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_NEED_LIVE_FRONTIER);
        d = route_decide(DS4_NEED_BANK_FRONTIER, DS4_WIRE_ANTHROPIC, &no_ctx);
        TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_CONT_UNAVAILABLE);
        d = route_decide(DS4_NEED_BANK_FRONTIER, DS4_WIRE_OPENAI_CHAT, &on);
        TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_NEED_LIVE_FRONTIER);
    }
    /* semantic requirements fire before the surface gap, lowest bit first */
    d = route_decide(DS4_NEED_TOOL_SCAN | DS4_NEED_CONTINUATION_PUBLISH |
                     DS4_NEED_CORRECTIVE_RECOVERY, DS4_WIRE_ANTHROPIC, &on);
    TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_NEED_CONTINUATION_PUBLISH);
    d = route_decide(DS4_NEED_LIVE_FRONTIER | DS4_NEED_TOOL_SCAN, DS4_WIRE_RESPONSES, &on);
    TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_NEED_LIVE_FRONTIER);
    d = route_decide(DS4_NEED_PREFILL_ONLY, DS4_WIRE_ANTHROPIC, &on);
    TEST_ASSERT(d.lane == ROUTE_LANE_SERIAL && d.reason == ROUTE_REASON_NEED_PREFILL_ONLY);
    /* durable references: rejected, never silently routed */
    d = route_decide(DS4_NEED_DURABLE_RESPONSE, DS4_WIRE_RESPONSES, &on);
    TEST_ASSERT(d.lane == ROUTE_LANE_NONE && d.reason == ROUTE_REASON_NEED_DURABLE);
}

/* Inc 3d: coalesce_gather's peer-join mirrors route_decide's static row --
 * needs-free promoted-surface jobs join a static group only while their §7
 * kill switch is on; every need (including Anthropic's PREFILL_ONLY zero)
 * keeps a job out; the OpenAI oracle row is untouched by the switches. */
static void test_static_peer_join(void) {
    server s;
    memset(&s, 0, sizeof(s));
    s.cont_anthropic = true;
    s.cont_responses = true;
    request r;

    request_init(&r, REQ_CHAT, 128);
    r.api = API_ANTHROPIC; r.temperature = 0.0f; r.think_mode = DS4_THINK_NONE;
    TEST_ASSERT(job_static_peer_ok(&s, &r));           /* needs-free promoted */
    r.temperature = 0.7f;
    TEST_ASSERT(!job_static_peer_ok(&s, &r));          /* per-row sampling */
    r.temperature = 0.0f;
    r.think_mode = DS4_THINK_LOW;
    TEST_ASSERT(!job_static_peer_ok(&s, &r));          /* thinking */
    r.think_mode = DS4_THINK_NONE;
    id_list_push_unique(&r.stops, "STOP");
    TEST_ASSERT(!job_static_peer_ok(&s, &r));          /* stop scan */
    stop_list_clear(&r.stops);
    r.max_tokens_set = true; r.max_tokens = 0;
    TEST_ASSERT(!job_static_peer_ok(&s, &r));          /* prewarm: PREFILL_ONLY */
    r.max_tokens_set = false; r.max_tokens = 128;
    s.cont_anthropic = false;
    TEST_ASSERT(!job_static_peer_ok(&s, &r));          /* kill switch gates joins */
    s.cont_anthropic = true;
    request_free(&r);

    request_init(&r, REQ_CHAT, 128);
    r.api = API_RESPONSES; r.temperature = 0.0f; r.think_mode = DS4_THINK_NONE;
    TEST_ASSERT(job_static_peer_ok(&s, &r));
    /* Responses explicit-zero carries NO need bit (3c: the wire trims the
     * seed floor) -- it may join and retires empty. */
    r.max_tokens_set = true; r.max_tokens = 0;
    TEST_ASSERT(job_static_peer_ok(&s, &r));
    s.cont_responses = false;
    TEST_ASSERT(!job_static_peer_ok(&s, &r));          /* independent switch */
    s.cont_responses = true;
    request_free(&r);

    /* The OpenAI row is the legacy oracle and ignores the switches. */
    s.cont_anthropic = false;
    s.cont_responses = false;
    request_init(&r, REQ_CHAT, 128);
    r.api = API_OPENAI; r.temperature = 0.0f; r.think_mode = DS4_THINK_NONE;
    TEST_ASSERT(job_static_peer_ok(&s, &r));
    request_free(&r);
}

/* Tape -> serial OpenAI Chat stream projector (role preamble + live SSE
 * machine + finish), the generate_job call shape. */
static void test_tape_openai_chat_stream_projection(void) {
    int sv[2];
    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
    if (sv[0] < 0 || sv[1] < 0) return;

    request r;
    request_init(&r, REQ_CHAT, 128);
    r.api = API_OPENAI;
    r.stream = true;
    r.think_mode = DS4_THINK_LOW;

    openai_stream st;
    openai_stream_start(&r, &st);
    TEST_ASSERT(sse_headers(sv[0], false));
    TEST_ASSERT(sse_chunk(sv[0], &r, "chatcmpl_tape", NULL, NULL));
    buf raw = {0};
    for (size_t i = 0; i < sizeof(tape_thinking) / sizeof(tape_thinking[0]); i++) {
        buf_append(&raw, tape_thinking[i].piece, strlen(tape_thinking[i].piece));
        TEST_ASSERT(openai_sse_stream_update(sv[0], NULL, &r, "chatcmpl_tape", &st,
                                             raw.ptr, raw.len, false));
    }
    tool_calls empty = {0};
    TEST_ASSERT(openai_sse_finish_live(sv[0], NULL, &r, "chatcmpl_tape", &st,
                                       raw.ptr, raw.len, &empty, "stop", 7, 4));
    shutdown(sv[0], SHUT_WR);
    char *out = read_socket_text(sv[1]);

    sse_assert_every_data_object(out, "\"object\":\"chat.completion.chunk\"", NULL);
    const char *reason = strstr(out, "\"reasoning_content\":");
    const char *content = strstr(out, "\"content\":\"Answer");
    TEST_ASSERT(strstr(out, "\"delta\":{\"role\":\"assistant\"}") != NULL);
    TEST_ASSERT(reason != NULL);
    TEST_ASSERT(content != NULL);
    TEST_ASSERT(reason < content);
    TEST_ASSERT(strstr(out, "\"finish_reason\":\"stop\"") != NULL);
    TEST_ASSERT(strstr(out, "</think>") == NULL);

    free(out);
    buf_free(&raw);
    openai_stream_free(&st);
    request_free(&r);
    close(sv[0]);
    close(sv[1]);

    /* UTF-8 tape: the split e-acute must never emit as a dangling byte. */
    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
    if (sv[0] < 0 || sv[1] < 0) return;
    request_init(&r, REQ_CHAT, 128);
    r.api = API_OPENAI;
    r.stream = true;
    r.think_mode = DS4_THINK_NONE;
    openai_stream st2;
    openai_stream_start(&r, &st2);
    TEST_ASSERT(sse_headers(sv[0], false));
    buf raw2 = {0};
    for (size_t i = 0; i < sizeof(tape_utf8) / sizeof(tape_utf8[0]); i++) {
        buf_append(&raw2, tape_utf8[i].piece, strlen(tape_utf8[i].piece));
        TEST_ASSERT(openai_sse_stream_update(sv[0], NULL, &r, "chatcmpl_tape8", &st2,
                                             raw2.ptr, raw2.len, false));
    }
    tool_calls empty2 = {0};
    TEST_ASSERT(openai_sse_finish_live(sv[0], NULL, &r, "chatcmpl_tape8", &st2,
                                       raw2.ptr, raw2.len, &empty2, "stop", 4, 4));
    shutdown(sv[0], SHUT_WR);
    out = read_socket_text(sv[1]);
    /* The held-back lead byte may flush in a LATER delta than "caf" -- what
     * must hold is that the two e-acute bytes stay contiguous inside one
     * delta and a dangling lead byte never ends a delta string. */
    TEST_ASSERT(strstr(out, "\xC3\xA9") != NULL);
    TEST_ASSERT(strstr(out, "\xC3\"") == NULL);
    free(out);
    buf_free(&raw2);
    openai_stream_free(&st2);
    request_free(&r);
    close(sv[0]);
    close(sv[1]);
}

/* Tape -> serial legacy Completion stream projector.  THIS is the protocol
 * oracle the negative continuous fixture is judged against: text_completion
 * objects with choices[].text, never chat deltas. */
static void test_tape_openai_completion_stream_projection(void) {
    int sv[2];
    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
    if (sv[0] < 0 || sv[1] < 0) return;

    request r;
    request_init(&r, REQ_COMPLETION, 128);
    r.api = API_OPENAI;
    r.stream = true;

    TEST_ASSERT(sse_headers(sv[0], false));
    for (size_t i = 0; i < sizeof(tape_plain) / sizeof(tape_plain[0]); i++) {
        TEST_ASSERT(sse_chunk(sv[0], &r, "cmpl_tape", tape_plain[i].piece, NULL));
    }
    TEST_ASSERT(sse_chunk(sv[0], &r, "cmpl_tape", NULL, "stop"));
    TEST_ASSERT(sse_done(sv[0], &r, "cmpl_tape", 4, 4));
    shutdown(sv[0], SHUT_WR);
    char *out = read_socket_text(sv[1]);

    sse_assert_every_data_object(out, "\"object\":\"text_completion\"",
                                 "chat.completion.chunk");
    TEST_ASSERT(strstr(out, "\"choices\":[{\"text\":\"Hel\"") != NULL);
    TEST_ASSERT(strstr(out, "\"finish_reason\":\"stop\"") != NULL);
    TEST_ASSERT(strstr(out, "\"delta\"") == NULL);

    free(out);
    request_free(&r);
    close(sv[0]);
    close(sv[1]);
}

/* Tape -> serial Anthropic Messages stream projector. */
static void test_tape_anthropic_stream_projection(void) {
    int sv[2];
    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
    if (sv[0] < 0 || sv[1] < 0) return;

    request r;
    request_init(&r, REQ_CHAT, 128);
    r.api = API_ANTHROPIC;
    r.stream = true;
    r.think_mode = DS4_THINK_LOW;

    anthropic_stream st;
    TEST_ASSERT(anthropic_sse_start_live(sv[0], &r, "msg_tape", 7, &st));
    buf raw = {0};
    for (size_t i = 0; i < sizeof(tape_thinking) / sizeof(tape_thinking[0]); i++) {
        buf_append(&raw, tape_thinking[i].piece, strlen(tape_thinking[i].piece));
        TEST_ASSERT(anthropic_sse_stream_update(sv[0], NULL, &r, "msg_tape", &st,
                                                raw.ptr, raw.len, false));
    }
    tool_calls empty = {0};
    TEST_ASSERT(anthropic_sse_finish_live(sv[0], NULL, &r, "msg_tape", &st,
                                          raw.ptr, raw.len, &empty, "stop", NULL, 4));
    shutdown(sv[0], SHUT_WR);
    char *out = read_socket_text(sv[1]);

    sse_validate_anthropic_stream(out);
    const char *thinking = strstr(out, "\"thinking\":\"plan\"");
    const char *signature = strstr(out, "\"type\":\"signature_delta\"");
    const char *text = strstr(out, "\"text\":\"Answer");
    TEST_ASSERT(thinking != NULL);
    TEST_ASSERT(signature != NULL);
    TEST_ASSERT(text != NULL);
    TEST_ASSERT(thinking < signature);
    TEST_ASSERT(signature < text);
    TEST_ASSERT(strstr(out, "\"stop_reason\":\"end_turn\"") != NULL);
    TEST_ASSERT(strstr(out, "</think>") == NULL);

    free(out);
    buf_free(&raw);
    anthropic_stream_free(&st);
    request_free(&r);
    close(sv[0]);
    close(sv[1]);
}

/* Tape -> serial Responses stream projector (created + reasoning summary +
 * message + completed), the generate_job call shape. */
static void test_tape_responses_stream_projection(void) {
    int sv[2];
    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
    if (sv[0] < 0 || sv[1] < 0) return;

    request r;
    request_init(&r, REQ_CHAT, 128);
    r.api = API_RESPONSES;
    r.stream = true;
    r.think_mode = DS4_THINK_LOW;
    r.reasoning_summary_emit = true;

    responses_stream st;
    responses_stream_init(&r, &st);
    st.active = true;
    TEST_ASSERT(responses_sse_created(sv[0], &r, &st, 1234));
    buf raw = {0};
    for (size_t i = 0; i < sizeof(tape_thinking) / sizeof(tape_thinking[0]); i++) {
        buf_append(&raw, tape_thinking[i].piece, strlen(tape_thinking[i].piece));
        TEST_ASSERT(responses_sse_stream_update(sv[0], &r, &st,
                                                raw.ptr, raw.len, false));
    }
    tool_calls empty = {0};
    TEST_ASSERT(responses_sse_finish_live(sv[0], &r, &st, raw.ptr, raw.len,
                                          NULL, &empty, "stop", 7, 4, 1, 1234));
    shutdown(sv[0], SHUT_WR);
    char *out = read_socket_text(sv[1]);

    sse_validate_responses_stream(out);
    const char *summary = strstr(out, "\"type\":\"response.reasoning_summary_text.delta\"");
    const char *text = strstr(out, "\"type\":\"response.output_text.delta\"");
    TEST_ASSERT(summary != NULL);
    TEST_ASSERT(text != NULL);
    TEST_ASSERT(summary < text);
    TEST_ASSERT(strstr(out, "\"status\":\"completed\"") != NULL);
    TEST_ASSERT(strstr(out, "</think>") == NULL);

    free(out);
    buf_free(&raw);
    responses_stream_free(&st);
    request_free(&r);
    close(sv[0]);
    close(sv[1]);
}

/* Tape terminal text -> the four buffered finals.  Freezes each surface's
 * response object and finish mapping, including Anthropic's
 * length->max_tokens / stop->end_turn stop_reason mapping. */
static void test_tape_buffered_final_responses(void) {
    int sv[2];
    request r;
    tool_calls empty = {0};
    char *out;

    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
    if (sv[0] < 0 || sv[1] < 0) return;
    request_init(&r, REQ_CHAT, 128);
    r.api = API_OPENAI;
    TEST_ASSERT(final_response(sv[0], false, &r, "chatcmpl_buf", "Hello world.",
                               NULL, &empty, "stop", 4, 4));
    shutdown(sv[0], SHUT_WR);
    out = read_socket_text(sv[1]);
    TEST_ASSERT(strstr(out, "\"object\":\"chat.completion\"") != NULL);
    TEST_ASSERT(strstr(out, "\"role\":\"assistant\",\"content\":\"Hello world.\"") != NULL);
    TEST_ASSERT(strstr(out, "\"finish_reason\":\"stop\"") != NULL);
    free(out);
    request_free(&r);
    close(sv[0]);
    close(sv[1]);

    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
    if (sv[0] < 0 || sv[1] < 0) return;
    request_init(&r, REQ_COMPLETION, 128);
    r.api = API_OPENAI;
    TEST_ASSERT(final_response(sv[0], false, &r, "cmpl_buf", "Hello world.",
                               NULL, &empty, "length", 4, 4));
    shutdown(sv[0], SHUT_WR);
    out = read_socket_text(sv[1]);
    TEST_ASSERT(strstr(out, "\"object\":\"text_completion\"") != NULL);
    TEST_ASSERT(strstr(out, "\"choices\":[{\"text\":\"Hello world.\"") != NULL);
    TEST_ASSERT(strstr(out, "\"finish_reason\":\"length\"") != NULL);
    free(out);
    request_free(&r);
    close(sv[0]);
    close(sv[1]);

    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
    if (sv[0] < 0 || sv[1] < 0) return;
    request_init(&r, REQ_CHAT, 128);
    r.api = API_ANTHROPIC;
    TEST_ASSERT(anthropic_final_response(sv[0], false, &r, "msg_buf", "Hello world.",
                                         NULL, &empty, "length", NULL, 4, 4));
    shutdown(sv[0], SHUT_WR);
    out = read_socket_text(sv[1]);
    TEST_ASSERT(strstr(out, "\"type\":\"message\"") != NULL);
    TEST_ASSERT(strstr(out, "\"stop_reason\":\"max_tokens\"") != NULL);
    free(out);
    request_free(&r);
    close(sv[0]);
    close(sv[1]);

    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
    if (sv[0] < 0 || sv[1] < 0) return;
    request_init(&r, REQ_CHAT, 128);
    r.api = API_RESPONSES;
    TEST_ASSERT(responses_final_response(sv[0], false, &r, "resp_buf", "Hello world.",
                                         NULL, &empty, "stop", 4, 4, 0));
    shutdown(sv[0], SHUT_WR);
    out = read_socket_text(sv[1]);
    TEST_ASSERT(strstr(out, "\"object\":\"response\"") != NULL);
    TEST_ASSERT(strstr(out, "\"status\":\"completed\"") != NULL);
    TEST_ASSERT(strstr(out, "Hello world.") != NULL);
    free(out);
    request_free(&r);
    close(sv[0]);
    close(sv[1]);
}

/* Inc 1 equivalence normalizer: only the "created"/"created_at" epoch digits
 * may differ between two renders that straddle a second boundary; everything
 * else must be byte-identical, so IDs, ordering, and structure stay asserted. */
static char *wire_test_normalize_created(const char *in) {
    size_t n = strlen(in);
    char *out = xmalloc(n + 2);
    size_t o = 0;
    for (size_t i = 0; i < n; ) {
        const char *k1 = "\"created\":";
        const char *k2 = "\"created_at\":";
        size_t l = 0;
        if (!strncmp(in + i, k1, strlen(k1))) l = strlen(k1);
        else if (!strncmp(in + i, k2, strlen(k2))) l = strlen(k2);
        if (l) {
            memcpy(out + o, in + i, l); o += l; i += l;
            while (in[i] >= '0' && in[i] <= '9') i++;
            out[o++] = '0';
        } else {
            out[o++] = in[i++];
        }
    }
    out[o] = 0;
    return out;
}

/* §6.1: canonicalize first-seen opaque ids (letters-only prefix, >=12 hex
 * digits) to prefix#N in first-seen order.  The Responses surface mints
 * fresh resp_/msg_/rs_/fc_ ids per render, so equivalence must compare
 * their PREFIX and reference structure, not the random bytes; repeated
 * references keep the same placeholder, so relationships stay asserted. */
static char *wire_test_canonicalize_ids(const char *in) {
    char *seen[64];
    size_t nseen = 0;
    size_t n = strlen(in);
    buf b = {0};
    size_t i = 0;
    while (i < n) {
        size_t j = i;
        while (j < n && ((in[j] >= 'a' && in[j] <= 'z') ||
                         (in[j] >= '0' && in[j] <= '9') || in[j] == '_')) j++;
        size_t len = j - i;
        const char *us = NULL;
        for (size_t k = j; k > i; k--) if (in[k - 1] == '_') { us = in + k - 1; break; }
        bool match = false;
        if (len >= 14 && us && us > in + i && (size_t)(in + j - us) - 1 >= 12) {
            match = true;
            for (const char *p = in + i; p < us; p++)
                if (!((*p >= 'a' && *p <= 'z'))) { match = false; break; }
            for (const char *p = us + 1; p < in + j; p++)
                if (!((*p >= '0' && *p <= '9') || (*p >= 'a' && *p <= 'f'))) { match = false; break; }
        }
        if (match) {
            size_t idx = nseen;
            for (size_t k = 0; k < nseen; k++)
                if (!strncmp(seen[k], in + i, len) && seen[k][len] == 0) { idx = k; break; }
            if (idx == nseen && nseen < 64) seen[nseen++] = xstrndup(in + i, len);
            buf_append(&b, in + i, (size_t)(us - (in + i)) + 1);
            buf_printf(&b, "#%zu", idx);
            i = j;
        } else if (len) {
            buf_append(&b, in + i, len);
            i = j;
        } else {
            buf_putc(&b, in[i]);
            i++;
        }
    }
    for (size_t k = 0; k < nseen; k++) free(seen[k]);
    char *out = b.ptr ? b.ptr : xstrdup("");
    return out;
}

/* Inc 1: the session owns surface mapping and identity; free is idempotent. */
static void test_wire_session_identity_and_free(void) {
    request r;
    ds4_wire_session ws;

    request_init(&r, REQ_CHAT, 128);
    r.api = API_OPENAI;
    TEST_ASSERT(wire_surface_for(&r) == DS4_WIRE_OPENAI_CHAT);
    r.api = API_ANTHROPIC;
    TEST_ASSERT(wire_surface_for(&r) == DS4_WIRE_ANTHROPIC);
    r.api = API_RESPONSES;
    TEST_ASSERT(wire_surface_for(&r) == DS4_WIRE_RESPONSES);
    request_free(&r);
    request_init(&r, REQ_COMPLETION, 128);
    r.api = API_OPENAI;
    TEST_ASSERT(wire_surface_for(&r) == DS4_WIRE_OPENAI_COMPLETION);
    request_free(&r);

    wire_init(&ws, DS4_WIRE_OPENAI_CHAT, "chatcmpl_wire_id");
    TEST_ASSERT(ws.surface == DS4_WIRE_OPENAI_CHAT);
    TEST_ASSERT(!strcmp(ws.id, "chatcmpl_wire_id"));
    TEST_ASSERT(!ws.terminal && !ws.http_started && !ws.protocol_started);
    /* Live per-surface state frees once; the second free is a no-op. */
    request_init(&r, REQ_CHAT, 128);
    r.api = API_OPENAI;
    openai_stream_start(&r, &ws.state.oa_chat);
    ws.state.oa_chat.pending_token_ids = xmalloc(4 * sizeof(int));
    ws.state.oa_chat.pending_token_byte_ends = xmalloc(4 * sizeof(size_t));
    ws.state.oa_chat.pending_cap = 4;
    ws.protocol_started = true;
    wire_free(&ws);
    TEST_ASSERT(!ws.protocol_started);
    TEST_ASSERT(ws.state.oa_chat.pending_token_ids == NULL);
    wire_free(&ws);
    request_free(&r);

    /* The canonical finish round-trip is total over the writer vocabulary. */
    static const char *finishes[] = { "stop", "length", "tool_calls", "error" };
    for (size_t i = 0; i < sizeof(finishes) / sizeof(finishes[0]); i++) {
        ds4_wire_result res = {0};
        wire_result_set_finish(&res, finishes[i]);
        TEST_ASSERT(!strcmp(wire_canonical_finish(&res), finishes[i]));
    }

    /* Inc 1c/2b: the error wrappers are byte-exact passthroughs where the
     * shared envelope IS native (OpenAI http, OpenAI + Anthropic stream);
     * Anthropic http and Responses stream shapes are asserted natively in
     * test_error_envelopes_native_shapes. */
    for (int api = 0; api < 2; api++) {
        int sv[2];
        char *direct, *wrapped;

        request_init(&r, REQ_CHAT, 128);
        r.api = api == 0 ? API_OPENAI : API_ANTHROPIC;

        if (r.api == API_OPENAI) {
            TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
            TEST_ASSERT(http_error(sv[0], false, 503, "wire error parity"));
            shutdown(sv[0], SHUT_WR);
            direct = read_socket_text(sv[1]);
            close(sv[0]); close(sv[1]);
            TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
            TEST_ASSERT(wire_http_error(sv[0], false, wire_surface_for(&r), 503,
                                        "wire error parity"));
            shutdown(sv[0], SHUT_WR);
            wrapped = read_socket_text(sv[1]);
            close(sv[0]); close(sv[1]);
            TEST_ASSERT(!strcmp(direct, wrapped));
            free(direct); free(wrapped);
        }

        TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
        TEST_ASSERT(sse_error_event(sv[0], &r, "boom"));
        shutdown(sv[0], SHUT_WR);
        direct = read_socket_text(sv[1]);
        close(sv[0]); close(sv[1]);
        TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
        ds4_wire_session es;
        wire_init(&es, wire_surface_for(&r), "err_wire");
        TEST_ASSERT(wire_stream_error(sv[0], &r, &es, "boom"));
        TEST_ASSERT(es.terminal);
        wire_free(&es);
        shutdown(sv[0], SHUT_WR);
        wrapped = read_socket_text(sv[1]);
        close(sv[0]); close(sv[1]);
        TEST_ASSERT(!strcmp(direct, wrapped));
        free(direct); free(wrapped);
        request_free(&r);
    }
}

/* Inc 1 gate: the typed wrapper and the direct emitter consume the same
 * terminal and must produce byte-identical responses (normalized only for
 * the created epoch) on every surface x finish combination. */
static void test_wire_finish_buffered_matches_direct_emitters(void) {
    static const struct { int api; int kind; const char *id; } surfaces[] = {
        { API_OPENAI,    REQ_CHAT,       "chatcmpl_wire_eq" },
        { API_OPENAI,    REQ_COMPLETION, "cmpl_wire_eq" },
        { API_ANTHROPIC, REQ_CHAT,       "msg_wire_eq" },
        { API_RESPONSES, REQ_CHAT,       "resp_wire_eq" },
    };
    static const char *finishes[] = { "stop", "length", "tool_calls", "error" };

    for (size_t si = 0; si < sizeof(surfaces) / sizeof(surfaces[0]); si++) {
        for (size_t fi = 0; fi < sizeof(finishes) / sizeof(finishes[0]); fi++) {
            request r;
            tool_calls empty = {0};
            int sv[2];
            char *direct, *wrapped, *dn, *wn;

            request_init(&r, surfaces[si].kind, 128);
            r.api = surfaces[si].api;

            TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
            if (sv[0] < 0 || sv[1] < 0) return;
            if (r.api == API_ANTHROPIC) {
                TEST_ASSERT(anthropic_final_response(sv[0], false, &r, surfaces[si].id,
                                                     "Hello world.", NULL, &empty,
                                                     finishes[fi], NULL, 4, 4));
            } else if (r.api == API_RESPONSES) {
                TEST_ASSERT(responses_final_response(sv[0], false, &r, surfaces[si].id,
                                                     "Hello world.", NULL, &empty,
                                                     finishes[fi], 4, 4, 0));
            } else {
                TEST_ASSERT(final_response(sv[0], false, &r, surfaces[si].id,
                                           "Hello world.", NULL, &empty,
                                           finishes[fi], 4, 4));
            }
            shutdown(sv[0], SHUT_WR);
            direct = read_socket_text(sv[1]);
            close(sv[0]);
            close(sv[1]);

            TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
            if (sv[0] < 0 || sv[1] < 0) return;
            ds4_wire_session ws;
            ds4_wire_result res = {0};
            wire_init(&ws, wire_surface_for(&r), surfaces[si].id);
            wire_result_set_finish(&res, finishes[fi]);
            res.content = "Hello world.";
            res.calls = &empty;
            res.prompt_tokens = 4;
            res.completion_tokens = 4;
            TEST_ASSERT(wire_finish_buffered(sv[0], false, &r, &ws, &res));
            TEST_ASSERT(ws.terminal);
            wire_free(&ws);
            shutdown(sv[0], SHUT_WR);
            wrapped = read_socket_text(sv[1]);
            close(sv[0]);
            close(sv[1]);

            char *dt = wire_test_normalize_created(direct);
            char *wt = wire_test_normalize_created(wrapped);
            dn = wire_test_canonicalize_ids(dt);
            wn = wire_test_canonicalize_ids(wt);
            free(dt);
            free(wt);
            if (strcmp(dn, wn)) {
                size_t d = 0;
                while (dn[d] && wn[d] && dn[d] == wn[d]) d++;
                fprintf(stderr, "WIREDIFF api=%d kind=%d finish=%s at=%zu\n  direct:  %.160s\n  wrapped: %.160s\n",
                        surfaces[si].api, surfaces[si].kind, finishes[fi], d,
                        dn + (d > 60 ? d - 60 : 0), wn + (d > 60 ? d - 60 : 0));
            }
            TEST_ASSERT(!strcmp(dn, wn));
            free(direct);
            free(wrapped);
            free(dn);
            free(wn);
            request_free(&r);
        }
    }
}

/* Inc 1b gate: wire_finish_stream reproduces the serial writer's historical
 * five-way dispatch byte-for-byte.  Each live branch feeds the SAME tape
 * through two independent machines (direct vs session-embedded) and diverges
 * only at the finish call; stateless branches compare end-to-end. */
static void test_wire_finish_stream_matches_direct_dispatch(void) {
    tool_calls empty = {0};
    int sv[2];
    char *direct, *wrapped, *dt, *wt, *dn, *wn;

    /* -- Anthropic live -- */
    {
        request r;
        request_init(&r, REQ_CHAT, 128);
        r.api = API_ANTHROPIC;
        r.stream = true;
        r.think_mode = DS4_THINK_LOW;
        buf raw = {0};

        TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
        anthropic_stream st;
        TEST_ASSERT(anthropic_sse_start_live(sv[0], &r, "msg_wire_st", 7, &st));
        for (size_t i = 0; i < sizeof(tape_thinking) / sizeof(tape_thinking[0]); i++) {
            buf_append(&raw, tape_thinking[i].piece, strlen(tape_thinking[i].piece));
            TEST_ASSERT(anthropic_sse_stream_update(sv[0], NULL, &r, "msg_wire_st", &st,
                                                    raw.ptr, raw.len, false));
        }
        TEST_ASSERT(anthropic_sse_finish_live(sv[0], NULL, &r, "msg_wire_st", &st,
                                              raw.ptr, raw.len, &empty, "stop", NULL, 4));
        shutdown(sv[0], SHUT_WR);
        direct = read_socket_text(sv[1]);
        close(sv[0]); close(sv[1]);

        TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
        ds4_wire_session ws;
        wire_init(&ws, DS4_WIRE_ANTHROPIC, "msg_wire_st");
        ws.protocol_started = true;
        TEST_ASSERT(anthropic_sse_start_live(sv[0], &r, "msg_wire_st", 7, &ws.state.anthropic));
        buf raw2 = {0};
        for (size_t i = 0; i < sizeof(tape_thinking) / sizeof(tape_thinking[0]); i++) {
            buf_append(&raw2, tape_thinking[i].piece, strlen(tape_thinking[i].piece));
            TEST_ASSERT(anthropic_sse_stream_update(sv[0], NULL, &r, "msg_wire_st",
                                                    &ws.state.anthropic,
                                                    raw2.ptr, raw2.len, false));
        }
        ds4_wire_result res = {0};
        wire_result_set_finish(&res, "stop");
        res.raw = raw2.ptr; res.raw_len = raw2.len;
        res.calls = &empty;
        res.completion_tokens = 4;
        TEST_ASSERT(wire_finish_stream(sv[0], NULL, &r, &ws, &res));
        TEST_ASSERT(ws.terminal);
        wire_free(&ws);
        shutdown(sv[0], SHUT_WR);
        wrapped = read_socket_text(sv[1]);
        close(sv[0]); close(sv[1]);

        TEST_ASSERT(!strcmp(direct, wrapped));
        free(direct); free(wrapped);
        buf_free(&raw); buf_free(&raw2);
        request_free(&r);
    }

    /* -- OpenAI chat live -- */
    {
        request r;
        request_init(&r, REQ_CHAT, 128);
        r.api = API_OPENAI;
        r.stream = true;
        r.think_mode = DS4_THINK_LOW;
        buf raw = {0};

        TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
        openai_stream st;
        openai_stream_start(&r, &st);
        for (size_t i = 0; i < sizeof(tape_thinking) / sizeof(tape_thinking[0]); i++) {
            buf_append(&raw, tape_thinking[i].piece, strlen(tape_thinking[i].piece));
            TEST_ASSERT(openai_sse_stream_update(sv[0], NULL, &r, "chatcmpl_wire_st", &st,
                                                 raw.ptr, raw.len, false));
        }
        TEST_ASSERT(openai_sse_finish_live(sv[0], NULL, &r, "chatcmpl_wire_st", &st,
                                           raw.ptr, raw.len, &empty, "stop", 4, 4));
        shutdown(sv[0], SHUT_WR);
        direct = read_socket_text(sv[1]);
        close(sv[0]); close(sv[1]);
        openai_stream_free(&st);

        TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
        ds4_wire_session ws;
        wire_init(&ws, DS4_WIRE_OPENAI_CHAT, "chatcmpl_wire_st");
        ws.live_openai = true;
        ws.protocol_started = true;
        openai_stream_start(&r, &ws.state.oa_chat);
        buf raw2 = {0};
        for (size_t i = 0; i < sizeof(tape_thinking) / sizeof(tape_thinking[0]); i++) {
            buf_append(&raw2, tape_thinking[i].piece, strlen(tape_thinking[i].piece));
            TEST_ASSERT(openai_sse_stream_update(sv[0], NULL, &r, "chatcmpl_wire_st",
                                                 &ws.state.oa_chat,
                                                 raw2.ptr, raw2.len, false));
        }
        ds4_wire_result res = {0};
        wire_result_set_finish(&res, "stop");
        res.raw = raw2.ptr; res.raw_len = raw2.len;
        res.calls = &empty;
        res.prompt_tokens = 4;
        res.completion_tokens = 4;
        TEST_ASSERT(wire_finish_stream(sv[0], NULL, &r, &ws, &res));
        wire_free(&ws);
        shutdown(sv[0], SHUT_WR);
        wrapped = read_socket_text(sv[1]);
        close(sv[0]); close(sv[1]);

        dt = wire_test_normalize_created(direct);
        wt = wire_test_normalize_created(wrapped);
        TEST_ASSERT(!strcmp(dt, wt));
        free(direct); free(wrapped); free(dt); free(wt);
        buf_free(&raw); buf_free(&raw2);
        request_free(&r);
    }

    /* -- Responses live (random ids canonicalized, created_at pinned) -- */
    {
        request r;
        request_init(&r, REQ_CHAT, 128);
        r.api = API_RESPONSES;
        r.stream = true;
        r.think_mode = DS4_THINK_LOW;
        buf raw = {0};

        ds4_wire_session ws;
        wire_init(&ws, DS4_WIRE_RESPONSES, "resp_wire_st");
        ws.live_responses = true;

        TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
        responses_stream st;
        responses_stream_init(&r, &st);
        st.active = true;
        TEST_ASSERT(responses_sse_created(sv[0], &r, &st, ws.created_at));
        for (size_t i = 0; i < sizeof(tape_thinking) / sizeof(tape_thinking[0]); i++) {
            buf_append(&raw, tape_thinking[i].piece, strlen(tape_thinking[i].piece));
            TEST_ASSERT(responses_sse_stream_update(sv[0], &r, &st,
                                                    raw.ptr, raw.len, false));
        }
        TEST_ASSERT(responses_sse_finish_live(sv[0], &r, &st, raw.ptr, raw.len,
                                              NULL, &empty, "stop", 4, 4, 0,
                                              ws.created_at));
        shutdown(sv[0], SHUT_WR);
        direct = read_socket_text(sv[1]);
        close(sv[0]); close(sv[1]);
        responses_stream_free(&st);

        TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
        responses_stream_init(&r, &ws.state.responses);
        ws.state.responses.active = true;
        ws.protocol_started = true;
        TEST_ASSERT(responses_sse_created(sv[0], &r, &ws.state.responses, ws.created_at));
        buf raw2 = {0};
        for (size_t i = 0; i < sizeof(tape_thinking) / sizeof(tape_thinking[0]); i++) {
            buf_append(&raw2, tape_thinking[i].piece, strlen(tape_thinking[i].piece));
            TEST_ASSERT(responses_sse_stream_update(sv[0], &r, &ws.state.responses,
                                                    raw2.ptr, raw2.len, false));
        }
        ds4_wire_result res = {0};
        wire_result_set_finish(&res, "stop");
        res.raw = raw2.ptr; res.raw_len = raw2.len;
        res.calls = &empty;
        res.prompt_tokens = 4;
        res.completion_tokens = 4;
        TEST_ASSERT(wire_finish_stream(sv[0], NULL, &r, &ws, &res));
        wire_free(&ws);
        shutdown(sv[0], SHUT_WR);
        wrapped = read_socket_text(sv[1]);
        close(sv[0]); close(sv[1]);

        dt = wire_test_normalize_created(direct);
        wt = wire_test_normalize_created(wrapped);
        dn = wire_test_canonicalize_ids(dt);
        wn = wire_test_canonicalize_ids(wt);
        TEST_ASSERT(!strcmp(dn, wn));
        free(direct); free(wrapped); free(dt); free(wt); free(dn); free(wn);
        buf_free(&raw); buf_free(&raw2);
        request_free(&r);
    }

    /* -- structured + plain (stateless dispatch plumbing) -- */
    {
        request r;
        request_init(&r, REQ_CHAT, 128);
        r.api = API_OPENAI;
        r.stream = true;

        TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
        TEST_ASSERT(sse_chat_finish(sv[0], &r, "chatcmpl_wire_sf", "Hi.", NULL,
                                    &empty, "stop", 4, 4));
        shutdown(sv[0], SHUT_WR);
        direct = read_socket_text(sv[1]);
        close(sv[0]); close(sv[1]);

        TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
        ds4_wire_session ws;
        wire_init(&ws, DS4_WIRE_OPENAI_CHAT, "chatcmpl_wire_sf");
        ws.structured = true;   /* live_openai false: force the structured branch */
        ds4_wire_result res = {0};
        wire_result_set_finish(&res, "stop");
        res.content = "Hi.";
        res.calls = &empty;
        res.prompt_tokens = 4;
        res.completion_tokens = 4;
        TEST_ASSERT(wire_finish_stream(sv[0], NULL, &r, &ws, &res));
        wire_free(&ws);
        shutdown(sv[0], SHUT_WR);
        wrapped = read_socket_text(sv[1]);
        close(sv[0]); close(sv[1]);

        dt = wire_test_normalize_created(direct);
        wt = wire_test_normalize_created(wrapped);
        TEST_ASSERT(!strcmp(dt, wt));
        free(direct); free(wrapped); free(dt); free(wt);
        request_free(&r);

        request_init(&r, REQ_COMPLETION, 128);
        r.api = API_OPENAI;
        r.stream = true;

        TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
        TEST_ASSERT(sse_chunk(sv[0], &r, "cmpl_wire_pl", NULL, "length") &&
                    sse_done(sv[0], &r, "cmpl_wire_pl", 4, 4));
        shutdown(sv[0], SHUT_WR);
        direct = read_socket_text(sv[1]);
        close(sv[0]); close(sv[1]);

        TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
        ds4_wire_session ws2;
        wire_init(&ws2, DS4_WIRE_OPENAI_COMPLETION, "cmpl_wire_pl");
        ds4_wire_result res2 = {0};
        wire_result_set_finish(&res2, "length");
        res2.calls = &empty;
        res2.prompt_tokens = 4;
        res2.completion_tokens = 4;
        TEST_ASSERT(wire_finish_stream(sv[0], NULL, &r, &ws2, &res2));
        wire_free(&ws2);
        shutdown(sv[0], SHUT_WR);
        wrapped = read_socket_text(sv[1]);
        close(sv[0]); close(sv[1]);

        dt = wire_test_normalize_created(direct);
        wt = wire_test_normalize_created(wrapped);
        TEST_ASSERT(!strcmp(dt, wt));
        free(direct); free(wrapped); free(dt); free(wt);
        request_free(&r);
    }
}

/* INVERTED Inc 0a negative fixture (fixed in Inc 0b).  The continuous lane
 * used to project streaming legacy /v1/completions rows through the CHAT
 * delta machine (chat.completion.chunk objects on a text_completion route);
 * cont_on_token now routes completion rows through cont_stream_emit_plain
 * and cont_stream_finalize closes with the serial plain branch.  This test
 * calls the REAL cont projection entry points (cont_stream_start /
 * cont_stream_emit_plain / cont_stream_finalize; cont_on_token itself needs
 * a live engine for detok) and asserts the serial oracle's shape --
 * byte-comparable with test_tape_openai_completion_stream_projection. */
static void test_cont_completion_stream_matches_serial_oracle(void) {
    int sv[2];
    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
    if (sv[0] < 0 || sv[1] < 0) return;

    server s;
    memset(&s, 0, sizeof(s));
    job j;
    memset(&j, 0, sizeof(j));
    j.fd = sv[0];
    request_init(&j.req, REQ_COMPLETION, 128);
    j.req.api = API_OPENAI;
    j.req.stream = true;
    j.req.think_mode = DS4_THINK_NONE;

    cont_stream *st = cont_stream_ensure(&j);
    cont_stream_start(&s, &j);
    TEST_ASSERT(st->started);
    TEST_ASSERT(!st->failed);
    TEST_ASSERT(!strncmp(st->id, "cmpl-", 5));
    for (size_t i = 0; i < sizeof(tape_plain) / sizeof(tape_plain[0]); i++) {
        const char *piece = tape_plain[i].piece;
        /* Inc 7a: drive the SHARED accumulator, the real cont feed path. */
        const sem_feed fr = sem_accum_feed(&st->acc, &j.req, piece, strlen(piece));
        TEST_ASSERT(cont_stream_emit_plain(&j, st, fr.emit_limit));
    }
    cont_stream_finalize(&s, &j, "stop");
    TEST_ASSERT(j.cstream == NULL);
    shutdown(sv[0], SHUT_WR);
    char *out = read_socket_text(sv[1]);

    /* The serial oracle's shape: text_completion everywhere, no chat objects,
     * no role preamble, no delta framing. */
    sse_assert_every_data_object(out, "\"object\":\"text_completion\"",
                                 "chat.completion.chunk");
    TEST_ASSERT(strstr(out, "\"delta\"") == NULL);
    TEST_ASSERT(strstr(out, "\"choices\":[{\"text\":\"Hel\"") != NULL);
    TEST_ASSERT(strstr(out, "\"finish_reason\":\"stop\"") != NULL);
    TEST_ASSERT(strstr(out, "data: [DONE]") != NULL);

    free(out);
    request_free(&j.req);
    close(sv[0]);
    close(sv[1]);
}

/* Inc 4a: transport starts at successful admission (cont_on_admitted) and the
 * prefill heartbeat emits the surface's native keepalive between chunks.
 * Production sends ride the W8a t_emit_job redirect into j->out, so the
 * asserts read the job buffer, exactly what a client thread would drain. */
static char *job_out_text(job *j) {
    return xstrndup(j->out.ptr ? j->out.ptr : "", j->out.len);
}
static void test_cont_admission_transport_and_heartbeat(void) {
    int sv[2];
    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
    if (sv[0] < 0 || sv[1] < 0) return;

    server s;
    memset(&s, 0, sizeof(s));
    cont_sched cs;
    memset(&cs, 0, sizeof(cs));
    cs.s = &s;

    /* OpenAI chat stream: admission starts headers + role preamble and
     * tightens the usage proposal to the engine's split (client frame). */
    job j;
    memset(&j, 0, sizeof(j));
    j.fd = sv[0];
    pthread_mutex_init(&j.mu, NULL);
    pthread_cond_init(&j.cv, NULL);
    request_init(&j.req, REQ_CHAT, 128);
    j.req.api = API_OPENAI;
    j.req.stream = true;
    j.req.think_mode = DS4_THINK_NONE;
    j.req.prompt.len = 10;
    j.req.cache_read_tokens = 10;   /* stale warm proposal the verdict corrects */
    j.req.cache_write_tokens = 0;
    TEST_ASSERT(cont_on_admitted(&cs, &j, 3, 7, 0) == 1);
    TEST_ASSERT(j.req.cache_write_tokens == 7 && j.req.cache_read_tokens == 3);
    TEST_ASSERT(j.cstream && j.cstream->started && !j.cstream->failed);
    TEST_ASSERT(j.cstream->wsess.live_openai);
    {
        char *out = job_out_text(&j);
        TEST_ASSERT(strstr(out, "text/event-stream") != NULL);
        TEST_ASSERT(strstr(out, "\"delta\":{\"role\":\"assistant\"}") != NULL);
        free(out);
    }
    /* Heartbeat: OpenAI-family rows get the serial keepalive comment; the
     * 5s cadence gate holds back an immediate second tick. */
    j.cstream->last_keepalive = now_sec() - 10.0;
    size_t before = j.out.len;
    cont_prefill_heartbeat(&cs, &j);
    {
        char *out = job_out_text(&j);
        TEST_ASSERT(j.out.len > before);
        TEST_ASSERT(strstr(out, ": prefill\n\n") != NULL);
        TEST_ASSERT(strstr(out, "event: ping") == NULL);
        free(out);
    }
    before = j.out.len;
    cont_prefill_heartbeat(&cs, &j);
    TEST_ASSERT(j.out.len == before);   /* inside the cadence window */
    cont_stream_discard(&j);
    buf_free(&j.out);
    request_free(&j.req);

    /* Anthropic chat stream: headers only (its protocol start event is the
     * 4b machine's business), NEVER the OpenAI role preamble, and the
     * heartbeat is the protocol's own ping event. */
    job j2;
    memset(&j2, 0, sizeof(j2));
    j2.fd = sv[0];
    pthread_mutex_init(&j2.mu, NULL);
    pthread_cond_init(&j2.cv, NULL);
    request_init(&j2.req, REQ_CHAT, 128);
    j2.req.api = API_ANTHROPIC;
    j2.req.stream = true;
    j2.req.think_mode = DS4_THINK_NONE;
    j2.req.prompt.len = 4;
    TEST_ASSERT(cont_on_admitted(&cs, &j2, 0, 4, 1) == 1);
    TEST_ASSERT(j2.req.cache_write_tokens == 4 && j2.req.cache_read_tokens == 0);
    TEST_ASSERT(j2.cstream && j2.cstream->started);
    TEST_ASSERT(!j2.cstream->wsess.live_openai);
    TEST_ASSERT(j2.cstream->wsess.surface == DS4_WIRE_ANTHROPIC);
    j2.cstream->last_keepalive = now_sec() - 10.0;
    cont_prefill_heartbeat(&cs, &j2);
    {
        char *out = job_out_text(&j2);
        TEST_ASSERT(strstr(out, "text/event-stream") != NULL);
        TEST_ASSERT(strstr(out, "\"delta\":{\"role\":\"assistant\"}") == NULL);
        TEST_ASSERT(strstr(out, "event: ping") != NULL);
        TEST_ASSERT(strstr(out, "data: {\"type\": \"ping\"}") != NULL);
        TEST_ASSERT(strstr(out, ": prefill\n\n") == NULL);
        free(out);
    }
    cont_stream_discard(&j2);
    buf_free(&j2.out);
    request_free(&j2.req);

    /* Non-streaming row: usage tightening only -- no transport, no stream
     * state (the buffered writers own its bytes at on_done). */
    job j3;
    memset(&j3, 0, sizeof(j3));
    j3.fd = sv[0];
    pthread_mutex_init(&j3.mu, NULL);
    pthread_cond_init(&j3.cv, NULL);
    request_init(&j3.req, REQ_CHAT, 128);
    j3.req.api = API_OPENAI;
    j3.req.stream = false;
    j3.req.prompt.len = 6;
    TEST_ASSERT(cont_on_admitted(&cs, &j3, 6, 9, 2) == 1);
    TEST_ASSERT(j3.req.cache_write_tokens == 6 && j3.req.cache_read_tokens == 0);
    TEST_ASSERT(j3.cstream == NULL && j3.out.len == 0);
    request_free(&j3.req);

    close(sv[0]);
    close(sv[1]);
}

/* Inc 4b: a promoted Anthropic stream on the CONT path projects through the
 * SAME machine the serial path uses -- the identical tape driven through the
 * real cont entry points (cont_stream_start / wire_update /
 * cont_stream_finalize) and through the direct serial calls must produce
 * byte-identical SSE when the id is pinned.  The automata validator runs on
 * the cont bytes too. */
static void test_cont_anthropic_stream_matches_serial_oracle(void) {
    int sv[2];
    server s;
    memset(&s, 0, sizeof(s));

    /* cont path */
    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
    if (sv[0] < 0 || sv[1] < 0) return;
    job j;
    memset(&j, 0, sizeof(j));
    j.fd = sv[0];
    request_init(&j.req, REQ_CHAT, 128);
    j.req.api = API_ANTHROPIC;
    j.req.stream = true;
    j.req.think_mode = DS4_THINK_LOW;
    j.req.prompt.len = 7;
    cont_stream *st = cont_stream_ensure(&j);
    cont_stream_start(&s, &j);        /* headers + message_start (wire_begin) */
    TEST_ASSERT(st->started && !st->failed);
    TEST_ASSERT(st->wsess.protocol_started);
    TEST_ASSERT(st->wsess.surface == DS4_WIRE_ANTHROPIC);
    char id[96];
    snprintf(id, sizeof(id), "%s", st->id);
    int completion = 0;
    for (size_t i = 0; i < sizeof(tape_thinking) / sizeof(tape_thinking[0]); i++) {
        const char *piece = tape_thinking[i].piece;
        /* Inc 7a: drive the SHARED accumulator, the real cont feed path. */
        const sem_feed fr = sem_accum_feed(&st->acc, &j.req, piece, strlen(piece));
        completion++;
        TEST_ASSERT(wire_update(j.fd, &s, &j.req, &st->wsess,
                                st->acc.text.ptr, fr.emit_limit));
    }
    TEST_ASSERT(st->acc.completion == completion);
    cont_stream_finalize(&s, &j, "stop");
    TEST_ASSERT(j.cstream == NULL);
    shutdown(sv[0], SHUT_WR);
    char *cont_out = read_socket_text(sv[1]);
    close(sv[0]);
    close(sv[1]);
    request_free(&j.req);

    /* direct serial machine, same id + tape + counts */
    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
    if (sv[0] < 0 || sv[1] < 0) { free(cont_out); return; }
    request r;
    request_init(&r, REQ_CHAT, 128);
    r.api = API_ANTHROPIC;
    r.stream = true;
    r.think_mode = DS4_THINK_LOW;
    r.prompt.len = 7;
    TEST_ASSERT(sse_headers(sv[0], false));
    anthropic_stream ast;
    TEST_ASSERT(anthropic_sse_start_live(sv[0], &r, id, 7, &ast));
    buf raw = {0};
    for (size_t i = 0; i < sizeof(tape_thinking) / sizeof(tape_thinking[0]); i++) {
        const char *piece = tape_thinking[i].piece;
        buf_append(&raw, piece, strlen(piece));
        TEST_ASSERT(anthropic_sse_stream_update(sv[0], &s, &r, id, &ast,
                                                raw.ptr, raw.len, false));
    }
    tool_calls empty = {0};
    TEST_ASSERT(anthropic_sse_finish_live(sv[0], &s, &r, id, &ast,
                                          raw.ptr, raw.len, &empty, "stop",
                                          NULL, completion));
    shutdown(sv[0], SHUT_WR);
    char *ser_out = read_socket_text(sv[1]);
    close(sv[0]);
    close(sv[1]);

    sse_validate_anthropic_stream(cont_out);
    TEST_ASSERT(strcmp(cont_out, ser_out) == 0);

    anthropic_stream_free(&ast);
    buf_free(&raw);
    free(cont_out);
    free(ser_out);
    request_free(&r);
}

/* Inc 4c: same proof for a promoted Responses stream -- identical tape
 * through the real cont entry points vs the direct serial machine.  The
 * machine mints random resp_/rs_/msg_ ids at init, so equality holds after
 * the Inc 1 first-seen id canonicalization; created_at is pinned by reusing
 * the cont session's value on the direct leg. */
static void test_cont_responses_stream_matches_serial_oracle(void) {
    int sv[2];
    server s;
    memset(&s, 0, sizeof(s));

    /* cont path */
    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
    if (sv[0] < 0 || sv[1] < 0) return;
    job j;
    memset(&j, 0, sizeof(j));
    j.fd = sv[0];
    request_init(&j.req, REQ_CHAT, 128);
    j.req.api = API_RESPONSES;
    j.req.stream = true;
    j.req.think_mode = DS4_THINK_LOW;
    j.req.prompt.len = 7;
    cont_stream *st = cont_stream_ensure(&j);
    cont_stream_start(&s, &j);      /* headers + response.created (wire_begin) */
    TEST_ASSERT(st->started && !st->failed);
    TEST_ASSERT(st->wsess.protocol_started);
    TEST_ASSERT(st->wsess.surface == DS4_WIRE_RESPONSES);
    TEST_ASSERT(st->wsess.live_responses && !st->wsess.live_openai);
    const long pinned_created = st->wsess.created_at;
    int completion = 0;
    for (size_t i = 0; i < sizeof(tape_thinking) / sizeof(tape_thinking[0]); i++) {
        const char *piece = tape_thinking[i].piece;
        /* Inc 7a: drive the SHARED accumulator, the real cont feed path. */
        const sem_feed fr = sem_accum_feed(&st->acc, &j.req, piece, strlen(piece));
        completion++;
        TEST_ASSERT(wire_update(j.fd, &s, &j.req, &st->wsess,
                                st->acc.text.ptr, fr.emit_limit));
    }
    TEST_ASSERT(st->acc.completion == completion);
    /* Inc 7b: the cont terminal reports the accumulator's generation-side
     * reasoning count; the direct serial leg below must render the same
     * number for byte equality (production serial reads the same field). */
    const int pinned_reasoning = st->acc.reasoning_tokens;
    TEST_ASSERT(pinned_reasoning > 0);   /* the thinking tape counts */
    cont_stream_finalize(&s, &j, "stop");
    TEST_ASSERT(j.cstream == NULL);
    shutdown(sv[0], SHUT_WR);
    char *cont_out = read_socket_text(sv[1]);
    close(sv[0]);
    close(sv[1]);
    request_free(&j.req);

    /* direct serial machine, same tape/counts, pinned created_at */
    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
    if (sv[0] < 0 || sv[1] < 0) { free(cont_out); return; }
    request r;
    request_init(&r, REQ_CHAT, 128);
    r.api = API_RESPONSES;
    r.stream = true;
    r.think_mode = DS4_THINK_LOW;
    r.prompt.len = 7;
    TEST_ASSERT(sse_headers(sv[0], false));
    responses_stream rst;
    responses_stream_init(&r, &rst);
    rst.active = true;
    TEST_ASSERT(responses_sse_created(sv[0], &r, &rst, pinned_created));
    buf raw = {0};
    for (size_t i = 0; i < sizeof(tape_thinking) / sizeof(tape_thinking[0]); i++) {
        const char *piece = tape_thinking[i].piece;
        buf_append(&raw, piece, strlen(piece));
        TEST_ASSERT(responses_sse_stream_update(sv[0], &r, &rst,
                                                raw.ptr, raw.len, false));
    }
    tool_calls empty = {0};
    TEST_ASSERT(responses_sse_finish_live(sv[0], &r, &rst, raw.ptr, raw.len,
                                          NULL, &empty, "stop", 7, completion,
                                          pinned_reasoning /* Inc 7b: acc count */,
                                          pinned_created));
    shutdown(sv[0], SHUT_WR);
    char *ser_out = read_socket_text(sv[1]);
    close(sv[0]);
    close(sv[1]);

    char *cn = wire_test_canonicalize_ids(cont_out);
    char *sn = wire_test_canonicalize_ids(ser_out);
    TEST_ASSERT(strstr(cn, "\"type\":\"response.created\"") != NULL);
    TEST_ASSERT(strstr(cn, "\"type\":\"response.completed\"") != NULL);
    TEST_ASSERT(strcmp(cn, sn) == 0);

    responses_stream_free(&rst);
    buf_free(&raw);
    free(cn);
    free(sn);
    free(cont_out);
    free(ser_out);
    request_free(&r);
}

/* Inc 0b: the three-state decode-budget contract shared by every lane site
 * (serial decode loop, serial fit, footprint, static pack, cont admit).
 * Before the helper, the batched lanes replaced ANY <= 0 with the server
 * default while serial honored it as zero decode -- the route-divergence
 * the plan's normalization step removes. */
static void test_request_decode_budget_three_states(void) {
    request r;
    request_init(&r, REQ_CHAT, 393216);          /* parser-preloaded default */
    TEST_ASSERT(request_decode_budget(&r, 393216) == 393216);   /* OMITTED */
    r.max_tokens = 4096;
    r.max_tokens_set = true;
    TEST_ASSERT(request_decode_budget(&r, 393216) == 4096);     /* POSITIVE */
    r.max_tokens = 0;
    TEST_ASSERT(request_decode_budget(&r, 393216) == 0);        /* EXPLICIT 0 */
    r.max_tokens = -5;
    TEST_ASSERT(request_decode_budget(&r, 393216) == 0);        /* EXPLICIT <0 */
    request_free(&r);
}

/* deepmem D-1c: pure-arithmetic tests for ds4_credit_union_runs (ds4.h),
 * the page-interval merge under the continuous-admission credit projection.
 * Production (credit_union_family, ds4.c) binds the resident subtraction
 * over these exact runs, so these shapes pin the union semantics the
 * admission verdicts charge: page-sharing neighbor banks merge into one
 * run (union < sum of per-bank rounded spans), nonadjacent banks stay
 * separate runs, the candidate slot overrides its credit, rows clamp at
 * cap, and empty credit sets contribute nothing.
 * Geometry: page 4096, row_bytes 64, cap_rows 100 (full bank 6400 B),
 * stride 6500 (> full bank, NOT a page multiple -- neighbor banks share an
 * edge page exactly like the 2 MiB VMM slabs on GB10). */
#define CU_TEST_MAX_RUNS 8
typedef struct {
    uint64_t off[CU_TEST_MAX_RUNS], span[CU_TEST_MAX_RUNS];
    int n;
} cu_test_runs;
static uint64_t test_cu_record_run(void *user, uint64_t off, uint64_t span) {
    cu_test_runs *r = (cu_test_runs *)user;
    TEST_ASSERT(r->n < CU_TEST_MAX_RUNS);
    r->off[r->n] = off;
    r->span[r->n] = span;
    r->n++;
    return span;   /* zero resident: need == span */
}
static void test_credit_union_merge_shapes(void) {
    const uint64_t page = 4096, rowb = 64, cap = 100, stride = 6500;
    const uint32_t ratio = 4, nb = 4;
    cu_test_runs r;

    /* nonadjacent banks 0+2 -> two runs at their own page spans */
    memset(&r, 0, sizeof(r));
    uint64_t credit_a[4] = {2000, 0, 2000, 0};
    uint64_t need = ds4_credit_union_runs(stride, rowb, cap, ratio, page,
                                          credit_a, nb, nb, 0,
                                          test_cu_record_run, &r);
    TEST_ASSERT(r.n == 2);
    TEST_ASSERT(r.off[0] == 0 && r.span[0] == 2 * page);        /* pages 0-1 */
    TEST_ASSERT(r.off[1] == 3 * page && r.span[1] == 2 * page); /* pages 3-4 */
    TEST_ASSERT(need == 4 * page);

    /* adjacent banks 0+1 share the edge page -> ONE merged run, and the
     * union (4 pages) beats independent per-bank rounding (2 + 3 pages) */
    memset(&r, 0, sizeof(r));
    uint64_t credit_b[4] = {2000, 2000, 0, 0};
    need = ds4_credit_union_runs(stride, rowb, cap, ratio, page,
                                 credit_b, nb, nb, 0,
                                 test_cu_record_run, &r);
    TEST_ASSERT(r.n == 1);
    TEST_ASSERT(r.off[0] == 0 && r.span[0] == 4 * page);        /* pages 0-3 */
    TEST_ASSERT(need == 4 * page && need < 5 * page);

    /* candidate slot overrides its credit entry: a huge stale credit[1]
     * must not leak in when the candidate's own target is tiny */
    memset(&r, 0, sizeof(r));
    uint64_t credit_c[4] = {2000, 999999, 0, 0};
    need = ds4_credit_union_runs(stride, rowb, cap, ratio, page,
                                 credit_c, nb, 1, 4,
                                 test_cu_record_run, &r);
    TEST_ASSERT(r.n == 1);
    TEST_ASSERT(r.span[0] == 2 * page);   /* tiny cand merges into pages 0-1 */
    TEST_ASSERT(need == 2 * page);

    /* rows clamp at cap_rows: an absurd credit still costs one full bank */
    memset(&r, 0, sizeof(r));
    uint64_t credit_d[4] = {1000000000ull, 0, 0, 0};
    need = ds4_credit_union_runs(stride, rowb, cap, ratio, page,
                                 credit_d, nb, nb, 0,
                                 test_cu_record_run, &r);
    TEST_ASSERT(r.n == 1 && r.span[0] == 2 * page && need == 2 * page);

    /* nothing credited, no candidate -> zero runs, zero need */
    memset(&r, 0, sizeof(r));
    uint64_t credit_e[4] = {0, 0, 0, 0};
    need = ds4_credit_union_runs(stride, rowb, cap, ratio, page,
                                 credit_e, nb, nb, 0,
                                 test_cu_record_run, &r);
    TEST_ASSERT(r.n == 0 && need == 0);
}
static uint64_t test_cu_first_run_free(void *user, uint64_t off, uint64_t span) {
    (void)user;
    return off == 0 ? 0 : span;   /* fully-resident first run charges nothing */
}
static void test_credit_union_sums_per_run_need(void) {
    const uint64_t page = 4096, rowb = 64, cap = 100, stride = 6500;
    uint64_t credit[4] = {2000, 0, 2000, 0};   /* the nonadjacent shape */
    uint64_t need = ds4_credit_union_runs(stride, rowb, cap, 4u, page,
                                          credit, 4, 4, 0,
                                          test_cu_first_run_free, NULL);
    TEST_ASSERT(need == 2 * page);   /* only the second run still charges */
}

/* MT-1b (v0.6.1 memory truth): pure tranche-extension arithmetic (ds4.h
 * inlines).  Pins the margin trigger (due exactly when pos + margin
 * reaches the credited end), the tranche walk with its true-target clamp,
 * the legacy kill switch, and the funded-boundary invariant: an extension
 * is due BEFORE the margin's worth of steps can reach the boundary, and
 * the refusal clamp finishes the row with its last KV write at
 * credit_end - 1. */
static void test_cont_credit_ext_due_shapes(void) {
    uint64_t nf = 0;

    /* tranche 0 = legacy kill switch: never due, even at the boundary */
    TEST_ASSERT(!ds4_cont_credit_ext_due(999, 1000, 5000, 8, 0, &nf));
    /* fully funded (credit_end == target): nothing to extend */
    TEST_ASSERT(!ds4_cont_credit_ext_due(999, 1000, 1000, 8, 100, &nf));
    /* far from the boundary: not due */
    TEST_ASSERT(!ds4_cont_credit_ext_due(500, 1000, 5000, 8, 100, &nf));
    /* the margin trigger is exact: pos + margin < end -> wait; == -> due */
    TEST_ASSERT(!ds4_cont_credit_ext_due(991, 1000, 5000, 8, 100, &nf));
    TEST_ASSERT(ds4_cont_credit_ext_due(992, 1000, 5000, 8, 100, &nf));
    TEST_ASSERT(nf == 1100);            /* one tranche */
    /* the last tranche clamps at the true target */
    TEST_ASSERT(ds4_cont_credit_ext_due(995, 1000, 1050, 8, 100, &nf));
    TEST_ASSERT(nf == 1050);
    /* a huge tranche funds the remainder in one step */
    TEST_ASSERT(ds4_cont_credit_ext_due(995, 1000, 5000, 8, 1u << 20, &nf));
    TEST_ASSERT(nf == 5000);
}
static void test_cont_credit_refuse_bmax_clamp(void) {
    /* row at pos 990 with 40 generated, funded through 1000: 10 more
     * tokens -> terminal fires at glen 50 with the last KV row at 999 */
    TEST_ASSERT(ds4_cont_credit_refuse_bmax(40, 990, 1000) == 50);
    /* at the boundary exactly: zero remain, terminal fires immediately */
    TEST_ASSERT(ds4_cont_credit_refuse_bmax(40, 1000, 1000) == 40);
    /* pathological pos past end floors at glen (never extends the cap) */
    TEST_ASSERT(ds4_cont_credit_refuse_bmax(40, 1005, 1000) == 40);
}
/* MT-5 (audit V6): the ctx-aware requested-banks default.  Anchors: 32
 * through the W8-measured regime (<=16384), halving against the ~1 Mi
 * fundable-token depth, floor 4 (fork fanout). */
static void test_coalesce_max_default_tiers(void) {
    TEST_ASSERT(coalesce_max_default(4096)   == 32);   /* the W8 shape */
    TEST_ASSERT(coalesce_max_default(16384)  == 32);   /* regime boundary */
    TEST_ASSERT(coalesce_max_default(32768)  == 32);   /* 32 x 32k == anchor */
    TEST_ASSERT(coalesce_max_default(57344)  == 16);   /* the mid-ctx shape */
    TEST_ASSERT(coalesce_max_default(131072) == 8);
    TEST_ASSERT(coalesce_max_default(262144) == 4);
    TEST_ASSERT(coalesce_max_default(524288) == 4);    /* floor holds */
    TEST_ASSERT(coalesce_max_default(786432) == 4);    /* the leg2a shape */
}

/* Governed cont bank plan (v0.6.2): the pure KV-aware plan bound the
 * engine's create_fit applies (ds4_batch_plan_kv_banks).  Shapes mirror
 * the ship box: tens-of-GiB boot budgets, kv-bank commits (seq_cap x
 * banded packed rate) from the deep ledger. */
static void test_batch_plan_kv_banks(void) {
    const uint64_t GiB = 1ull << 30;
    /* deep ctx: full-depth funding runs out below the floor -- the A2b
     * fanout floor holds (floor banks ride the admission gate, exactly
     * the ladder's 4 @ 262k+ posture) */
    TEST_ASSERT(ds4_batch_plan_kv_banks(48 * GiB, 16 * GiB, 100u, 4u) == 4u);
    /* mid ctx: the live budget funds MORE than the frozen ladder said
     * (the v0.6.1 pessimism kill: 12 fully-funded banks where the ladder
     * froze 8) */
    TEST_ASSERT(ds4_batch_plan_kv_banks(48 * GiB, 4 * GiB, 100u, 4u) == 12u);
    /* the eager fit still caps: a floor the eager slabs cannot fund is
     * not granted */
    TEST_ASSERT(ds4_batch_plan_kv_banks(48 * GiB, 16 * GiB, 3u, 4u) == 3u);
    /* shallow ctx: plan-bound above the eager count changes nothing */
    TEST_ASSERT(ds4_batch_plan_kv_banks(48 * GiB, GiB / 2, 32u, 4u) == 32u);
    /* no physics answer -> the eager fit's count passes through */
    TEST_ASSERT(ds4_batch_plan_kv_banks(48 * GiB, 0, 7u, 4u) == 7u);
    /* zero budget still grants the floor (the fit's own 2-bank poke and
     * the physical descent stay the safety below it) */
    TEST_ASSERT(ds4_batch_plan_kv_banks(0, 16 * GiB, 100u, 4u) == 4u);
}

/* MT-7: the disclosed admission band -- clamp, physics floor, round-up. */
static void test_cont_admit_band_apply(void) {
    /* 1024 = physics-exact: identity at any need */
    TEST_ASSERT(ds4_cont_admit_band_apply(0, 1024) == 0);
    TEST_ASSERT(ds4_cont_admit_band_apply(1048576, 1024) == 1048576);
    /* the default 1045 (~1.02x): rounds UP, never shrinks a nonzero need */
    TEST_ASSERT(ds4_cont_admit_band_apply(1048576, 1045) == 1070080);
    TEST_ASSERT(ds4_cont_admit_band_apply(1, 1045) == 2);
    /* clamp low: anything below 1024 charges physics-exact */
    TEST_ASSERT(ds4_cont_admit_band_apply(1048576, 0) == 1048576);
    TEST_ASSERT(ds4_cont_admit_band_apply(1048576, 512) == 1048576);
    /* clamp high: 2048 is the sanity cap (2x physics) */
    TEST_ASSERT(ds4_cont_admit_band_apply(1048576, 4096) == 2097152);
    TEST_ASSERT(ds4_cont_admit_band_apply(1048576, 2048) == 2097152);
}

/* MT-7: the commit-rate tripwire -- sample gate, 2x boundary, guards. */
static void test_cont_rate_anomalous(void) {
    /* below the sample gate: page floors dominate, never trips */
    TEST_ASSERT(!ds4_cont_rate_anomalous(1u << 30, 100, 4096, 65536));
    /* zero physics rate or zero min_tokens: undefined comparison, no trip */
    TEST_ASSERT(!ds4_cont_rate_anomalous(1u << 30, 100000, 0, 65536));
    TEST_ASSERT(!ds4_cont_rate_anomalous(1u << 30, 100000, 4096, 0));
    /* at the boundary exactly (obs == 2x phys): not anomalous */
    TEST_ASSERT(!ds4_cont_rate_anomalous(2ull * 4096 * 100000, 100000, 4096, 65536));
    /* one byte past: trips */
    TEST_ASSERT(ds4_cont_rate_anomalous(2ull * 4096 * 100000 + 1, 100000, 4096, 65536));
    /* the healthy ship shape: obs ~= phys, never trips */
    TEST_ASSERT(!ds4_cont_rate_anomalous(4300ull * 500000, 500000, 4096, 65536));
}

/* Rider #48: content fingerprint determinism + size folding on the
 * small-file full-hash branch. */
static void test_weight_fp_small(void) {
    unsigned char buf[4096];
    for (size_t i = 0; i < sizeof(buf); i++) buf[i] = (unsigned char)(i * 7u + 3u);
    uint64_t a = ds4_weight_content_fingerprint(buf, sizeof(buf));
    TEST_ASSERT(a == ds4_weight_content_fingerprint(buf, sizeof(buf)));
    /* any flipped byte differs (small files hash fully) */
    buf[2048] ^= 0x40u;
    TEST_ASSERT(a != ds4_weight_content_fingerprint(buf, sizeof(buf)));
    buf[2048] ^= 0x40u;
    TEST_ASSERT(a == ds4_weight_content_fingerprint(buf, sizeof(buf)));
    /* equal prefix, different length differs (the size fold) */
    TEST_ASSERT(a != ds4_weight_content_fingerprint(buf, sizeof(buf) - 1));
    /* empty/NULL are stable and distinct from data */
    TEST_ASSERT(ds4_weight_content_fingerprint(NULL, 0) ==
                ds4_weight_content_fingerprint(NULL, 0));
    TEST_ASSERT(a != ds4_weight_content_fingerprint(NULL, 0));
}

/* Rider #48: the strided-sample geometry contract on large files -- head,
 * tail, and stride pages are covered; bytes BETWEEN sample windows are
 * invisible BY DESIGN (mixup detection, not tamper-proofing).  This test
 * pins both directions so a geometry change that silently widens or
 * narrows coverage fails here first. */
static void test_weight_fp_stride_geometry(void) {
    const uint64_t n = 24ull << 20; /* head 4M + strides at 16M + tail 4M */
    unsigned char *buf = (unsigned char *)calloc(1, (size_t)n);
    TEST_ASSERT(buf != NULL);
    uint64_t fp0 = ds4_weight_content_fingerprint(buf, n);
    /* head window covered */
    buf[100] = 1;
    TEST_ASSERT(fp0 != ds4_weight_content_fingerprint(buf, n));
    buf[100] = 0;
    /* stride page at 16 MiB covered */
    buf[(16ull << 20) + 100] = 1;
    TEST_ASSERT(fp0 != ds4_weight_content_fingerprint(buf, n));
    buf[(16ull << 20) + 100] = 0;
    /* tail window covered */
    buf[n - 100] = 1;
    TEST_ASSERT(fp0 != ds4_weight_content_fingerprint(buf, n));
    buf[n - 100] = 0;
    /* between windows: invisible by design */
    buf[(8ull << 20) + 100] = 1;
    TEST_ASSERT(fp0 == ds4_weight_content_fingerprint(buf, n));
    buf[(8ull << 20) + 100] = 0;
    free(buf);
}

/* Inc 7a: the extracted accumulator's own contract -- verdict precedence,
 * stop capture + truncation, one-shot transitions, think-gated markers.
 * The serial/cont byte equivalence is pinned by the oracle tests above;
 * this pins the machine the two drivers now share. */
static void test_sem_accum_feed_verdicts(void) {
    /* 1) stop hit: emit_limit == match start, matched_stop captured, text
     * truncated (stop excluded), verdict "stop". */
    request r;
    request_init(&r, REQ_CHAT, 128);
    r.api = API_OPENAI;
    r.think_mode = DS4_THINK_NONE;
    stop_list_push(&r.stops, xstrdup("END"));
    sem_accum a;
    sem_accum_init(&a, &r);
    sem_feed f = sem_accum_feed(&a, &r, "hello ", 6);
    TEST_ASSERT(!f.hit_stop && !a.verdict);
    TEST_ASSERT(f.emit_limit == 4);   /* len 6 minus the 2-byte stop hold */
    f = sem_accum_feed(&a, &r, "world END tail", 14);
    TEST_ASSERT(f.hit_stop);
    TEST_ASSERT(a.verdict && !strcmp(a.verdict, "stop"));
    TEST_ASSERT(a.matched_stop && !strcmp(a.matched_stop, "END"));
    TEST_ASSERT(f.emit_limit == a.text.len);
    TEST_ASSERT(!strcmp(a.text.ptr, "hello world "));
    TEST_ASSERT(a.completion == 2);
    TEST_ASSERT(a.reasoning_tokens == 0);   /* Inc 7b: think off -> no count */
    sem_accum_free(&a);
    request_free(&r);

    /* 2) tool block close: one-shot enter/close transitions, verdict
     * "tool_calls"; a stop hit on the SAME feed would win (both twins break
     * on stop first) -- proven by feeding stop+close together in (3). */
    request rt;
    request_init(&rt, REQ_CHAT, 128);
    rt.api = API_OPENAI;
    rt.has_tools = true;
    rt.think_mode = DS4_THINK_NONE;
    sem_accum b;
    sem_accum_init(&b, &rt);
    f = sem_accum_feed(&b, &rt, "calling.\n" DS4_TOOL_CALLS_START,
                       strlen("calling.\n") + strlen(DS4_TOOL_CALLS_START));
    TEST_ASSERT(f.entered_tool_block && b.saw_tool_start && !b.saw_tool_end);
    f = sem_accum_feed(&b, &rt, DS4_TOOL_CALLS_END, strlen(DS4_TOOL_CALLS_END));
    TEST_ASSERT(f.tool_block_closed && b.saw_tool_end);
    TEST_ASSERT(b.verdict && !strcmp(b.verdict, "tool_calls"));
    sem_accum_free(&b);

    /* 3) stop beats tool close when one feed carries both. */
    stop_list_push(&rt.stops, xstrdup("XSTOPX"));
    sem_accum c;
    sem_accum_init(&c, &rt);
    buf both = {0};
    buf_puts(&both, DS4_TOOL_CALLS_START);
    buf_puts(&both, DS4_TOOL_CALLS_END);
    buf_puts(&both, "XSTOPX");
    f = sem_accum_feed(&c, &rt, both.ptr, both.len);
    TEST_ASSERT(f.hit_stop && c.saw_tool_end);
    TEST_ASSERT(c.verdict && !strcmp(c.verdict, "stop"));
    buf_free(&both);
    sem_accum_free(&c);
    request_free(&rt);

    /* 4) think gating: a marker inside <think> is not observed; after
     * </think> the scan resumes past the close. */
    request rk;
    request_init(&rk, REQ_CHAT, 128);
    rk.api = API_OPENAI;
    rk.has_tools = true;
    rk.think_mode = DS4_THINK_LOW;
    free(rk.prompt_text);
    rk.prompt_text = xstrdup("<think>");   /* generation starts inside */
    sem_accum d;
    sem_accum_init(&d, &rk);
    TEST_ASSERT(d.thinking.inside && d.tool_scan_waiting_for_think_close);
    f = sem_accum_feed(&d, &rk, DS4_TOOL_CALLS_START, strlen(DS4_TOOL_CALLS_START));
    TEST_ASSERT(!d.saw_tool_start);        /* quoted in reasoning: inert */
    f = sem_accum_feed(&d, &rk, "</think>ok ", 11);
    TEST_ASSERT(!d.saw_tool_start && !d.tool_scan_waiting_for_think_close);
    f = sem_accum_feed(&d, &rk, DS4_TOOL_CALLS_START, strlen(DS4_TOOL_CALLS_START));
    TEST_ASSERT(f.entered_tool_block && d.saw_tool_start);
    /* Inc 7b: generation-side reasoning count -- the two feeds made while
     * inside <think> (the closer's feed counts; post-close feeds do not). */
    TEST_ASSERT(d.reasoning_tokens == 2);
    sem_accum_free(&d);
    request_free(&rk);
}

/* v0.5.7 C1: DSML tool-call syntax is TERMINAL on no-tools chat requests --
 * the visible channel cuts at the marker (finish=stop, nothing invented in
 * matched_stop), partial markers are held off the wire, and think-quoted
 * DSML stays inert.  Field receipt: codex compact-summary poisoning
 * (local/docs/v0561/cut_receipt_2026-08-09.md). */
static void test_sem_accum_no_tools_dsml_cut(void) {
    /* 1) visible marker cuts exactly at the marker start. */
    request r;
    request_init(&r, REQ_CHAT, 128);
    r.api = API_OPENAI;
    r.think_mode = DS4_THINK_NONE;
    TEST_ASSERT(!r.has_tools);
    sem_accum a;
    sem_accum_init(&a, &r);
    TEST_ASSERT(a.cut_tool_syntax && !a.track_tools);
    sem_feed f = sem_accum_feed(&a, &r, "Summary line.\n\n", 15);
    TEST_ASSERT(!f.hit_stop && !a.verdict);
    f = sem_accum_feed(&a, &r, DS4_TOOL_CALLS_START, strlen(DS4_TOOL_CALLS_START));
    TEST_ASSERT(f.tool_syntax_cut && f.hit_stop);
    TEST_ASSERT(a.verdict && !strcmp(a.verdict, "stop"));
    TEST_ASSERT(!a.matched_stop);            /* no stop_sequence invented */
    TEST_ASSERT(!strcmp(a.text.ptr, "Summary line.\n\n"));
    TEST_ASSERT(f.emit_limit == a.text.len); /* streamed == buffered */
    sem_accum_free(&a);
    request_free(&r);

    /* 2) hold-back: a tail that could begin a marker stays off the wire
     * until it disambiguates. */
    request r2;
    request_init(&r2, REQ_CHAT, 128);
    r2.api = API_OPENAI;
    r2.think_mode = DS4_THINK_NONE;
    sem_accum b;
    sem_accum_init(&b, &r2);
    f = sem_accum_feed(&b, &r2, "ok ", 3);
    TEST_ASSERT(f.emit_limit == 3);
    f = sem_accum_feed(&b, &r2, "<", 1);
    TEST_ASSERT(f.emit_limit == 3);          /* "<" held back */
    TEST_ASSERT(!f.hit_stop && !b.verdict);
    f = sem_accum_feed(&b, &r2, "b", 1);
    TEST_ASSERT(f.emit_limit == 5);          /* "<b" diverged: released */
    sem_accum_free(&b);
    request_free(&r2);

    /* 3) think gating carries over: DSML quoted in reasoning is inert; the
     * first VISIBLE marker after </think> cuts. */
    request rk;
    request_init(&rk, REQ_CHAT, 128);
    rk.api = API_OPENAI;
    rk.think_mode = DS4_THINK_LOW;
    free(rk.prompt_text);
    rk.prompt_text = xstrdup("<think>");
    sem_accum d;
    sem_accum_init(&d, &rk);
    TEST_ASSERT(d.cut_tool_syntax);
    f = sem_accum_feed(&d, &rk, DS4_TOOL_CALLS_START, strlen(DS4_TOOL_CALLS_START));
    TEST_ASSERT(!f.tool_syntax_cut && !d.verdict);   /* reasoning: inert */
    f = sem_accum_feed(&d, &rk, "</think>done ", 13);
    TEST_ASSERT(!f.tool_syntax_cut && !d.verdict);
    const size_t visible_len = d.text.len;
    f = sem_accum_feed(&d, &rk, DS4_TOOL_CALLS_START, strlen(DS4_TOOL_CALLS_START));
    TEST_ASSERT(f.tool_syntax_cut && f.hit_stop);
    TEST_ASSERT(d.verdict && !strcmp(d.verdict, "stop"));
    TEST_ASSERT(d.text.len == visible_len);  /* cut at the visible marker */
    sem_accum_free(&d);
    request_free(&rk);

    /* 4) finalize gate: without tools nothing is ever extracted as a call
     * and finish cannot become tool_calls, whatever the text contains. */
    tool_calls calls = {0};
    char *content = NULL, *reasoning = NULL;
    char err[64] = {0};
    const char *finish = "stop";
    bool recovered = false;
    buf t = {0};
    buf_puts(&t, "summary text\n\n");
    buf_puts(&t, DS4_TOOL_CALLS_START);
    buf_puts(&t, DS4_TOOL_CALLS_END);
    bool ok = parse_generated_message_for_response(t.ptr, false, true, false,
                                                   &finish, err, sizeof(err),
                                                   &content, &reasoning, &calls,
                                                   &recovered);
    TEST_ASSERT(ok && calls.len == 0 && !recovered);
    TEST_ASSERT(!strcmp(finish, "stop"));
    TEST_ASSERT(content && strstr(content, "summary text"));
    free(content);
    free(reasoning);
    tool_calls_free(&calls);
    buf_free(&t);
}

/* v0.5.7 C3: the shared stream heartbeat speaks each protocol -- Anthropic
 * gets the native ping event, the OpenAI family gets an ignorable SSE
 * comment.  (The 5 s cadence itself is wall-clock-gated in the drivers and
 * deliberately cannot fire inside fast unit fixtures.) */
static void test_stream_heartbeat_emit(void) {
    int p[2];   /* send() needs a socket, not a pipe (ENOTSOCK) */
    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, p) == 0);
    char out[512];
    ssize_t n;
    request r;
    request_init(&r, REQ_CHAT, 128);

    /* Anthropic: the native ping event. */
    r.api = API_ANTHROPIC;
    TEST_ASSERT(stream_heartbeat_emit(p[1], &r, NULL, ": decode\n\n"));
    n = read(p[0], out, sizeof(out) - 1);
    TEST_ASSERT(n > 0);
    out[n] = '\0';
    TEST_ASSERT(strstr(out, "event: ping") && strstr(out, "\"type\": \"ping\""));

    /* OpenAI family without a live Responses machine: comment only. */
    r.api = API_RESPONSES;
    TEST_ASSERT(stream_heartbeat_emit(p[1], &r, NULL, ": decode\n\n"));
    n = read(p[0], out, sizeof(out) - 1);
    TEST_ASSERT(n > 0);
    out[n] = '\0';
    TEST_ASSERT(!strcmp(out, ": decode\n\n"));

    /* Live Responses machine: a REAL response.in_progress event continuing
     * the machine's sequence counter (codex's idle timer only sees parsed
     * events, run10). */
    responses_stream rs;
    responses_stream_init(&r, &rs);
    rs.created_at = 1786316295;
    rs.sequence = 7;
    TEST_ASSERT(stream_heartbeat_emit(p[1], &r, &rs, ": decode\n\n"));
    n = read(p[0], out, sizeof(out) - 1);
    TEST_ASSERT(n > 0);
    out[n] = '\0';
    TEST_ASSERT(strstr(out, "\"type\":\"response.in_progress\""));
    TEST_ASSERT(strstr(out, "\"sequence_number\":7"));
    TEST_ASSERT(strstr(out, "\"status\":\"in_progress\""));
    TEST_ASSERT(rs.sequence == 8);

    /* created not yet on the wire: ordering safety, stays a comment. */
    responses_stream rs2;
    responses_stream_init(&r, &rs2);
    TEST_ASSERT(stream_heartbeat_emit(p[1], &r, &rs2, ": decode\n\n"));
    n = read(p[0], out, sizeof(out) - 1);
    TEST_ASSERT(n > 0);
    out[n] = '\0';
    TEST_ASSERT(!strcmp(out, ": decode\n\n"));

    responses_stream_free(&rs);
    responses_stream_free(&rs2);
    request_free(&r);
    close(p[0]);
    close(p[1]);
}

/* v0.5.7 C2: the /v1/models codex-splice array extractor -- string-aware
 * bracket matching over operator-provided catalog JSON. */
static void test_json_models_array_dup(void) {
    /* Well-formed catalog: the array comes back verbatim, brackets included. */
    char *a = json_models_array_dup(
        "{\"models\": [{\"slug\":\"x\",\"nested\":[1,2]}] }");
    TEST_ASSERT(a && !strcmp(a, "[{\"slug\":\"x\",\"nested\":[1,2]}]"));
    free(a);

    /* A "models" decoy inside a string value must not satisfy the search;
     * the real key after it still does. */
    a = json_models_array_dup(
        "{\"desc\":\"\\\"models\\\": fake\",\"models\":[{\"s\":\"]\"}]}");
    TEST_ASSERT(a && !strcmp(a, "[{\"s\":\"]\"}]"));
    free(a);

    /* Escaped quotes and brackets inside strings do not move the depth. */
    a = json_models_array_dup(
        "{\"models\":[{\"i\":\"a\\\\\\\"[\",\"j\":\"]\"}]}");
    TEST_ASSERT(a && a[0] == '[' && a[strlen(a) - 1] == ']');
    free(a);

    /* Unterminated array / missing key / non-array value: NULL, no crash. */
    TEST_ASSERT(!json_models_array_dup("{\"models\":[{\"s\":1}"));
    TEST_ASSERT(!json_models_array_dup("{\"data\":[1]}"));
    TEST_ASSERT(!json_models_array_dup("{\"models\":{\"s\":1}}"));
}

/* Inc 0b (#13 twin): an unrepairable mid-toolcall budget cut on the cont
 * lane keeps the honest "length" finish and returns the partial call as
 * assistant text, mirroring the serial dcc2623 behavior; a non-budget
 * unterminated block (EOS mid-call) still reports "error".  The live twin
 * is finish_reason_gate.sh, whose engagement oracle can now fire on the
 * lane that actually serves chat+tools. */
static void test_cont_budget_cut_toolcall_keeps_length(void) {
    server s;
    memset(&s, 0, sizeof(s));
    pthread_mutex_init(&s.tool_mu, NULL);
    job j;
    memset(&j, 0, sizeof(j));
    request_init(&j.req, REQ_CHAT, 128);
    j.req.api = API_OPENAI;
    j.req.has_tools = true;
    j.req.think_mode = DS4_THINK_NONE;

    cont_stream *st = cont_stream_ensure(&j);
    const char *cut = "I will check the weather.\n\n" DS4_TOOL_CALLS_START
                      "\nprose the budget cut before any invoke tag";
    /* Inc 7a: the shared accumulator's own marker scan observes the start. */
    (void)sem_accum_feed(&st->acc, &j.req, cut, strlen(cut));
    TEST_ASSERT(st->acc.saw_tool_start && !st->acc.saw_tool_end);

    const char *fin = "length";
    char *content = NULL, *reasoning = NULL;
    tool_calls calls = {0};
    cont_resolve_chat(&s, &j, st, &fin, &content, &reasoning, &calls);
    TEST_ASSERT(!strcmp(fin, "length"));
    TEST_ASSERT(calls.len == 0);
    TEST_ASSERT(content && content[0]);
    free(content);
    free(reasoning);
    tool_calls_free(&calls);
    content = NULL;
    reasoning = NULL;

    /* EOS inside an unterminated block is not a budget cut: still "error". */
    fin = "stop";
    cont_resolve_chat(&s, &j, st, &fin, &content, &reasoning, &calls);
    TEST_ASSERT(!strcmp(fin, "error"));
    free(content);
    free(reasoning);
    tool_calls_free(&calls);

    cont_stream_discard(&j);
    request_free(&j.req);
    pthread_mutex_destroy(&s.tool_mu);
}

/* Contract record: the HTTP reader parses Content-Length,
 * Transfer-Encoding (v0.6.3), and Accept; an Idempotency-Key header is
 * accepted and silently discarded, so a retry is a NEW generation with
 * new IDs.  Documented unsupported in docs/ds4-api-surface-matrix.md. */
static void test_idempotency_key_header_is_ignored(void) {
    int sv[2];
    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
    if (sv[0] < 0 || sv[1] < 0) return;

    const char *req =
        "POST /v1/messages HTTP/1.1\r\n"
        "Content-Length: 2\r\n"
        "Idempotency-Key: retry-me-42\r\n"
        "Accept: application/json\r\n"
        "\r\n"
        "{}";
    TEST_ASSERT(send(sv[0], req, strlen(req), 0) == (ssize_t)strlen(req));
    shutdown(sv[0], SHUT_WR);

    http_request hr;
    memset(&hr, 0, sizeof(hr));
    TEST_ASSERT(read_http_request(sv[1], &hr));
    TEST_ASSERT(!strcmp(hr.method, "POST"));
    TEST_ASSERT(!strcmp(hr.path, "/v1/messages"));
    TEST_ASSERT(hr.body_len == 2 && !strcmp(hr.body, "{}"));
    TEST_ASSERT(hr.accept_json);
    /* http_request has no field for the key: dropped by omission. */
    http_request_free(&hr);
    close(sv[0]);
    close(sv[1]);
}

/* v0.6.3 Inc 2: chunked request decoding.  Every wire image is written
 * whole then the write side shut down, so a decoder that over-reads hits
 * EOF and fails instead of hanging.  The kill-switch leg pins the
 * pre-v0.6.3 behavior (chunked read as a zero-length body) -- that is the
 * shape the field's proxied requests died with. */
static bool chunked_reader_run(const char *wire, http_request *hr) {
    int sv[2];
    if (socketpair(AF_UNIX, SOCK_STREAM, 0, sv) != 0) return false;
    memset(hr, 0, sizeof(*hr));
    const ssize_t n = (ssize_t)strlen(wire);
    bool ok = send(sv[0], wire, (size_t)n, 0) == n;
    shutdown(sv[0], SHUT_WR);
    ok = ok && read_http_request(sv[1], hr);
    close(sv[0]);
    close(sv[1]);
    return ok;
}

static void test_chunked_request_decoding(void) {
    http_request hr;

    /* Single chunk. */
    TEST_ASSERT(chunked_reader_run(
        "POST /v1/messages HTTP/1.1\r\n"
        "Transfer-Encoding: chunked\r\n"
        "\r\n"
        "b\r\nhello world\r\n0\r\n\r\n", &hr));
    TEST_ASSERT(hr.body_len == 11 && !strcmp(hr.body, "hello world"));
    http_request_free(&hr);

    /* Multiple chunks, an extension, and a trailer. */
    TEST_ASSERT(chunked_reader_run(
        "POST /v1/chat/completions HTTP/1.1\r\n"
        "Transfer-Encoding: chunked\r\n"
        "\r\n"
        "5;ext=1\r\nhello\r\n6\r\n world\r\n0\r\nX-Trailer: v\r\n\r\n", &hr));
    TEST_ASSERT(hr.body_len == 11 && !strcmp(hr.body, "hello world"));
    http_request_free(&hr);

    /* Terminator only: empty body, still a successful read. */
    TEST_ASSERT(chunked_reader_run(
        "POST /v1/completions HTTP/1.1\r\n"
        "Transfer-Encoding: chunked\r\n"
        "\r\n"
        "0\r\n\r\n", &hr));
    TEST_ASSERT(hr.body_len == 0 && hr.body[0] == '\0');
    http_request_free(&hr);

    /* RFC 7230 3.3.3: Transfer-Encoding wins over Content-Length. */
    TEST_ASSERT(chunked_reader_run(
        "POST /v1/responses HTTP/1.1\r\n"
        "Content-Length: 5\r\n"
        "Transfer-Encoding: chunked\r\n"
        "\r\n"
        "b\r\nhello world\r\n0\r\n\r\n", &hr));
    TEST_ASSERT(hr.body_len == 11 && !strcmp(hr.body, "hello world"));
    http_request_free(&hr);

    /* Garbage size line -> read fails (caller answers 400). */
    TEST_ASSERT(!chunked_reader_run(
        "POST /v1/messages HTTP/1.1\r\n"
        "Transfer-Encoding: chunked\r\n"
        "\r\n"
        "zz\r\nhello\r\n0\r\n\r\n", &hr));

    /* Payload not followed by CRLF -> framing error. */
    TEST_ASSERT(!chunked_reader_run(
        "POST /v1/messages HTTP/1.1\r\n"
        "Transfer-Encoding: chunked\r\n"
        "\r\n"
        "5\r\nhelloX0\r\n\r\n", &hr));

    /* A blank size line must not let strtoul walk into the payload. */
    TEST_ASSERT(!chunked_reader_run(
        "POST /v1/messages HTTP/1.1\r\n"
        "Transfer-Encoding: chunked\r\n"
        "\r\n"
        "\r\n5\r\nhello\r\n0\r\n\r\n", &hr));

    /* A declared chunk larger than the body cap refuses. */
    TEST_ASSERT(!chunked_reader_run(
        "POST /v1/messages HTTP/1.1\r\n"
        "Transfer-Encoding: chunked\r\n"
        "\r\n"
        "4000001\r\n", &hr));

    /* Kill switch pins the pre-v0.6.3 reader: chunked reads as a
     * zero-length body (no Content-Length parsed). */
    setenv("DS4_SERVER_CHUNKED", "0", 1);
    TEST_ASSERT(chunked_reader_run(
        "POST /v1/messages HTTP/1.1\r\n"
        "Transfer-Encoding: chunked\r\n"
        "\r\n"
        "b\r\nhello world\r\n0\r\n\r\n", &hr));
    TEST_ASSERT(hr.body_len == 0);
    http_request_free(&hr);
    unsetenv("DS4_SERVER_CHUNKED");
}

/* Contract record: non-null Responses previous_response_id / conversation
 * reject at parse time with a replay-full-input message (DS4 serves a
 * stateless Responses subset; a durable response store is out of scope for
 * this arc).  Only the reject branch runs here -- it fires before the
 * parser needs an engine or server. */
static void test_responses_durable_references_rejected_at_parse(void) {
    request r;
    char err[200] = {0};
    TEST_ASSERT(!parse_responses_request(NULL, NULL,
        "{\"previous_response_id\":\"resp_123\"}", 128, 4096, &r, err, sizeof(err)));
    TEST_ASSERT(strstr(err, "not supported") != NULL);
    TEST_ASSERT(strstr(err, "previous_response_id") != NULL);

    err[0] = '\0';
    TEST_ASSERT(!parse_responses_request(NULL, NULL,
        "{\"conversation\":\"conv_1\"}", 128, 4096, &r, err, sizeof(err)));
    TEST_ASSERT(strstr(err, "not supported") != NULL);
    TEST_ASSERT(strstr(err, "conversation") != NULL);
}

/* Vision-Exp text-only serving: media content blocks are refused with a
 * named reason on the chat and Anthropic content parsers (the Responses
 * converter already failed closed), never flattened to their text parts.
 * Text-only content arrays still parse. */
static void test_media_content_blocks_rejected(void) {
    chat_msgs msgs = {0};
    char err[200] = {0};
    const char *p;

    p = "[{\"role\":\"user\",\"content\":[{\"type\":\"text\",\"text\":\"hi\"},"
        "{\"type\":\"image_url\",\"image_url\":{\"url\":\"data:image/png;base64,AA==\"}}]}]";
    g_content_reject[0] = 0;
    TEST_ASSERT(!parse_messages(&p, &msgs));
    content_reject_take(err, sizeof(err));
    TEST_ASSERT(strstr(err, "image_url") != NULL);
    TEST_ASSERT(strstr(err, "not implemented") != NULL);
    TEST_ASSERT(g_content_reject[0] == 0);          /* consumed once */
    chat_msgs_free(&msgs);

    /* Anthropic image block inside a user message. */
    err[0] = '\0';
    p = "[{\"role\":\"user\",\"content\":[{\"type\":\"text\",\"text\":\"hi\"},"
        "{\"type\":\"image\",\"source\":{\"type\":\"base64\",\"media_type\":\"image/png\",\"data\":\"AA==\"}}]}]";
    TEST_ASSERT(!parse_anthropic_messages(&p, &msgs));
    content_reject_take(err, sizeof(err));
    TEST_ASSERT(strstr(err, "\"image\"") != NULL);
    chat_msgs_free(&msgs);

    /* Positive control: typed text blocks (type before text, and after). */
    err[0] = '\0';
    p = "[{\"role\":\"user\",\"content\":[{\"type\":\"text\",\"text\":\"a\"},"
        "{\"text\":\"b\",\"type\":\"text\"}]}]";
    TEST_ASSERT(parse_messages(&p, &msgs));
    TEST_ASSERT(msgs.len == 1 && msgs.v[0].content && !strcmp(msgs.v[0].content, "ab"));
    content_reject_take(err, sizeof(err));
    TEST_ASSERT(err[0] == '\0');
    chat_msgs_free(&msgs);
}

/* Inc 2b: endpoint-native error envelopes (surface-matrix defect 3 FIXED).
 * OpenAI keeps the shared envelope (it is native there); Anthropic buffered
 * errors carry the documented {"type":"error",...} envelope with a
 * status-mapped type; Responses stream errors are protocol events with a
 * spliced sequence_number that continues a live machine's counter. */
static void test_error_envelopes_native_shapes(void) {
    int sv[2];
    char *out;

    /* OpenAI: unchanged shared envelope through the wrapper. */
    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
    if (sv[0] < 0 || sv[1] < 0) return;
    TEST_ASSERT(wire_http_error(sv[0], false, DS4_WIRE_OPENAI_CHAT, 503,
                                "server is shutting down"));
    shutdown(sv[0], SHUT_WR);
    out = read_socket_text(sv[1]);
    TEST_ASSERT(strstr(out, "HTTP/1.1 503") != NULL);
    TEST_ASSERT(strstr(out, "\"error\":{\"message\":") != NULL);
    TEST_ASSERT(strstr(out, "\"type\":\"server_error\"") != NULL);   /* Inc 2c: 5xx is the server's fault */
    free(out);
    close(sv[0]);
    close(sv[1]);

    /* Anthropic buffered: native envelope, full status->type map. */
    static const struct { int code; const char *type; } amap[] = {
        { 400, "invalid_request_error" }, { 404, "not_found_error" },
        { 409, "invalid_request_error" }, { 429, "rate_limit_error" },
        { 500, "api_error" },             { 503, "overloaded_error" },
    };
    for (size_t i = 0; i < sizeof(amap) / sizeof(amap[0]); i++) {
        char head[96], expect[96];
        TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
        TEST_ASSERT(wire_http_error(sv[0], false, DS4_WIRE_ANTHROPIC,
                                    amap[i].code, "boom"));
        shutdown(sv[0], SHUT_WR);
        out = read_socket_text(sv[1]);
        snprintf(head, sizeof(head), "HTTP/1.1 %d", amap[i].code);
        snprintf(expect, sizeof(expect),
                 "{\"type\":\"error\",\"error\":{\"type\":\"%s\",\"message\":\"boom\"}}",
                 amap[i].type);
        TEST_ASSERT(strstr(out, head) != NULL);
        TEST_ASSERT(strstr(out, expect) != NULL);
        TEST_ASSERT(strstr(out, "\"error\":{\"message\":") == NULL);   /* no OpenAI shape */
        free(out);
        close(sv[0]);
        close(sv[1]);
    }

    /* Anthropic stream: the native event (unchanged bytes, still through
     * sse_error_event's branch). */
    request a;
    request_init(&a, REQ_CHAT, 128);
    a.api = API_ANTHROPIC;
    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
    if (sv[0] < 0 || sv[1] < 0) { request_free(&a); return; }
    TEST_ASSERT(sse_error_event(sv[0], &a, "boom"));
    shutdown(sv[0], SHUT_WR);
    out = read_socket_text(sv[1]);
    TEST_ASSERT(strstr(out, "event: error") != NULL);
    TEST_ASSERT(strstr(out, "{\"type\":\"error\",\"error\":{\"type\":\"api_error\"") != NULL);
    free(out);
    request_free(&a);
    close(sv[0]);
    close(sv[1]);

    /* Inc 2b: negative budgets reject at parse with the client's own field
     * name; the specific message survives the shared bad: epilogue.  NULL
     * engine/server is safe -- the check fires before anything needs them
     * (the durable-reference contract test set the precedent). */
    {
        char err[160];
        request pr;
        err[0] = '\0';
        TEST_ASSERT(!parse_chat_request(NULL, NULL, "{\"max_tokens\":-1}",
                                        128, 4096, &pr, err, sizeof(err)));
        TEST_ASSERT(strstr(err, "max_tokens must be >= 0") != NULL);
        err[0] = '\0';
        TEST_ASSERT(!parse_chat_request(NULL, NULL,
                                        "{\"max_completion_tokens\":-2}",
                                        128, 4096, &pr, err, sizeof(err)));
        TEST_ASSERT(strstr(err, "max_completion_tokens must be >= 0") != NULL);
        err[0] = '\0';
        TEST_ASSERT(!parse_anthropic_request(NULL, NULL, "{\"max_tokens\":-1}",
                                             128, 4096, &pr, err, sizeof(err)));
        TEST_ASSERT(strstr(err, "max_tokens must be >= 0") != NULL);
        err[0] = '\0';
        TEST_ASSERT(!parse_responses_request(NULL, NULL,
                                             "{\"max_output_tokens\":-3}",
                                             128, 4096, &pr, err, sizeof(err)));
        TEST_ASSERT(strstr(err, "max_output_tokens must be >= 0") != NULL);
        err[0] = '\0';
        TEST_ASSERT(!parse_completion_request(NULL, "{\"max_tokens\":-1}",
                                              128, 4096, &pr, err, sizeof(err)));
        TEST_ASSERT(strstr(err, "max_tokens must be >= 0") != NULL);
    }

    /* v0.6.3: response_format contract (ds4-on-spark#10).  Plain, null,
     * and typeless formats stay accepted -- proved by the parse failing
     * LATER on the missing required field, so the format itself was not
     * the objection.  Schema-constrained modes refuse with a typed
     * message naming the mode, on every surface and in every spelling
     * (nested schema first, string shorthand, output_config nesting). */
    {
        char err[160];
        request pr;

        err[0] = '\0';
        TEST_ASSERT(!parse_chat_request(NULL, NULL,
            "{\"response_format\":{\"type\":\"text\"}}",
            128, 4096, &pr, err, sizeof(err)));
        TEST_ASSERT(strstr(err, "missing messages") != NULL);
        err[0] = '\0';
        TEST_ASSERT(!parse_chat_request(NULL, NULL,
            "{\"response_format\":null}",
            128, 4096, &pr, err, sizeof(err)));
        TEST_ASSERT(strstr(err, "missing messages") != NULL);
        err[0] = '\0';
        TEST_ASSERT(!parse_chat_request(NULL, NULL,
            "{\"response_format\":{}}",
            128, 4096, &pr, err, sizeof(err)));
        TEST_ASSERT(strstr(err, "missing messages") != NULL);

        err[0] = '\0';
        TEST_ASSERT(!parse_chat_request(NULL, NULL,
            "{\"response_format\":{\"type\":\"json_object\"}}",
            128, 4096, &pr, err, sizeof(err)));
        TEST_ASSERT(strstr(err, "response_format type 'json_object' is not implemented") != NULL);
        err[0] = '\0';
        TEST_ASSERT(!parse_chat_request(NULL, NULL,
            "{\"response_format\":{\"json_schema\":{\"schema\":{\"type\":\"object\"}},"
            "\"type\":\"json_schema\"}}",
            128, 4096, &pr, err, sizeof(err)));
        TEST_ASSERT(strstr(err, "'json_schema' is not implemented") != NULL);
        err[0] = '\0';
        TEST_ASSERT(!parse_chat_request(NULL, NULL,
            "{\"response_format\":{\"type\":\"xml\"}}",
            128, 4096, &pr, err, sizeof(err)));
        TEST_ASSERT(strstr(err, "response_format type 'xml' is not supported") != NULL);
        err[0] = '\0';
        TEST_ASSERT(!parse_chat_request(NULL, NULL,
            "{\"response_format\":\"json_object\"}",
            128, 4096, &pr, err, sizeof(err)));
        TEST_ASSERT(strstr(err, "'json_object' is not implemented") != NULL);

        err[0] = '\0';
        TEST_ASSERT(!parse_completion_request(NULL,
            "{\"response_format\":{\"type\":\"text\"}}",
            128, 4096, &pr, err, sizeof(err)));
        TEST_ASSERT(strstr(err, "missing prompt") != NULL);
        err[0] = '\0';
        TEST_ASSERT(!parse_completion_request(NULL,
            "{\"response_format\":{\"type\":\"json_object\"}}",
            128, 4096, &pr, err, sizeof(err)));
        TEST_ASSERT(strstr(err, "response_format type 'json_object' is not implemented") != NULL);

        err[0] = '\0';
        TEST_ASSERT(!parse_responses_request(NULL, NULL,
            "{\"text\":{\"format\":{\"type\":\"text\"},\"verbosity\":\"low\"}}",
            128, 4096, &pr, err, sizeof(err)));
        TEST_ASSERT(strstr(err, "missing input") != NULL);
        err[0] = '\0';
        TEST_ASSERT(!parse_responses_request(NULL, NULL,
            "{\"text\":{\"format\":{\"type\":\"json_schema\",\"name\":\"x\"}}}",
            128, 4096, &pr, err, sizeof(err)));
        TEST_ASSERT(strstr(err, "text.format type 'json_schema' is not implemented") != NULL);

        err[0] = '\0';
        TEST_ASSERT(!parse_anthropic_request(NULL, NULL,
            "{\"output_format\":null}",
            128, 4096, &pr, err, sizeof(err)));
        TEST_ASSERT(strstr(err, "missing messages") != NULL);
        err[0] = '\0';
        TEST_ASSERT(!parse_anthropic_request(NULL, NULL,
            "{\"output_format\":{\"type\":\"json_schema\",\"schema\":{}}}",
            128, 4096, &pr, err, sizeof(err)));
        TEST_ASSERT(strstr(err, "output_format type 'json_schema' is not implemented") != NULL);
        err[0] = '\0';
        TEST_ASSERT(!parse_anthropic_request(NULL, NULL,
            "{\"output_config\":{\"effort\":\"high\",\"format\":{\"type\":\"json_object\"}}}",
            128, 4096, &pr, err, sizeof(err)));
        TEST_ASSERT(strstr(err, "output_config.format type 'json_object' is not implemented") != NULL);
    }

    /* Responses stream, no machine yet: protocol event, sequence 0. */
    request rr;
    request_init(&rr, REQ_CHAT, 128);
    rr.api = API_RESPONSES;
    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
    if (sv[0] < 0 || sv[1] < 0) { request_free(&rr); return; }
    TEST_ASSERT(wire_stream_error(sv[0], &rr, NULL, "boom"));
    shutdown(sv[0], SHUT_WR);
    out = read_socket_text(sv[1]);
    TEST_ASSERT(strstr(out, "data: {\"type\":\"error\",\"sequence_number\":0,"
                            "\"code\":\"server_error\",\"message\":\"boom\","
                            "\"param\":null}") != NULL);
    TEST_ASSERT(strstr(out, "event: error") == NULL);   /* data-only, like every Responses event */
    free(out);
    close(sv[0]);
    close(sv[1]);

    /* Responses stream, live machine: the counter continues and advances. */
    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
    ds4_wire_session ws;
    wire_init(&ws, DS4_WIRE_RESPONSES, "resp_err");
    ws.protocol_started = true;
    ws.state.responses.sequence = 7;
    TEST_ASSERT(wire_stream_error(sv[0], &rr, &ws, "late failure"));
    TEST_ASSERT(ws.terminal);
    TEST_ASSERT(ws.state.responses.sequence == 8);
    shutdown(sv[0], SHUT_WR);
    out = read_socket_text(sv[1]);
    TEST_ASSERT(strstr(out, "\"sequence_number\":7,\"code\":\"server_error\"") != NULL);
    free(out);
    wire_free(&ws);   /* zeroed machine bufs -> the responses free path is a no-op */
    request_free(&rr);
    close(sv[0]);
    close(sv[1]);
}

/* Inc 2c: a matched stop sequence is "stop_sequence" + the matched text on
 * the Anthropic surface (buffered + stream message_delta); EOS keeps
 * end_turn with a null stop_sequence; length still beats a match (the
 * budget cut is the reason).  OpenAI/Responses bytes carry no stop text. */
static void test_anthropic_stop_sequence_native_shape(void) {
    int sv[2];
    char *out;
    request r;
    tool_calls empty = {0};
    request_init(&r, REQ_CHAT, 128);
    r.api = API_ANTHROPIC; r.temperature = 0.0f; r.think_mode = DS4_THINK_NONE;

    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
    if (sv[0] < 0 || sv[1] < 0) { request_free(&r); return; }
    TEST_ASSERT(anthropic_final_response(sv[0], false, &r, "msg_stop", "before",
                                         NULL, &empty, "stop", "STOPWORD", 4, 2));
    shutdown(sv[0], SHUT_WR);
    out = read_socket_text(sv[1]);
    TEST_ASSERT(strstr(out, "\"stop_reason\":\"stop_sequence\"") != NULL);
    TEST_ASSERT(strstr(out, "\"stop_sequence\":\"STOPWORD\"") != NULL);
    free(out);
    close(sv[0]); close(sv[1]);

    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
    TEST_ASSERT(anthropic_final_response(sv[0], false, &r, "msg_eos", "hi",
                                         NULL, &empty, "stop", NULL, 4, 2));
    shutdown(sv[0], SHUT_WR);
    out = read_socket_text(sv[1]);
    TEST_ASSERT(strstr(out, "\"stop_reason\":\"end_turn\"") != NULL);
    TEST_ASSERT(strstr(out, "\"stop_sequence\":null") != NULL);
    free(out);
    close(sv[0]); close(sv[1]);

    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
    TEST_ASSERT(anthropic_sse_stop_live(sv[0], "stop", "\n\nHuman:", 7));
    shutdown(sv[0], SHUT_WR);
    out = read_socket_text(sv[1]);
    TEST_ASSERT(strstr(out, "\"stop_reason\":\"stop_sequence\"") != NULL);
    TEST_ASSERT(strstr(out, "\"stop_sequence\":\"\\n\\nHuman:\"") != NULL);
    free(out);
    close(sv[0]); close(sv[1]);

    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
    TEST_ASSERT(anthropic_sse_stop_live(sv[0], "length", "X", 7));
    shutdown(sv[0], SHUT_WR);
    out = read_socket_text(sv[1]);
    TEST_ASSERT(strstr(out, "\"stop_reason\":\"max_tokens\"") != NULL);
    TEST_ASSERT(strstr(out, "\"stop_sequence\":null") != NULL);
    free(out);
    close(sv[0]); close(sv[1]);
    request_free(&r);
}

/* v0.5.6 Inc 2e: admission bounds shed with endpoint-native 429/503 plus
 * Retry-After; the queue bounds enforce atomically at enqueue and the age
 * bound sheds at the pull sites. */
static void test_admission_bounds_shed(void) {
    int sv[2];
    char *out;

    /* Retry-After + native envelope, both families, both shed codes. */
    static const struct {
        ds4_wire_surface surf; int code; const char *reason; const char *type;
    } smap[] = {
        { DS4_WIRE_ANTHROPIC,   429, "429 Too Many Requests", "\"type\":\"rate_limit_error\"" },
        { DS4_WIRE_ANTHROPIC,   503, "503 Service Unavailable", "\"type\":\"overloaded_error\"" },
        { DS4_WIRE_OPENAI_CHAT, 429, "429 Too Many Requests", "\"type\":\"rate_limit_error\"" },
        { DS4_WIRE_OPENAI_CHAT, 503, "503 Service Unavailable", "\"type\":\"server_error\"" },
    };
    for (size_t i = 0; i < sizeof(smap) / sizeof(smap[0]); i++) {
        char head[64];
        TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, sv) == 0);
        TEST_ASSERT(wire_http_error_retry(sv[0], false, smap[i].surf,
                                          smap[i].code, 7, "busy"));
        shutdown(sv[0], SHUT_WR);
        out = read_socket_text(sv[1]);
        snprintf(head, sizeof(head), "HTTP/1.1 %s", smap[i].reason);
        TEST_ASSERT(strstr(out, head) != NULL);
        TEST_ASSERT(strstr(out, "Retry-After: 7\r\n") != NULL);
        TEST_ASSERT(strstr(out, smap[i].type) != NULL);
        if (smap[i].surf == DS4_WIRE_ANTHROPIC) {
            TEST_ASSERT(strstr(out, "{\"type\":\"error\",\"error\":{") != NULL);
            TEST_ASSERT(strstr(out, "\"error\":{\"message\":") == NULL);
        } else {
            TEST_ASSERT(strstr(out, "\"error\":{\"message\":") != NULL);
        }
        free(out);
        close(sv[0]);
        close(sv[1]);
    }

    /* enqueue: the authoritative queue bounds, atomic with the queue state.
     * Minimal server -- only what enqueue/dequeue touch. */
    server s;
    memset(&s, 0, sizeof(s));
    pthread_mutex_init(&s.mu, NULL);
    pthread_cond_init(&s.cv, NULL);
    s.max_queue = 1;
    s.max_queue_bytes = 100;

    job j1, j2, j3;
    memset(&j1, 0, sizeof(j1)); memset(&j2, 0, sizeof(j2)); memset(&j3, 0, sizeof(j3));
    request_init(&j1.req, REQ_CHAT, 128);
    request_init(&j2.req, REQ_CHAT, 128);
    request_init(&j3.req, REQ_CHAT, 128);
    j1.body_bytes = 40; j2.body_bytes = 40; j3.body_bytes = 70;

    TEST_ASSERT(enqueue(&s, &j1) == ENQ_OK);
    TEST_ASSERT(s.queued == 1 && s.inflight_body_bytes == 40);
    TEST_ASSERT(enqueue(&s, &j2) == ENQ_SHED_QUEUE_DEPTH);    /* depth checks first */
    s.max_queue = 8;
    TEST_ASSERT(enqueue(&s, &j3) == ENQ_SHED_QUEUE_BYTES);    /* 40 + 70 > 100 */
    TEST_ASSERT(enqueue(&s, &j2) == ENQ_OK);                  /* 40 + 40 fits */
    TEST_ASSERT(s.queued == 2 && s.inflight_body_bytes == 80);
    s.stopping = true;
    TEST_ASSERT(enqueue(&s, &j3) == ENQ_STOPPING);
    s.stopping = false;

    /* dequeue: an over-age head is shed 503+Retry-After with outcome SHED,
     * and the pull returns the next (fresh) job.  Both jobs need live peer
     * sockets so the zombie probe says alive (a dead peer must stay the Inc
     * 2c CANCELED reap, also asserted). */
    int aged_sv[2], fresh_sv[2];
    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, aged_sv) == 0);
    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, fresh_sv) == 0);
    s.max_queue_age = 1.0;
    /* j1 is the queue head from above; age it and give it a live socket. */
    j1.fd = aged_sv[0];
    j1.t_arrive = now_sec() - 5.0;
    j2.fd = fresh_sv[0];
    j2.t_arrive = now_sec();
    job *got = dequeue(&s);
    TEST_ASSERT(got == &j2);
    TEST_ASSERT(j1.done && j1.outcome == JOB_OUT_SHED);
    TEST_ASSERT(s.queued == 0);
    shutdown(aged_sv[0], SHUT_WR);
    out = read_socket_text(aged_sv[1]);
    TEST_ASSERT(strstr(out, "HTTP/1.1 503 Service Unavailable") != NULL);
    TEST_ASSERT(strstr(out, "Retry-After: 30\r\n") != NULL);
    TEST_ASSERT(strstr(out, "over the 1s limit") != NULL);
    free(out);

    /* Dead peer + aged: the zombie reap wins -- CANCELED, nothing written.
     * Byte bound off here: nothing settles in a unit, so the earlier
     * charges never leave inflight_body_bytes. */
    s.max_queue_bytes = 0;
    int dead_sv[2];
    TEST_ASSERT(socketpair(AF_UNIX, SOCK_STREAM, 0, dead_sv) == 0);
    close(dead_sv[1]);                          /* peer gone: FIN pending */
    memset(&j3, 0, sizeof(j3));
    request_init(&j3.req, REQ_CHAT, 128);
    j3.fd = dead_sv[0];
    j3.t_arrive = now_sec() - 5.0;
    TEST_ASSERT(enqueue(&s, &j3) == ENQ_OK);
    j2.next = NULL;                             /* re-queue the fresh job behind it */
    j2.t_arrive = now_sec();
    TEST_ASSERT(enqueue(&s, &j2) == ENQ_OK);
    got = dequeue(&s);
    TEST_ASSERT(got == &j2);
    TEST_ASSERT(j3.done && j3.outcome == JOB_OUT_CANCELED);

    close(aged_sv[0]); close(aged_sv[1]);
    close(fresh_sv[0]); close(fresh_sv[1]);
    close(dead_sv[0]);
    request_free(&j1.req); request_free(&j2.req); request_free(&j3.req);
    pthread_mutex_destroy(&s.mu);
    pthread_cond_destroy(&s.cv);
}

/* Inc 2e: job_emit's two slow-reader eviction branches -- the per-job cap
 * and the aggregate backlog cap -- plus the backlog gauge accounting.  The
 * live gate pins DS4_SERVER_CLIENT_SNDBUF to make the aggregate branch
 * reachable through a real socket (loopback sndbuf autotune otherwise
 * absorbs a gate-sized stream); this unit locks the branch logic itself. */
static void test_job_emit_backlog_eviction(void) {
    ds4_metrics *m = ds4_metrics_get();
    const uint64_t cap0 = g_out_agg_cap, min0 = g_out_agg_evict_min;
    const uint64_t shed0 = ds4_metric_read(&m->requests_shed[DS4_SHED_SLOW_READER]);
    const uint64_t back0 = ds4_metric_read(&m->out_backlog_bytes);
    char chunk[512];
    memset(chunk, 'x', sizeof(chunk));

    job j;
    memset(&j, 0, sizeof(j));
    pthread_mutex_init(&j.mu, NULL);
    pthread_cond_init(&j.cv, NULL);

    /* Healthy appends under the caps: the backlog gauge tracks exactly.
     * Caps are set RELATIVE to the current gauge -- the registry is
     * process-global and earlier units may have left stream residue. */
    g_out_agg_cap = back0 + 4096; g_out_agg_evict_min = 1024;
    TEST_ASSERT(job_emit(&j, chunk, sizeof(chunk)));
    TEST_ASSERT(job_emit(&j, chunk, sizeof(chunk)));
    TEST_ASSERT(!j.client_gone && j.out.len == 2 * sizeof(chunk));
    TEST_ASSERT(ds4_metric_read(&m->out_backlog_bytes) - back0 == 2 * sizeof(chunk));

    /* Aggregate cap: an emitter whose own backlog >= evict_min is evicted
     * (nothing appended, gauge unchanged), counted shed{slow_reader}. */
    g_out_agg_cap = back0 + 1200;
    TEST_ASSERT(!job_emit(&j, chunk, sizeof(chunk)));
    TEST_ASSERT(j.client_gone && j.out.len == 2 * sizeof(chunk));
    TEST_ASSERT(ds4_metric_read(&m->out_backlog_bytes) - back0 == 2 * sizeof(chunk));
    TEST_ASSERT(ds4_metric_read(&m->requests_shed[DS4_SHED_SLOW_READER]) - shed0 == 1);

    /* Aggregate over cap but a small own backlog stays: the biggest laggard
     * self-selects; tiny emitters are never evicted for someone else's
     * backlog (worst case stays bounded by clients x evict_min). */
    job j3;
    memset(&j3, 0, sizeof(j3));
    pthread_mutex_init(&j3.mu, NULL);
    pthread_cond_init(&j3.cv, NULL);
    g_out_agg_cap = back0 + 512;               /* agg already over via j */
    g_out_agg_evict_min = 4096;
    TEST_ASSERT(job_emit(&j3, chunk, sizeof(chunk)));
    TEST_ASSERT(!j3.client_gone && j3.out.len == sizeof(chunk));

    /* Per-job cap (W8a), now counted: out.len faked at the cap, so the next
     * append would cross it -- evicted without touching memory. */
    job j2;
    memset(&j2, 0, sizeof(j2));
    pthread_mutex_init(&j2.mu, NULL);
    pthread_cond_init(&j2.cv, NULL);
    g_out_agg_cap = 0;                         /* isolate the per-job branch */
    j2.out.len = DS4_JOB_OUT_CAP;              /* no backing store needed: eviction never reads it */
    TEST_ASSERT(!job_emit(&j2, chunk, sizeof(chunk)));
    TEST_ASSERT(j2.client_gone);
    TEST_ASSERT(ds4_metric_read(&m->requests_shed[DS4_SHED_SLOW_READER]) - shed0 == 2);

    /* Restore the registry and caps (units share the process registry). */
    ds4_metric_add(&m->out_backlog_bytes,
                   (uint64_t)-(uint64_t)(j.out.len + j3.out.len));
    g_out_agg_cap = cap0; g_out_agg_evict_min = min0;
    buf_free(&j.out); buf_free(&j3.out);
    pthread_mutex_destroy(&j.mu); pthread_cond_destroy(&j.cv);
    pthread_mutex_destroy(&j2.mu); pthread_cond_destroy(&j2.cv);
    pthread_mutex_destroy(&j3.mu); pthread_cond_destroy(&j3.cv);
}

/* memgov D0a-1: pure-arithmetic tests for the allocation-census cells
 * (ds4_mem_census.h).  Production (ds4_cuda.cu note sites) drives these
 * exact inlines, so the shapes pinned here are the ledger semantics the
 * census gate reconciles: monotonic requested/committed with clamped
 * frees, arena slack = committed - requested, and the trim-residue rule
 * (release-failure keeps committed live and surfaces as slack). */
static void test_mem_census_cell_arithmetic(void) {
    ds4_mem_cell c = {0, 0, 0, 0, 0, 0};
    uint64_t faults = 0;
    ds4_mem_cell_note_alloc(&c, 100, 100, &faults);
    ds4_mem_cell_note_alloc(&c, 50, 50, &faults);
    TEST_ASSERT(ds4_mem_cell_live(&c) == 150);
    TEST_ASSERT(ds4_mem_cell_slack(&c) == 0);
    TEST_ASSERT(c.alloc_calls == 2 && faults == 0);
    ds4_mem_cell_note_free(&c, 100, 100, &faults);
    TEST_ASSERT(ds4_mem_cell_live(&c) == 50 && faults == 0);
    /* Over-free clamps to outstanding and counts faults (both axes). */
    ds4_mem_cell_note_free(&c, 60, 60, &faults);
    TEST_ASSERT(ds4_mem_cell_live(&c) == 0);
    TEST_ASSERT(c.freed_requested == c.requested);
    TEST_ASSERT(c.freed_committed == c.committed);
    TEST_ASSERT(faults == 2);
    /* Saturation pins at UINT64_MAX and faults instead of wrapping. */
    ds4_mem_cell s = {UINT64_MAX - 10, UINT64_MAX - 10, 0, 0, 0, 0};
    uint64_t sf = 0;
    ds4_mem_cell_note_alloc(&s, 100, 100, &sf);
    TEST_ASSERT(s.requested == UINT64_MAX && s.committed == UINT64_MAX);
    TEST_ASSERT(sf == 2);
    /* NULL cell and NULL faults are inert. */
    ds4_mem_cell_note_alloc(NULL, 1, 1, NULL);
    ds4_mem_cell_note_free(NULL, 1, 1, NULL);
    ds4_mem_cell n = {0, 0, 0, 0, 0, 0};
    ds4_mem_cell_note_alloc(&n, 5, 5, NULL);
    TEST_ASSERT(ds4_mem_cell_live(&n) == 5);
}

static void test_mem_census_arena_slack_shape(void) {
    /* Arena discipline: chunk commits carry committed only, bumps carry
     * requested only; slack = chunk tail nobody asked for. */
    ds4_mem_cell c = {0, 0, 0, 0, 0, 0};
    uint64_t faults = 0;
    const uint64_t chunk = 1792ull << 20;
    ds4_mem_cell_note_alloc(&c, 0, chunk, &faults);      /* chunk commit  */
    ds4_mem_cell_note_alloc(&c, 512u << 20, 0, &faults); /* bump          */
    ds4_mem_cell_note_alloc(&c, 256u << 20, 0, &faults); /* bump          */
    TEST_ASSERT(ds4_mem_cell_live(&c) == chunk);
    TEST_ASSERT(ds4_mem_cell_slack(&c) == chunk - (768ull << 20));
    /* Teardown frees the used total against the chunk commit. */
    ds4_mem_cell_note_free(&c, 768ull << 20, chunk, &faults);
    TEST_ASSERT(ds4_mem_cell_live(&c) == 0);
    TEST_ASSERT(ds4_mem_cell_slack(&c) == 0);
    TEST_ASSERT(faults == 0);
}

static void test_mem_census_trim_residue_shape(void) {
    /* D-1b trim semantics: unmap-ok + release-FAIL frees the ask but not
     * the commitment -- the physical leak stays live and reads as slack,
     * never as an undercharge. */
    ds4_mem_cell c = {0, 0, 0, 0, 0, 0};
    uint64_t faults = 0;
    const uint64_t page = 2048u << 10;
    ds4_mem_cell_note_alloc(&c, page, page, &faults);
    ds4_mem_cell_note_alloc(&c, page, page, &faults);
    ds4_mem_cell_note_free(&c, page, page, &faults);     /* clean trim   */
    ds4_mem_cell_note_free(&c, page, 0, &faults);        /* release-fail */
    TEST_ASSERT(ds4_mem_cell_live(&c) == page);          /* leak visible */
    TEST_ASSERT(ds4_mem_cell_slack(&c) == page);         /* ...as slack  */
    TEST_ASSERT(faults == 0);
    /* Class/domain bounds are compile-time enums; assert the fixed
     * cardinality the metrics render (D0a-3) will bake in. */
    TEST_ASSERT(DS4_MEMC_ENGINE_OTHER == 0);
    TEST_ASSERT(DS4_MEMC__COUNT == 17);
    TEST_ASSERT(DS4_MEMD__COUNT == 2);
}

/* memgov D0a-4: the exact production parse of DS4_CUDA_TRIM_INJECT. */
static void test_mem_census_trim_inject_parse(void) {
    int site = 0; uint32_t n = 0;
    TEST_ASSERT(ds4_trim_inject_parse("unmap:4", &site, &n) == 1);
    TEST_ASSERT(site == DS4_TRIM_INJECT_UNMAP && n == 4);
    TEST_ASSERT(ds4_trim_inject_parse("release:1", &site, &n) == 1);
    TEST_ASSERT(site == DS4_TRIM_INJECT_RELEASE && n == 1);
    TEST_ASSERT(ds4_trim_inject_parse("unmap:4294967295", &site, &n) == 1);
    TEST_ASSERT(n == UINT32_MAX);
    /* Rejections leave the outputs untouched. */
    site = -7; n = 77;
    TEST_ASSERT(ds4_trim_inject_parse(NULL, &site, &n) == 0);
    TEST_ASSERT(ds4_trim_inject_parse("", &site, &n) == 0);
    TEST_ASSERT(ds4_trim_inject_parse("unmap", &site, &n) == 0);
    TEST_ASSERT(ds4_trim_inject_parse("unmap:", &site, &n) == 0);
    TEST_ASSERT(ds4_trim_inject_parse("unmap:0", &site, &n) == 0);  /* off = unset, not zero */
    TEST_ASSERT(ds4_trim_inject_parse("unmap:4x", &site, &n) == 0);
    TEST_ASSERT(ds4_trim_inject_parse("release:4294967296", &site, &n) == 0);
    TEST_ASSERT(ds4_trim_inject_parse("free:3", &site, &n) == 0);
    TEST_ASSERT(site == -7 && n == 77);
}

/* v0.6.2 Inc 3: the trim-victim blend (pure core, ds4.h).  The plan's
 * synthetic 3-bank scenario: an invalid bank beats everything; among
 * valid banks the OLDEST activity wins regardless of history length
 * (the old order's inversion); equal recency falls back to shortest
 * history; the hist kill switch restores shortest-history-only. */
static void test_trim_victim_blend_order(void) {
    const ds4_trim_victim_key inv   = { 0,      0, 900 };  /* invalid, hot  */
    const ds4_trim_victim_key old_deep  = { 1, 700000,  10 };
    const ds4_trim_victim_key hot_small = { 1,   2000, 500 };
    /* Invalid history is always the cheapest victim, both orders. */
    TEST_ASSERT(ds4_trim_victim_cheaper(&inv, &old_deep, 0));
    TEST_ASSERT(ds4_trim_victim_cheaper(&inv, &hot_small, 0));
    TEST_ASSERT(ds4_trim_victim_cheaper(&inv, &hot_small, 1));
    TEST_ASSERT(!ds4_trim_victim_cheaper(&old_deep, &inv, 0));
    /* THE inversion the increment exists for: the ancient deep trunk
     * trims before the recently-hot small bank... */
    TEST_ASSERT(ds4_trim_victim_cheaper(&old_deep, &hot_small, 0));
    TEST_ASSERT(!ds4_trim_victim_cheaper(&hot_small, &old_deep, 0));
    /* ...and the hist kill switch restores the old choice. */
    TEST_ASSERT(ds4_trim_victim_cheaper(&hot_small, &old_deep, 1));
    TEST_ASSERT(!ds4_trim_victim_cheaper(&old_deep, &hot_small, 1));
    /* Equal recency: shortest history is the cheaper re-prefill. */
    const ds4_trim_victim_key tie_a = { 1, 100, 42 };
    const ds4_trim_victim_key tie_b = { 1, 200, 42 };
    TEST_ASSERT(ds4_trim_victim_cheaper(&tie_a, &tie_b, 0));
    TEST_ASSERT(!ds4_trim_victim_cheaper(&tie_b, &tie_a, 0));
    /* Two invalids compare equal (stable sort keeps index order). */
    const ds4_trim_victim_key inv2 = { 0, 5, 5 };
    TEST_ASSERT(!ds4_trim_victim_cheaper(&inv, &inv2, 0));
    TEST_ASSERT(!ds4_trim_victim_cheaper(&inv2, &inv, 0));
}

/* v0.6.2 Inc 0: reconciliation arithmetic (pure core).  The equation
 * under test: observed raw drop = census growth + one-time charges +
 * residual, signed in every term, flagged strictly over the tolerance. */
static void test_mem_reconcile_arithmetic(void) {
    /* A fully explained drop: residual 0, unflagged. */
    ds4_mem_reconcile r = ds4_mem_reconcile_compute(
        /*boot_raw*/ 100, /*now_raw*/ 60,
        /*boot_census*/ 10, /*now_census*/ 50,
        /*onetime*/ 0, /*tol*/ 5);
    TEST_ASSERT(r.observed_delta == 40 && r.census_growth == 40);
    TEST_ASSERT(r.residual == 0 && !r.flagged);
    /* One-time charges explain the census-invisible part. */
    r = ds4_mem_reconcile_compute(100, 50, 10, 40, 20, 5);
    TEST_ASSERT(r.observed_delta == 50 && r.explained == 50);
    TEST_ASSERT(r.residual == 0 && !r.flagged);
    /* Unexplained consumption flags positive... */
    r = ds4_mem_reconcile_compute(100, 40, 10, 40, 0, 5);
    TEST_ASSERT(r.residual == 30 && r.flagged);
    /* ...and over-explanation flags negative (the box returned memory
     * the ledger still charges): |residual| governs. */
    r = ds4_mem_reconcile_compute(100, 90, 10, 60, 0, 5);
    TEST_ASSERT(r.residual == -40 && r.flagged);
    /* Exactly at tol does NOT flag (strictly-over threshold). */
    r = ds4_mem_reconcile_compute(100, 95, 10, 10, 0, 5);
    TEST_ASSERT(r.residual == 5 && !r.flagged);
    /* The raw answer can rise past boot (a neighbor exited) while the
     * census shrank: both terms go negative and still reconcile. */
    r = ds4_mem_reconcile_compute(100, 120, 50, 30, 0, 5);
    TEST_ASSERT(r.observed_delta == -20 && r.census_growth == -20);
    TEST_ASSERT(r.residual == 0 && !r.flagged);
    /* Saturated inputs clamp to INT64_MAX instead of wrapping (a stale
     * counter errs HIGH, the tripwire convention). */
    r = ds4_mem_reconcile_compute(UINT64_MAX, 0, 0, 0, 0, 5);
    TEST_ASSERT(r.observed_delta == INT64_MAX && r.flagged);
    /* Every signed STEP saturates too: max drop beside max census
     * shrink would wrap the naive subtraction; it pins at +INT64_MAX. */
    r = ds4_mem_reconcile_compute(UINT64_MAX, 0, UINT64_MAX, 0, 0, 5);
    TEST_ASSERT(r.explained == -INT64_MAX);
    TEST_ASSERT(r.residual == INT64_MAX && r.flagged);
}

#ifndef DS4_NO_GPU
/* memgov D0a-4: drive the D-1b trim-failure semantics at the REAL driver
 * boundary.  Runs only where the backend supports injection (CUDA) AND
 * demand mapping; Metal skips via the set() return, CPU builds compile it
 * out.  Delta-based census asserts: the test binary's tensor traffic is
 * untagged (ENGINE_OTHER) by contract and earlier suites may have left
 * live cells.  The release-injection case deliberately orphans ONE real
 * page handle -- a bounded, process-scoped leak that stays visible as
 * cell slack forever after, which is exactly the property under test. */
static void test_mem_census_trim_inject_driver(void) {
    if (!ds4_gpu_trim_inject_set(DS4_TRIM_INJECT_OFF, 0)) {
        printf("    (trim-inject driver test skipped: backend has no injection)\n");
        return;
    }
    /* Context warmup through the funnel (balanced: alloc+free nets zero). */
    ds4_gpu_tensor *warm = ds4_gpu_tensor_alloc(4096);
    if (!warm) {
        printf("    (trim-inject driver test skipped: no GPU context)\n");
        return;
    }
    ds4_gpu_tensor_free(warm);
    const uint64_t page = ds4_gpu_vmm_demand_page();
    if (page == 0) {
        printf("    (trim-inject driver test skipped: no VMM demand mapping)\n");
        return;
    }
    ds4_mem_cell c0;
    TEST_ASSERT(ds4_gpu_mem_census_read(DS4_MEMC_ENGINE_OTHER,
                                        DS4_MEMD_UNIFIED_DEVICE, &c0) == 0);
    const uint64_t faults0 = ds4_gpu_mem_census_faults();
    const uint32_t fired0 = ds4_gpu_trim_inject_fired();

    ds4_gpu_tensor *t = ds4_gpu_tensor_reserve(4 * page);
    TEST_ASSERT(t != NULL);
    TEST_ASSERT(ds4_gpu_tensor_ensure(t, 0, 4 * page) == 1);
    ds4_mem_cell c1;
    TEST_ASSERT(ds4_gpu_mem_census_read(DS4_MEMC_ENGINE_OTHER,
                                        DS4_MEMD_UNIFIED_DEVICE, &c1) == 0);
    TEST_ASSERT(ds4_mem_cell_live(&c1) - ds4_mem_cell_live(&c0) == 4 * page);

    /* Injected unmap failure: the page stays owned, resident, and charged
     * -- registry cell byte-identical, trim reports nothing released. */
    TEST_ASSERT(ds4_gpu_trim_inject_set(DS4_TRIM_INJECT_UNMAP, 1) == 1);
    TEST_ASSERT(ds4_gpu_tensor_trim(t, 0, page) == 0);
    TEST_ASSERT(ds4_gpu_trim_inject_fired() - fired0 == 1);
    TEST_ASSERT(ds4_gpu_tensor_resident(t, 0, 4 * page) == 4 * page);
    ds4_mem_cell c2;
    TEST_ASSERT(ds4_gpu_mem_census_read(DS4_MEMC_ENGINE_OTHER,
                                        DS4_MEMD_UNIFIED_DEVICE, &c2) == 0);
    TEST_ASSERT(memcmp(&c2, &c1, sizeof(c2)) == 0);

    /* Injected release failure after a REAL unmap: the ask is freed, the
     * commitment is not -- live unchanged, residue visible as slack,
     * never counted as released. */
    TEST_ASSERT(ds4_gpu_trim_inject_set(DS4_TRIM_INJECT_RELEASE, 1) == 1);
    TEST_ASSERT(ds4_gpu_tensor_trim(t, 0, page) == 0);
    TEST_ASSERT(ds4_gpu_trim_inject_fired() - fired0 == 2);
    TEST_ASSERT(ds4_gpu_tensor_resident(t, 0, 4 * page) == 3 * page);
    ds4_mem_cell c3;
    TEST_ASSERT(ds4_gpu_mem_census_read(DS4_MEMC_ENGINE_OTHER,
                                        DS4_MEMD_UNIFIED_DEVICE, &c3) == 0);
    TEST_ASSERT(ds4_mem_cell_live(&c3) - ds4_mem_cell_live(&c0) == 4 * page);
    TEST_ASSERT(ds4_mem_cell_slack(&c3) - ds4_mem_cell_slack(&c0) == page);

    /* Disarmed: the surviving pages trim clean; the leak alone stays. */
    TEST_ASSERT(ds4_gpu_trim_inject_set(DS4_TRIM_INJECT_OFF, 0) == 1);
    TEST_ASSERT(ds4_gpu_tensor_trim(t, page, 3 * page) == 3 * page);
    ds4_mem_cell c4;
    TEST_ASSERT(ds4_gpu_mem_census_read(DS4_MEMC_ENGINE_OTHER,
                                        DS4_MEMD_UNIFIED_DEVICE, &c4) == 0);
    TEST_ASSERT(ds4_mem_cell_live(&c4) - ds4_mem_cell_live(&c0) == page);
    TEST_ASSERT(ds4_mem_cell_slack(&c4) - ds4_mem_cell_slack(&c0) == page);

    ds4_gpu_tensor_free(t);
    ds4_mem_cell c5;
    TEST_ASSERT(ds4_gpu_mem_census_read(DS4_MEMC_ENGINE_OTHER,
                                        DS4_MEMD_UNIFIED_DEVICE, &c5) == 0);
    TEST_ASSERT(ds4_mem_cell_live(&c5) - ds4_mem_cell_live(&c0) == page);
    TEST_ASSERT(ds4_gpu_trim_inject_fired() - fired0 == 2);
    TEST_ASSERT(ds4_gpu_mem_census_faults() == faults0);
}

/* memgov D4-2: ds4_gpu_tensor_trim_estimate is the exact trim preimage --
 * interior-page arithmetic shared with trim, so a reclaim prepare's quote
 * equals what commit's release can destroy, page for page, and edge pages
 * are excluded on both sides (never quoted, never released). */
static void test_reclaim_trim_estimate_preimage(void) {
    ds4_gpu_tensor *warm = ds4_gpu_tensor_alloc(4096);
    if (!warm) {
        printf("    (trim-estimate test skipped: no GPU context)\n");
        return;
    }
    ds4_gpu_tensor_free(warm);
    const uint64_t page = ds4_gpu_vmm_demand_page();
    if (page == 0) {
        printf("    (trim-estimate test skipped: no VMM demand mapping)\n");
        return;
    }
    ds4_gpu_tensor *t = ds4_gpu_tensor_reserve(4 * page);
    TEST_ASSERT(t != NULL);
    TEST_ASSERT(ds4_gpu_tensor_trim_estimate(t, 0, 4 * page) == 0);   /* unmapped */
    TEST_ASSERT(ds4_gpu_tensor_ensure(t, 0, 4 * page) == 1);
    /* Whole range: every page interior.  A sub-page span holds no whole
     * page; a page-straddling span owns neither neighbor. */
    TEST_ASSERT(ds4_gpu_tensor_trim_estimate(t, 0, 4 * page) == 4 * page);
    TEST_ASSERT(ds4_gpu_tensor_trim_estimate(t, 0, page) == page);
    TEST_ASSERT(ds4_gpu_tensor_trim_estimate(t, 0, page - 1) == 0);
    TEST_ASSERT(ds4_gpu_tensor_trim_estimate(t, page / 2, page) == 0);
    /* estimate == what trim releases, and the preimage empties exactly. */
    const uint64_t est = ds4_gpu_tensor_trim_estimate(t, page, 3 * page);
    TEST_ASSERT(est == 3 * page);
    TEST_ASSERT(ds4_gpu_tensor_trim(t, page, 3 * page) == est);
    TEST_ASSERT(ds4_gpu_tensor_trim_estimate(t, page, 3 * page) == 0);
    TEST_ASSERT(ds4_gpu_tensor_trim_estimate(t, 0, 4 * page) == page);
    /* An injected unmap failure keeps the failed page IN the preimage:
     * the estimate tracks physical mapping, never intent. */
    TEST_ASSERT(ds4_gpu_trim_inject_set(DS4_TRIM_INJECT_UNMAP, 1) == 1);
    TEST_ASSERT(ds4_gpu_tensor_trim(t, 0, page) == 0);
    TEST_ASSERT(ds4_gpu_tensor_trim_estimate(t, 0, page) == page);
    TEST_ASSERT(ds4_gpu_trim_inject_set(DS4_TRIM_INJECT_OFF, 0) == 1);
    TEST_ASSERT(ds4_gpu_tensor_trim(t, 0, page) == page);
    TEST_ASSERT(ds4_gpu_tensor_trim_estimate(t, 0, 4 * page) == 0);
    ds4_gpu_tensor_free(t);
}
#endif /* !DS4_NO_GPU */

/* memgov D4-3: the reclaim status vocabulary is CLOSED -- counters and
 * /metrics render every label by enum walk, so a new status must extend
 * the enum, the string table, and this test together.  Also pins the
 * typed UNSUPPORTED refusal on a contextless call (the no-backend stub
 * and the NULL-argument path share it). */
static void test_reclaim_status_vocabulary(void) {
    TEST_ASSERT(DS4_RECLAIM_STATUS__COUNT == 6);
    const char *want[] = {"ok", "partial", "stale_plan", "busy",
                          "unsupported", "device_error"};
    for (int rs = 0; rs < DS4_RECLAIM_STATUS__COUNT; rs++)
        TEST_ASSERT(strcmp(ds4_reclaim_status_str(rs), want[rs]) == 0);
    TEST_ASSERT(strcmp(ds4_reclaim_status_str(-1), "unknown") == 0);
    TEST_ASSERT(strcmp(ds4_reclaim_status_str(DS4_RECLAIM_STATUS__COUNT),
                       "unknown") == 0);
    ds4_reclaim_plan p;
    TEST_ASSERT(ds4_batch_ctx_reclaim_prepare(NULL, NULL, 0, 1, &p) ==
                DS4_RECLAIM_UNSUPPORTED);
    TEST_ASSERT(p.n == 0 && p.est_bytes == 0);
    ds4_reclaim_result r;
    TEST_ASSERT(ds4_batch_ctx_reclaim_commit(NULL, &p, &r) ==
                DS4_RECLAIM_UNSUPPORTED);
    TEST_ASSERT(r.status == DS4_RECLAIM_UNSUPPORTED && r.bytes_released == 0);
    TEST_ASSERT(ds4_batch_ctx_reclaim_prepare(NULL, NULL, 0, 1, NULL) ==
                DS4_RECLAIM_UNSUPPORTED);
}

/* memgov D4-2: the serial reclaim ranking -- cheapest warm value first
 * (no-value banks by index, superseded records by LRU, shallow records by
 * LRU) with retention protection as a HARD exclusion at every tier.  The
 * depth tier (warm_pin_min) needs a live batch ctx for committed lengths
 * and is exercised by the serial_reclaim gate instead; pin 0 keeps it out
 * here. */
static void test_serial_reclaim_rank_order(void) {
    server s = {0};
    pthread_mutex_init(&s.tool_mu, NULL);
    s.batch_ctx_max_seq = 6;
    s.warm_pin_min = 0;
    s.creg.grace_s = 60;   /* publish => in-grace => protected */
    s.warm = calloc(6, sizeof(*s.warm));   /* plain calloc: the test link has no xcalloc */
    TEST_ASSERT(s.warm != NULL);
    struct { int b; const char *txt; uint64_t use; } recs[] = {
        {0, "AAAA", 10},      /* superseded by bank 1's longer record */
        {1, "AAAABBB", 20},   /* superseder: plain shallow */
        {3, "CCCC", 5},       /* plain shallow, LRU-oldest */
        {4, "DDDD", 30},      /* valid but protected: excluded */
    };
    for (size_t i = 0; i < sizeof(recs) / sizeof(recs[0]); i++) {
        s.warm[recs[i].b].text = xstrdup(recs[i].txt);
        s.warm[recs[i].b].len = strlen(recs[i].txt);
        s.warm[recs[i].b].last_use = recs[i].use;
        s.warm[recs[i].b].valid = true;
    }
    /* banks 2 and 5 hold no record; 4 and 5 carry a live in-grace tool
     * continuation (the Inc 6c protection the ranking must honor). */
    for (int b = 4; b <= 5; b++) {
        tool_calls calls = {0};
        tool_call tc = {0};
        char id[32];
        snprintf(id, sizeof(id), "toolu_rk%d", b);
        tc.id = xstrdup(id);
        tool_calls_push(&calls, tc);
        cont_registry_publish_bank(&s, API_ANTHROPIC, &calls, b, 3, 50);
        tool_calls_free(&calls);
    }
    uint32_t out[DS4_COALESCE_HARD_MAX];
    const uint32_t n = serial_reclaim_rank(&s, out);
    TEST_ASSERT(n == 4);
    TEST_ASSERT(out[0] == 2);   /* tier 0: no retained value */
    TEST_ASSERT(out[1] == 0);   /* tier 1: superseded */
    TEST_ASSERT(out[2] == 3);   /* tier 2: shallow LRU-oldest first */
    TEST_ASSERT(out[3] == 1);
    /* Warm records off: every unprotected bank ranks no-value by index. */
    void *wsave = s.warm;
    s.warm = NULL;
    const uint32_t n2 = serial_reclaim_rank(&s, out);
    TEST_ASSERT(n2 == 4);
    TEST_ASSERT(out[0] == 0 && out[1] == 1 && out[2] == 2 && out[3] == 3);
    s.warm = wsave;
    cont_registry_free(&s);
    for (int b = 0; b < 6; b++) free(s.warm[b].text);
    free(s.warm);
}

/* memgov D0a-3: publication preconditions on EVERY backend -- positional
 * name tables fully populated (a hole would misattribute a class in every
 * porcelain), snapshot supported-flag consistent with the backend, and
 * the render-time observation sampler always returning clamped enums the
 * name tables can index. */
static void test_mem_census_publication_shape(void) {
    for (int c = 0; c < DS4_MEMC__COUNT; c++)
        TEST_ASSERT(mem_class_names[c] && mem_class_names[c][0]);
    for (int d = 0; d < DS4_MEMD__COUNT; d++)
        TEST_ASSERT(mem_domain_names[d] && mem_domain_names[d][0]);
    mem_census_image img;
    mem_census_snapshot(&img);
    int backend = 0;
#ifndef DS4_NO_GPU
    ds4_mem_cell probe;
    backend = ds4_gpu_mem_census_read(0, 0, &probe) == 0;
#endif
    TEST_ASSERT(img.supported == backend);
    ds4_mem_observation o;
    mem_obs_sample(&o);
    TEST_ASSERT(o.status >= DS4_MEMOBS_OK && o.status <= DS4_MEMOBS_QUERY_ERROR);
    TEST_ASSERT(o.source >= DS4_MEMOBS_SRC_NONE &&
                o.source <= DS4_MEMOBS_SRC_MEMINFO_AVAILABLE);
}

/* memgov D5-1: the render capture -- one coherent moment for every
 * porcelain.  A capture must never hand a renderer a torn stamp (odd =
 * writer mid-note; even asserts double as a no-wedged-writer tripwire),
 * and on a quiescent process two back-to-back captures must agree on
 * BOTH stamps -- reading never advances an epoch, the property that
 * makes "compare only equal epochs" (plan sec 12) usable at all.  Stubs
 * report permanently even epochs, so every assert holds per-backend. */
static void test_mem_render_capture_coherent(void) {
    mem_census_image img1, img2;
    ds4_gov_ledger lg1, lg2;
    ds4_mem_observation o1, o2;
    mem_render_capture(&img1, &lg1, &o1);
    mem_render_capture(&img2, &lg2, &o2);
    TEST_ASSERT((img1.epoch & 1u) == 0);
    TEST_ASSERT((lg1.epoch & 1u) == 0);
    TEST_ASSERT(img1.supported == img2.supported);
    TEST_ASSERT(img1.epoch == img2.epoch);
    TEST_ASSERT(lg1.epoch == lg2.epoch);
    TEST_ASSERT(o1.status >= DS4_MEMOBS_OK &&
                o1.status <= DS4_MEMOBS_QUERY_ERROR);
    TEST_ASSERT(o2.status == o1.status);
    /* The lineage clock's degenerate contract: no ctx reads as clock 0
     * at any max_seq (the bank_generation API's NULL answer), so board
     * consumers need no live-ctx special case. */
    server s = {0};
    s.batch_ctx_max_seq = 4;
    TEST_ASSERT(bank_lineage_clock(&s) == 0);
}

/* memgov D5-2: residency families -- positional name tables complete,
 * accessor domain contract (out-of-range = nonzero on EVERY backend;
 * Metal reports unsupported so porcelains render absence, and where
 * supported every in-domain cell reads), and the deficit gauge's
 * ADMIT-writes-0 law through a real shadow check. */
static void test_residency_family_shape(void) {
    for (int st = 0; st < DS4_RESUNIT__COUNT; st++)
        TEST_ASSERT(resunit_state_names[st] && resunit_state_names[st][0]);
    for (int sg = 0; sg < DS4_RESSTAGE__COUNT; sg++)
        TEST_ASSERT(resstage_names[sg] && resstage_names[sg][0]);
    TEST_ASSERT(strcmp(resunit_policy_name(DS4_RESIDENCY_EAGER_DEVICE),
                       "eager") == 0);
    TEST_ASSERT(strcmp(resunit_policy_name(DS4_RESIDENCY__COUNT),
                       "unattributed") == 0);
    TEST_ASSERT(strcmp(ds4_model_source_role_name(DS4_MSRC_ROLE_DRAFTER),
                       "drafter") == 0);
    uint64_t rv = 42;
    TEST_ASSERT(ds4_gpu_residency_units_read(-1, 0, &rv) != 0);
    TEST_ASSERT(ds4_gpu_residency_units_read(0, DS4_RESUNIT__COUNT, &rv) != 0);
    TEST_ASSERT(ds4_gpu_residency_units_read(DS4_RESUNIT_POLICY_ROWS, 0, &rv) != 0);
    TEST_ASSERT(ds4_gpu_residency_failures_read(DS4_MSRC_ROLE__COUNT, 0, &rv) != 0);
    TEST_ASSERT(ds4_gpu_residency_failures_read(0, DS4_RESSTAGE__COUNT, &rv) != 0);
    if (ds4_gpu_residency_units_read(0, 0, &rv) == 0) {
        for (int p = 0; p < DS4_RESUNIT_POLICY_ROWS; p++)
            for (int st = 0; st < DS4_RESUNIT__COUNT; st++)
                TEST_ASSERT(ds4_gpu_residency_units_read(p, st, &rv) == 0);
        for (int r = 0; r < DS4_MSRC_ROLE__COUNT; r++)
            for (int sg = 0; sg < DS4_RESSTAGE__COUNT; sg++)
                TEST_ASSERT(ds4_gpu_residency_failures_read(r, sg, &rv) == 0);
    }
    /* memgov D5-3: rejection vocabulary -- tables complete, the gov
     * mapping lands every refusal status on its documented reason, and
     * every mapped value is in-domain (the tick sites index raw). */
    for (int ln = 0; ln < DS4_REJLANE__COUNT; ln++)
        TEST_ASSERT(rejlane_names[ln] && rejlane_names[ln][0]);
    for (int rr = 0; rr < DS4_REJECT__COUNT; rr++)
        TEST_ASSERT(reject_reason_names[rr] && reject_reason_names[rr][0]);
    TEST_ASSERT(ds4_reject_reason_from_gov(DS4_GOV_REFUSE_CLASS) ==
                DS4_REJECT_CLASS_BUDGET);
    TEST_ASSERT(ds4_reject_reason_from_gov(DS4_GOV_REFUSE_LIVE) ==
                DS4_REJECT_LIVE_HEADROOM);
    TEST_ASSERT(ds4_reject_reason_from_gov(DS4_GOV_RETRY_OBS) ==
                DS4_REJECT_OBS_RETRY);
    TEST_ASSERT(ds4_reject_reason_from_gov(DS4_GOV_UNSUPPORTED) ==
                DS4_REJECT_UNSUPPORTED);
    TEST_ASSERT(ds4_reject_reason_from_gov(DS4_GOV_FAULT) == DS4_REJECT_FAULT);
    for (int st = 0; st < DS4_GOV_STATUS__COUNT; st++) {
        const int rr = ds4_reject_reason_from_gov(st);
        TEST_ASSERT(rr >= 0 && rr < DS4_REJECT__COUNT);
    }
    /* Deficit gauge: a well-formed ADMIT-shaped claim writes 0 for its
     * consumer.  Mode off legitimately skips the decision core (and so
     * the gauge) -- assert the law only where the core runs, whatever
     * mode an earlier fixture left behind. */
    if (ds4_gov_mode(DS4_GOVC_STATIC_BATCH) != DS4_GOV_MODE_OFF) {
        ds4_gov_claim cl = {0};
        cl.requester = DS4_GOVC_STATIC_BATCH;
        cl.memc = DS4_MEMC_SESSION_TENSORS;
        cl.domain = DS4_MEMD_UNIFIED_DEVICE;
        cl.proposed_outstanding = 1;
        ds4_metric_set(&ds4_metrics_get()->memgov_deficit[DS4_GOVC_STATIC_BATCH],
                       777);
        ds4_gov_shadow_check("unit-d52", &cl, DS4_GOV_ADMIT);
        TEST_ASSERT(ds4_metric_read(
            &ds4_metrics_get()->memgov_deficit[DS4_GOVC_STATIC_BATCH]) == 0);
    }
}

static void test_mem_obs_legacy_shim(void) {
    /* D0a-2: every typed state must map to the EXACT legacy
     * ds4_gpu_mem_info contract -- rc 0 + outputs only on OK, rc 1 with
     * outputs untouched otherwise (callers pre-zero or fail open). */
    ds4_mem_observation o;
    o.status = DS4_MEMOBS_OK;
    o.source = DS4_MEMOBS_SRC_MEMINFO_AVAILABLE;
    o.free_bytes = 123;
    o.total_bytes = 456;
    uint64_t f = 0, t = 0;
    TEST_ASSERT(ds4_mem_obs_to_legacy(&o, &f, &t) == 0);
    TEST_ASSERT(f == 123 && t == 456);
    f = t = 77;
    o.status = DS4_MEMOBS_QUERY_ERROR;
    TEST_ASSERT(ds4_mem_obs_to_legacy(&o, &f, &t) == 1);
    TEST_ASSERT(f == 77 && t == 77);              /* untouched on failure */
    o.status = DS4_MEMOBS_UNSUPPORTED;
    TEST_ASSERT(ds4_mem_obs_to_legacy(&o, &f, &t) == 1);
    TEST_ASSERT(ds4_mem_obs_to_legacy(NULL, &f, &t) == 1);
    TEST_ASSERT(ds4_mem_obs_to_legacy(&o, NULL, NULL) == 1);
}

/* memgov D0b-1: shadow-governor core (ds4_mem_gov.h).  The evaluator is
 * pure, so these ARE the fake memory provider: ledger images and typed
 * observations are constructed directly and every verdict/fault path is
 * pinned without a GPU.  The fixture mirrors the live boot shape in
 * unit-agnostic numbers (the arithmetic never sees units): settled boot
 * lease, prewarm lease, a bank plan with unfaulted credit debt, and the
 * serial lane holding its opt-in reserve as its own lease reservation. */
static ds4_gov_ledger mem_gov_test_ledger(void) {
    ds4_gov_ledger lg = {0};
    uint64_t faults = 0;
    ds4_gov_lease_publish(&lg, DS4_GOVC_ENGINE_BOOT, 10000, 10000, 0, &faults);
    ds4_gov_lease_publish(&lg, DS4_GOVC_PREWARM, 200, 200, 0, &faults);
    /* bank plan: 1200 promised, 1000 faulted-in -> 200 outstanding debt */
    ds4_gov_lease_publish(&lg, DS4_GOVC_BATCH_BANK_PLAN, 1200, 1000, 0, &faults);
    /* serial lane: empty session holding a 200 reserve */
    ds4_gov_lease_publish(&lg, DS4_GOVC_SERIAL_SESSION, 0, 0, 200, &faults);
    TEST_ASSERT(faults == 0);
    lg.floor_bytes = 600;
    lg.substrate_outstanding = 50;
    lg.epoch = 42;
    return lg;
}

static ds4_mem_observation mem_gov_test_obs(uint64_t free_bytes) {
    ds4_mem_observation o;
    o.status = DS4_MEMOBS_OK;
    o.source = DS4_MEMOBS_SRC_MEMINFO_AVAILABLE;
    o.free_bytes = free_bytes;
    o.total_bytes = 20000;
    return o;
}

static void test_mem_gov_evaluate_verdicts(void) {
    const ds4_gov_ledger lg = mem_gov_test_ledger();
    ds4_gov_claim cl = {0};
    cl.requester = DS4_GOVC_BATCH_BANK_PLAN;
    cl.memc = DS4_MEMC_BATCH_BANK;
    cl.domain = DS4_MEMD_UNIFIED_DEVICE;
    cl.proposed_outstanding = 1500;      /* absolute; unfunded = 500 */
    cl.class_limit = 2000;
    /* required = floor 600 + substrate 50 + serial reserve 200
     *          + others' unfunded 0 + own unfunded 500 = 1350 */
    ds4_mem_observation o = mem_gov_test_obs(1350);
    ds4_gov_quote q = ds4_gov_evaluate(&lg, &o, &cl);
    TEST_ASSERT(q.status == DS4_GOV_ADMIT);
    TEST_ASSERT(q.required == 1350 && q.available == 1350 && q.deficit == 0);
    TEST_ASSERT(q.old_intent == 1200 && q.proposed_intent == 1500);
    TEST_ASSERT(q.other_reservations == 200);
    TEST_ASSERT(q.total_prospective_intent == 10000 + 200 + 1500 + 0 + 0);
    TEST_ASSERT(q.epoch == 42);
    TEST_ASSERT(q.obs_source == DS4_MEMOBS_SRC_MEMINFO_AVAILABLE);
    /* One byte short: live refusal, exact deficit, retryable. */
    o = mem_gov_test_obs(1349);
    q = ds4_gov_evaluate(&lg, &o, &cl);
    TEST_ASSERT(q.status == DS4_GOV_REFUSE_LIVE && q.retryable == 1);
    TEST_ASSERT(q.deficit == 1);
    /* Class cap refuses before the live gate and is not retryable. */
    cl.proposed_outstanding = 2500;
    o = mem_gov_test_obs(UINT64_MAX / 2);
    q = ds4_gov_evaluate(&lg, &o, &cl);
    TEST_ASSERT(q.status == DS4_GOV_REFUSE_CLASS && q.retryable == 0);
    TEST_ASSERT(q.proposed_class_bytes == 2500 && q.class_limit == 2000);
    /* class_limit 0 = uncapped: the same ask rides through to ADMIT. */
    cl.class_limit = 0;
    q = ds4_gov_evaluate(&lg, &o, &cl);
    TEST_ASSERT(q.status == DS4_GOV_ADMIT);
    /* The operation transient is part of required. */
    cl.proposed_outstanding = 1500;
    cl.class_limit = 2000;
    cl.operation_transient = 100;
    o = mem_gov_test_obs(1449);
    q = ds4_gov_evaluate(&lg, &o, &cl);
    TEST_ASSERT(q.status == DS4_GOV_REFUSE_LIVE && q.deficit == 1);
}

/* MT-2 (v0.6.1 memory truth): the serial build-window lease lifecycle as
 * seen by a BANK claim.  ds4_session_alloc_graph publishes (est, 0) before
 * the burst, (est, est) at commit, (0, 0) on failure/release; the
 * evaluator's cross-lane term (others' intent - resident) must charge the
 * whole window and drop to zero at commit -- the committed bytes are
 * already invisible to raw free, so charging them again would double-count
 * (no false admit during the window, no false refuse after commit). */
static void test_mem_gov_serial_window_lease(void) {
    ds4_gov_ledger lg = mem_gov_test_ledger();
    uint64_t faults = 0;
    ds4_gov_claim cl = {0};
    cl.requester = DS4_GOVC_BATCH_BANK_PLAN;
    cl.memc = DS4_MEMC_BATCH_BANK;
    cl.domain = DS4_MEMD_UNIFIED_DEVICE;
    cl.proposed_outstanding = 1500;      /* own unfunded = 500 */
    cl.class_limit = 0;

    /* Baseline (serial lease empty): required = floor 600 + sub 50
     * + serial reserve 200 + own unfunded 500 = 1350. */
    ds4_mem_observation o = mem_gov_test_obs(1350);
    ds4_gov_quote q = ds4_gov_evaluate(&lg, &o, &cl);
    TEST_ASSERT(q.status == DS4_GOV_ADMIT && q.required == 1350);

    /* Window OPEN: serial declares intent 5000, nothing landed.  The
     * bank's quote must charge the full unfunded window. */
    ds4_gov_lease_publish(&lg, DS4_GOVC_SERIAL_SESSION, 5000, 0, 200, &faults);
    q = ds4_gov_evaluate(&lg, &o, &cl);
    TEST_ASSERT(q.status == DS4_GOV_REFUSE_LIVE);
    TEST_ASSERT(q.required == 1350 + 5000 && q.deficit == 5000);

    /* COMMIT: bytes landed (est, est) -- unfunded drops to zero, raw
     * free now carries the graph; required returns to baseline. */
    ds4_gov_lease_publish(&lg, DS4_GOVC_SERIAL_SESSION, 5000, 5000, 200, &faults);
    q = ds4_gov_evaluate(&lg, &o, &cl);
    TEST_ASSERT(q.status == DS4_GOV_ADMIT && q.required == 1350);

    /* RELEASE (graph freed): identical required -- no phantom remains. */
    ds4_gov_lease_publish(&lg, DS4_GOVC_SERIAL_SESSION, 0, 0, 200, &faults);
    q = ds4_gov_evaluate(&lg, &o, &cl);
    TEST_ASSERT(q.status == DS4_GOV_ADMIT && q.required == 1350);
    TEST_ASSERT(faults == 0);
}

static void test_mem_gov_requester_asymmetry(void) {
    /* sec 6.2: the serial requester spends its own reserve; a batch
     * requester must treat it as spoken for.  Identical numbers, the two
     * verdicts differ by exactly the reservation. */
    const ds4_gov_ledger lg = mem_gov_test_ledger();
    ds4_gov_claim cl = {0};
    cl.memc = DS4_MEMC_SESSION_TENSORS;
    cl.domain = DS4_MEMD_UNIFIED_DEVICE;
    cl.proposed_outstanding = 700;
    /* serial: floor 600 + sub 50 + others' reservations 0
     *       + others' unfunded (bank 200) + own 700 = 1550 */
    cl.requester = DS4_GOVC_SERIAL_SESSION;
    ds4_mem_observation o = mem_gov_test_obs(1550);
    ds4_gov_quote qs = ds4_gov_evaluate(&lg, &o, &cl);
    TEST_ASSERT(qs.status == DS4_GOV_ADMIT && qs.required == 1550);
    TEST_ASSERT(qs.other_reservations == 0);
    /* static-batch requester, same ask: + the 200 serial reserve, but
     * NOT the serial lane's unfunded (still 0) twice. */
    cl.requester = DS4_GOVC_STATIC_BATCH;
    ds4_gov_quote qb = ds4_gov_evaluate(&lg, &o, &cl);
    TEST_ASSERT(qb.status == DS4_GOV_REFUSE_LIVE);
    TEST_ASSERT(qb.required == 1550 + 200 && qb.deficit == 200);
    TEST_ASSERT(qb.other_reservations == 200);
}

static void test_mem_gov_absolute_replacement(void) {
    /* Absolute leases: re-evaluating the same claim is idempotent, and a
     * shrink (proposed <= resident) spends nothing -- the page-union
     * projection can be re-published forever without drift (sec 6.2). */
    const ds4_gov_ledger lg = mem_gov_test_ledger();
    ds4_gov_claim cl = {0};
    cl.requester = DS4_GOVC_BATCH_BANK_PLAN;
    cl.memc = DS4_MEMC_BATCH_BANK;
    cl.domain = DS4_MEMD_UNIFIED_DEVICE;
    cl.proposed_outstanding = 1500;
    cl.class_limit = 2000;
    const ds4_mem_observation o = mem_gov_test_obs(1350);
    ds4_gov_quote q1 = ds4_gov_evaluate(&lg, &o, &cl);
    ds4_gov_quote q2 = ds4_gov_evaluate(&lg, &o, &cl);
    TEST_ASSERT(memcmp(&q1, &q2, sizeof(q1)) == 0);
    /* Shrink below resident: unfunded 0, required = 600+50+200 = 850. */
    cl.proposed_outstanding = 900;
    const ds4_mem_observation lo = mem_gov_test_obs(850);
    ds4_gov_quote qs = ds4_gov_evaluate(&lg, &lo, &cl);
    TEST_ASSERT(qs.status == DS4_GOV_ADMIT && qs.required == 850);
    /* Idempotent publish: same absolute state twice, ledger unchanged. */
    ds4_gov_ledger a = mem_gov_test_ledger();
    ds4_gov_ledger b = a;
    uint64_t faults = 0;
    TEST_ASSERT(ds4_gov_lease_publish(&b, DS4_GOVC_BATCH_BANK_PLAN,
                                      1200, 1000, 0, &faults) == 1);
    TEST_ASSERT(memcmp(&a, &b, sizeof(a)) == 0 && faults == 0);
}

static void test_mem_gov_observation_policy(void) {
    /* sec 6.4: UNSUPPORTED is a documented terminal policy (CPU/Metal);
     * QUERY_ERROR is a retryable transient.  Both still return a full
     * record (requester + epoch stamped, no free bytes claimed). */
    const ds4_gov_ledger lg = mem_gov_test_ledger();
    ds4_gov_claim cl = {0};
    cl.requester = DS4_GOVC_BATCH_BANK_PLAN;
    cl.memc = DS4_MEMC_BATCH_BANK;
    cl.domain = DS4_MEMD_UNIFIED_DEVICE;
    cl.proposed_outstanding = 1500;
    ds4_mem_observation o = mem_gov_test_obs(1350);
    o.status = DS4_MEMOBS_UNSUPPORTED;
    ds4_gov_quote q = ds4_gov_evaluate(&lg, &o, &cl);
    TEST_ASSERT(q.status == DS4_GOV_UNSUPPORTED && q.retryable == 0);
    TEST_ASSERT(q.obs_free == 0 && q.available == 0);
    TEST_ASSERT(q.requester == DS4_GOVC_BATCH_BANK_PLAN && q.epoch == 42);
    o.status = DS4_MEMOBS_QUERY_ERROR;
    q = ds4_gov_evaluate(&lg, &o, &cl);
    TEST_ASSERT(q.status == DS4_GOV_RETRY_OBS && q.retryable == 1);
}

static void test_mem_gov_checked_arithmetic(void) {
    const ds4_mem_observation o = mem_gov_test_obs(1350);
    ds4_gov_claim cl = {0};
    cl.requester = DS4_GOVC_BATCH_BANK_PLAN;
    cl.memc = DS4_MEMC_BATCH_BANK;
    cl.domain = DS4_MEMD_UNIFIED_DEVICE;
    cl.proposed_outstanding = 1500;
    /* NULL and out-of-range args fail closed, never decide. */
    TEST_ASSERT(ds4_gov_evaluate(NULL, &o, &cl).status == DS4_GOV_FAULT);
    ds4_gov_ledger lg = mem_gov_test_ledger();
    TEST_ASSERT(ds4_gov_evaluate(&lg, NULL, &cl).status == DS4_GOV_FAULT);
    TEST_ASSERT(ds4_gov_evaluate(&lg, &o, NULL).status == DS4_GOV_FAULT);
    ds4_gov_claim bad = cl;
    bad.requester = DS4_GOVC__COUNT;
    TEST_ASSERT(ds4_gov_evaluate(&lg, &o, &bad).status == DS4_GOV_FAULT);
    bad = cl; bad.memc = DS4_MEMC__COUNT;
    TEST_ASSERT(ds4_gov_evaluate(&lg, &o, &bad).status == DS4_GOV_FAULT);
    bad = cl; bad.domain = -1;
    TEST_ASSERT(ds4_gov_evaluate(&lg, &o, &bad).status == DS4_GOV_FAULT);
    /* Impossible ledger state anywhere in the image fails closed --
     * including on a lease the requester does not own. */
    lg.lease[DS4_GOVC_ENGINE_BOOT].resident =
        lg.lease[DS4_GOVC_ENGINE_BOOT].intent + 1;
    TEST_ASSERT(ds4_gov_evaluate(&lg, &o, &cl).status == DS4_GOV_FAULT);
    /* Saturating sums never wrap into an ADMIT. */
    lg = mem_gov_test_ledger();
    lg.floor_bytes = UINT64_MAX;
    const ds4_mem_observation big = mem_gov_test_obs(UINT64_MAX);
    TEST_ASSERT(ds4_gov_evaluate(&lg, &big, &cl).status == DS4_GOV_FAULT);
    lg = mem_gov_test_ledger();
    lg.lease[DS4_GOVC_ENGINE_BOOT].intent = UINT64_MAX;
    lg.lease[DS4_GOVC_ENGINE_BOOT].resident = UINT64_MAX;
    TEST_ASSERT(ds4_gov_evaluate(&lg, &big, &cl).status == DS4_GOV_FAULT);
    /* Publish guards: out-of-range consumer and resident > intent are
     * refused with a fault, ledger untouched. */
    ds4_gov_ledger before = mem_gov_test_ledger();
    ds4_gov_ledger after = before;
    uint64_t faults = 0;
    TEST_ASSERT(ds4_gov_lease_publish(&after, DS4_GOVC__COUNT,
                                      1, 1, 0, &faults) == 0);
    TEST_ASSERT(ds4_gov_lease_publish(&after, DS4_GOVC_PREWARM,
                                      100, 101, 0, &faults) == 0);
    TEST_ASSERT(ds4_gov_lease_publish(NULL, DS4_GOVC_PREWARM,
                                      1, 1, 0, &faults) == 0);
    TEST_ASSERT(faults == 3);
    TEST_ASSERT(memcmp(&before, &after, sizeof(before)) == 0);
}

static void test_mem_gov_state_machine(void) {
    /* A deterministic admission lifecycle: claim -> admit -> allocation
     * completes (intent becomes resident) -> the SAME absolute claim now
     * costs nothing -> release -> a fresh grow starts from zero.  This is
     * the sec 6.2/6.3 story the shadow wiring will drive with live
     * numbers; the invariants are pinned here first. */
    ds4_gov_ledger lg = mem_gov_test_ledger();
    uint64_t faults = 0;
    ds4_gov_claim cl = {0};
    cl.requester = DS4_GOVC_BATCH_BANK_PLAN;
    cl.memc = DS4_MEMC_BATCH_BANK;
    cl.domain = DS4_MEMD_UNIFIED_DEVICE;
    cl.proposed_outstanding = 1500;
    cl.class_limit = 2000;
    const ds4_mem_observation o = mem_gov_test_obs(1350);
    TEST_ASSERT(ds4_gov_evaluate(&lg, &o, &cl).status == DS4_GOV_ADMIT);
    /* Allocation lands: absolute publish, resident catches intent. */
    TEST_ASSERT(ds4_gov_lease_publish(&lg, DS4_GOVC_BATCH_BANK_PLAN,
                                      1500, 1500, 0, &faults) == 1);
    ds4_gov_quote q = ds4_gov_evaluate(&lg, &o, &cl);
    TEST_ASSERT(q.status == DS4_GOV_ADMIT);
    TEST_ASSERT(q.required == 850);      /* 600+50+200: nothing unfunded */
    /* Release everything; a new grow quotes from a zero base. */
    TEST_ASSERT(ds4_gov_lease_publish(&lg, DS4_GOVC_BATCH_BANK_PLAN,
                                      0, 0, 0, &faults) == 1);
    q = ds4_gov_evaluate(&lg, &o, &cl);
    TEST_ASSERT(q.old_intent == 0 && q.required == 850 + 1500);
    TEST_ASSERT(q.status == DS4_GOV_REFUSE_LIVE && q.deficit == 1000);
    TEST_ASSERT(faults == 0);
}

/* memgov D0b-2: the versioned snapshot protocol (plan sec 6.3), pinned by
 * DETERMINISTIC interleaving enumeration on a fake (epoch, data) pair --
 * the reader must never ACCEPT a copy taken across an in-flight write, at
 * any interleaving point.  (True concurrency cannot be enumerated; the
 * torn-snapshot hunt under live load is the close gate's leg.  What is
 * provable deterministically is the protocol's verdict at every step.) */
static void test_mem_gov_epoch_protocol(void) {
    uint64_t epoch = 0, faults = 0;
    struct { uint64_t a, b; } data = {1, 1};   /* invariant: a == b */
    uint64_t began;

    /* Quiescent read: accept, coherent. */
    began = ds4_gov_epoch_read_begin(&epoch);
    TEST_ASSERT(ds4_gov_epoch_read_verify(&epoch, began) == 1);

    /* Reader lands after write_begin: odd epoch, must not accept. */
    ds4_gov_epoch_write_begin(&epoch, &faults);
    began = ds4_gov_epoch_read_begin(&epoch);
    TEST_ASSERT((began & 1u) != 0);
    TEST_ASSERT(ds4_gov_epoch_read_verify(&epoch, began) == 0);

    /* Reader copies mid-mutation (exactly one field written): the copy is
     * torn by construction and the verdict discards it. */
    data.a = 2;                                 /* half the write         */
    TEST_ASSERT(ds4_gov_epoch_read_verify(&epoch, began) == 0);
    data.b = 2;                                 /* write completes        */
    ds4_gov_epoch_write_end(&epoch, &faults);
    TEST_ASSERT(faults == 0);

    /* Reader straddles a whole transaction (begin before, verify after):
     * epoch advanced by 2, must not accept even though it is even now. */
    began = ds4_gov_epoch_read_begin(&epoch);
    ds4_gov_epoch_write_begin(&epoch, &faults);
    data.a = 3; data.b = 3;
    ds4_gov_epoch_write_end(&epoch, &faults);
    TEST_ASSERT(ds4_gov_epoch_read_verify(&epoch, began) == 0);

    /* Reader entirely after: accept, and the data invariant holds. */
    began = ds4_gov_epoch_read_begin(&epoch);
    TEST_ASSERT(data.a == data.b);
    TEST_ASSERT(ds4_gov_epoch_read_verify(&epoch, began) == 1);
    TEST_ASSERT(faults == 0);

    /* Single-writer tripwire: a nested begin faults (odd seen), the inner
     * end faults (even seen), and parity SELF-HEALS -- after the balanced
     * sequence the epoch is even and readable again. */
    ds4_gov_epoch_write_begin(&epoch, &faults);     /* outer: ok          */
    ds4_gov_epoch_write_begin(&epoch, &faults);     /* inner: FAULT       */
    TEST_ASSERT(faults == 1);
    ds4_gov_epoch_write_end(&epoch, &faults);       /* inner: FAULT (even)*/
    TEST_ASSERT(faults == 2);
    ds4_gov_epoch_write_end(&epoch, &faults);       /* outer: ok (odd)    */
    TEST_ASSERT(faults == 2);
    began = ds4_gov_epoch_read_begin(&epoch);
    TEST_ASSERT((began & 1u) == 0);
    TEST_ASSERT(ds4_gov_epoch_read_verify(&epoch, began) == 1);

    /* Backend hook contract at unit-time quiesce (Metal: permanently even
     * stub; CUDA: the live registry epoch between transactions). */
    const uint64_t live = ds4_gpu_mem_census_epoch_begin();
    TEST_ASSERT((live & 1u) == 0);
    TEST_ASSERT(ds4_gpu_mem_census_epoch_verify(live) == 1);
    TEST_ASSERT(ds4_gpu_mem_census_epoch_verify(live + 1u) == 0);
}

/* memgov D0b-3: the closed comparison-reason set -- every (live, shadow)
 * pair classifies to exactly one reason, no OTHER bucket. */
static void test_mem_gov_compare_classes(void) {
    TEST_ASSERT(ds4_gov_compare(DS4_GOV_ADMIT, DS4_GOV_ADMIT) ==
                DS4_GOV_CMP_AGREE);
    TEST_ASSERT(ds4_gov_compare(DS4_GOV_REFUSE_LIVE, DS4_GOV_REFUSE_LIVE) ==
                DS4_GOV_CMP_AGREE);
    TEST_ASSERT(ds4_gov_compare(DS4_GOV_REFUSE_CLASS, DS4_GOV_REFUSE_CLASS) ==
                DS4_GOV_CMP_AGREE);
    TEST_ASSERT(ds4_gov_compare(DS4_GOV_REFUSE_LIVE, DS4_GOV_ADMIT) ==
                DS4_GOV_CMP_LIVE_STRICTER);
    TEST_ASSERT(ds4_gov_compare(DS4_GOV_REFUSE_CLASS, DS4_GOV_ADMIT) ==
                DS4_GOV_CMP_LIVE_STRICTER);
    TEST_ASSERT(ds4_gov_compare(DS4_GOV_ADMIT, DS4_GOV_REFUSE_LIVE) ==
                DS4_GOV_CMP_SHADOW_STRICTER);
    TEST_ASSERT(ds4_gov_compare(DS4_GOV_ADMIT, DS4_GOV_REFUSE_CLASS) ==
                DS4_GOV_CMP_SHADOW_STRICTER);
    TEST_ASSERT(ds4_gov_compare(DS4_GOV_REFUSE_CLASS, DS4_GOV_REFUSE_LIVE) ==
                DS4_GOV_CMP_VERDICT_CLASS);
    TEST_ASSERT(ds4_gov_compare(DS4_GOV_REFUSE_LIVE, DS4_GOV_REFUSE_CLASS) ==
                DS4_GOV_CMP_VERDICT_CLASS);
    TEST_ASSERT(ds4_gov_compare(DS4_GOV_ADMIT, DS4_GOV_RETRY_OBS) ==
                DS4_GOV_CMP_OBS_POLICY);
    TEST_ASSERT(ds4_gov_compare(DS4_GOV_REFUSE_LIVE, DS4_GOV_UNSUPPORTED) ==
                DS4_GOV_CMP_OBS_POLICY);
    TEST_ASSERT(ds4_gov_compare(DS4_GOV_ADMIT, DS4_GOV_FAULT) ==
                DS4_GOV_CMP_FAULT);
}

/* memgov D0b-3: the live shadow ledger + check plumbing (process-global,
 * so leases are restored to zero at the end).  Backend-portable: on
 * Metal/CPU the observation is UNSUPPORTED and the check must classify
 * OBS_POLICY; on CUDA it quotes for real -- either way EXACTLY ONE
 * decision cell ticks per check. */
static void test_mem_gov_shadow_ledger(void) {
    ds4_metrics *m = ds4_metrics_get();
    ds4_gov_ledger lg;
    ds4_gov_publish_use(DS4_GOVC_PREWARM, 100, 100);
    ds4_gov_publish_reservation(DS4_GOVC_SERIAL_SESSION, 50);
    ds4_gov_publish_use(DS4_GOVC_SERIAL_SESSION, 10, 10);
    ds4_gov_snapshot(&lg);
    TEST_ASSERT((lg.epoch & 1u) == 0);
    TEST_ASSERT(lg.lease[DS4_GOVC_PREWARM].intent == 100);
    TEST_ASSERT(lg.lease[DS4_GOVC_PREWARM].resident == 100);
    /* _use and _reservation are independent absolute setters. */
    TEST_ASSERT(lg.lease[DS4_GOVC_SERIAL_SESSION].intent == 10);
    TEST_ASSERT(lg.lease[DS4_GOVC_SERIAL_SESSION].reservation == 50);
    /* One check ticks exactly one cell. */
    uint64_t cells0 = 0, cells1 = 0;
    for (int c = 0; c < DS4_GOVC__COUNT; c++)
        for (int st = 0; st < DS4_GOV_STATUS__COUNT; st++)
            for (int r = 0; r < DS4_GOV_CMP__COUNT; r++)
                cells0 += ds4_metric_read(&m->memgov_decisions[c][st][r]);
    ds4_gov_claim cl = {0};
    cl.requester = DS4_GOVC_STATIC_BATCH;
    cl.memc = DS4_MEMC_SESSION_TENSORS;
    cl.domain = DS4_MEMD_UNIFIED_DEVICE;
    cl.proposed_outstanding = 4096;
    ds4_gov_shadow_check("unit", &cl, DS4_GOV_ADMIT);
    for (int c = 0; c < DS4_GOVC__COUNT; c++)
        for (int st = 0; st < DS4_GOV_STATUS__COUNT; st++)
            for (int r = 0; r < DS4_GOV_CMP__COUNT; r++)
                cells1 += ds4_metric_read(&m->memgov_decisions[c][st][r]);
    TEST_ASSERT(cells1 == cells0 + 1);
    /* Malformed checks fail closed into the gov fault counter. */
    const uint64_t f0 = ds4_metric_read(&m->memgov_faults);
    ds4_gov_shadow_check("unit", NULL, DS4_GOV_ADMIT);
    ds4_gov_shadow_check("unit", &cl, DS4_GOV_FAULT);   /* not a live verdict */
    TEST_ASSERT(ds4_metric_read(&m->memgov_faults) == f0 + 2);
    /* Restore the shared ledger. */
    ds4_gov_publish_use(DS4_GOVC_PREWARM, 0, 0);
    ds4_gov_publish_use(DS4_GOVC_SERIAL_SESSION, 0, 0);
    ds4_gov_publish_reservation(DS4_GOVC_SERIAL_SESSION, 0);
    ds4_gov_snapshot(&lg);
    TEST_ASSERT(lg.lease[DS4_GOVC_SERIAL_SESSION].intent == 0 &&
                lg.lease[DS4_GOVC_SERIAL_SESSION].reservation == 0);
}

/* memgov D0b-4: the governor porcelain's name tables are positional
 * against closed enums -- a grown enum without its name is a NULL deref
 * at render time; pin the shape here instead. */
static void test_mem_gov_publication_shape(void) {
    for (int c = 0; c < DS4_GOVC__COUNT; c++)
        TEST_ASSERT(gov_consumer_names[c] && gov_consumer_names[c][0]);
    for (int st = 0; st < DS4_GOV_STATUS__COUNT; st++)
        TEST_ASSERT(gov_status_names[st] && gov_status_names[st][0]);
    for (int r = 0; r < DS4_GOV_CMP__COUNT; r++)
        TEST_ASSERT(gov_cmp_names[r] && gov_cmp_names[r][0]);
}

/* memgov D2-1: mode vocabulary + env table + the OFF kill switch.  The
 * table is process state: the test re-invokes the idempotent init under
 * controlled env and restores observe-everywhere before returning. */
static void test_mem_gov_modes(void) {
    /* Pure vocabulary: exact words only -- no prefixes, no case slack. */
    TEST_ASSERT(ds4_gov_mode_parse("off") == DS4_GOV_MODE_OFF);
    TEST_ASSERT(ds4_gov_mode_parse("observe") == DS4_GOV_MODE_OBSERVE);
    TEST_ASSERT(ds4_gov_mode_parse("enforce") == DS4_GOV_MODE_ENFORCE);
    TEST_ASSERT(ds4_gov_mode_parse(NULL) == -1);
    TEST_ASSERT(ds4_gov_mode_parse("") == -1);
    TEST_ASSERT(ds4_gov_mode_parse("obs") == -1);
    TEST_ASSERT(ds4_gov_mode_parse("observed") == -1);
    TEST_ASSERT(ds4_gov_mode_parse("Enforce") == -1);
    TEST_ASSERT(ds4_gov_mode_parse("offx") == -1);
    for (int mi = 0; mi < DS4_GOV_MODE__COUNT; mi++)
        TEST_ASSERT(ds4_gov_mode_parse(ds4_gov_mode_name(mi)) == mi);
    /* Env layering: global default, per-family override, bogus value
     * keeps the layer beneath (loudly -- stderr, not asserted here). */
    setenv("DS4_MEMGOV", "enforce", 1);
    setenv("DS4_MEMGOV_SERIAL", "off", 1);
    setenv("DS4_MEMGOV_STATIC", "bogus", 1);
    ds4_gov_modes_init();
    TEST_ASSERT(ds4_gov_mode(DS4_GOVC_ENGINE_BOOT) == DS4_GOV_MODE_ENFORCE);
    TEST_ASSERT(ds4_gov_mode(DS4_GOVC_BATCH_BANK_PLAN) == DS4_GOV_MODE_ENFORCE);
    TEST_ASSERT(ds4_gov_mode(DS4_GOVC_SERIAL_SESSION) == DS4_GOV_MODE_OFF);
    TEST_ASSERT(ds4_gov_mode(DS4_GOVC_STATIC_BATCH) == DS4_GOV_MODE_ENFORCE);
    TEST_ASSERT(ds4_gov_mode(-1) == DS4_GOV_MODE_OFF);
    TEST_ASSERT(ds4_gov_mode(DS4_GOVC__COUNT) == DS4_GOV_MODE_OFF);
    /* OFF is the kill switch: publications drop, checks tick nothing. */
    ds4_gov_ledger lg;
    ds4_gov_publish_use(DS4_GOVC_SERIAL_SESSION, 777, 777);
    ds4_gov_snapshot(&lg);
    TEST_ASSERT(lg.lease[DS4_GOVC_SERIAL_SESSION].intent == 0);
    ds4_metrics *m = ds4_metrics_get();
    uint64_t cells0 = 0, cells1 = 0;
    for (int c = 0; c < DS4_GOVC__COUNT; c++)
        for (int st = 0; st < DS4_GOV_STATUS__COUNT; st++)
            for (int r = 0; r < DS4_GOV_CMP__COUNT; r++)
                cells0 += ds4_metric_read(&m->memgov_decisions[c][st][r]);
    ds4_gov_claim cl = {0};
    cl.requester = DS4_GOVC_SERIAL_SESSION;
    cl.memc = DS4_MEMC_SESSION_TENSORS;
    cl.domain = DS4_MEMD_UNIFIED_DEVICE;
    cl.proposed_outstanding = 4096;
    ds4_gov_shadow_check("unit", &cl, DS4_GOV_ADMIT);
    for (int c = 0; c < DS4_GOVC__COUNT; c++)
        for (int st = 0; st < DS4_GOV_STATUS__COUNT; st++)
            for (int r = 0; r < DS4_GOV_CMP__COUNT; r++)
                cells1 += ds4_metric_read(&m->memgov_decisions[c][st][r]);
    TEST_ASSERT(cells1 == cells0);
    /* DS4_MEMGOV=observe is the one-word rollback: every family shadows
     * regardless of the ratcheted per-family defaults. */
    setenv("DS4_MEMGOV", "observe", 1);
    unsetenv("DS4_MEMGOV_SERIAL");
    unsetenv("DS4_MEMGOV_STATIC");
    ds4_gov_modes_init();
    for (int c = 0; c < DS4_GOVC__COUNT; c++)
        TEST_ASSERT(ds4_gov_mode(c) == DS4_GOV_MODE_OBSERVE);
    /* Ship defaults (D2-2b/4/5 ratchets): THE FULL ENFORCE BOARD.
     * This assertion IS the ratchet's unit-level record. */
    unsetenv("DS4_MEMGOV");
    ds4_gov_modes_init();
    for (int c = 0; c < DS4_GOVC__COUNT; c++)
        TEST_ASSERT(ds4_gov_mode(c) == DS4_GOV_MODE_ENFORCE);
    /* The margin variant dispatches identically (same core, caller's
     * protected term): a class-refusing claim under enforce must refuse
     * through it exactly as the floored check would. */
    setenv("DS4_MEMGOV_STATIC", "enforce", 1);
    ds4_gov_modes_init();
    {
        ds4_gov_claim mcl = {0};
        mcl.requester = DS4_GOVC_STATIC_BATCH;
        mcl.memc = DS4_MEMC_SESSION_TENSORS;
        mcl.domain = DS4_MEMD_UNIFIED_DEVICE;
        mcl.proposed_outstanding = 100;
        mcl.class_limit = 10;
        ds4_mem_observation mo;
        memset(&mo, 0, sizeof(mo));
        (void)ds4_gpu_mem_observe(&mo);
        const int mwant = mo.status == DS4_MEMOBS_OK ? DS4_GOV_REFUSE_CLASS
                                                     : DS4_GOV_ADMIT;
        TEST_ASSERT(ds4_gov_governed_check_margin("unit", &mcl, DS4_GOV_ADMIT,
                                                  1u << 20) == mwant);
    }
    unsetenv("DS4_MEMGOV_STATIC");
    ds4_gov_modes_init();
    ds4_gov_publish_use(DS4_GOVC_SERIAL_SESSION, 5, 5);
    ds4_gov_snapshot(&lg);
    TEST_ASSERT(lg.lease[DS4_GOVC_SERIAL_SESSION].intent == 5);
    ds4_gov_publish_use(DS4_GOVC_SERIAL_SESSION, 0, 0);
}

/* memgov D2-2: governed_check mode dispatch.  observe/off return the
 * legacy verdict; enforce returns the quote -- but only when the backend
 * has an OK memory observation (Metal/CPU: UNSUPPORTED defers to legacy,
 * the documented sec 6.4 policy), so the enforce expectation is derived
 * from the live observation status, not hardcoded per platform. */
static void test_mem_gov_governed_check(void) {
    ds4_gov_claim cl = {0};
    cl.requester = DS4_GOVC_STATIC_BATCH;
    cl.memc = DS4_MEMC_SESSION_TENSORS;
    cl.domain = DS4_MEMD_UNIFIED_DEVICE;
    cl.proposed_outstanding = 100;
    cl.class_limit = 10;             /* class-refusing claim by design */
    /* observe: legacy rules regardless of the quote.  Pinned explicitly
     * -- the SHIP default is enforce since the D2-5 full board, so on a
     * CUDA backend (observation OK) an unpinned check would refuse
     * (exactly how the stage-close battery caught this assumption). */
    setenv("DS4_MEMGOV_STATIC", "observe", 1);
    ds4_gov_modes_init();
    TEST_ASSERT(ds4_gov_governed_check("unit", &cl, DS4_GOV_ADMIT)
                == DS4_GOV_ADMIT);
    /* enforce: the quote rules where the backend can quote. */
    ds4_mem_observation o;
    memset(&o, 0, sizeof(o));
    (void)ds4_gpu_mem_observe(&o);
    const int want = o.status == DS4_MEMOBS_OK ? DS4_GOV_REFUSE_CLASS
                                               : DS4_GOV_ADMIT;
    setenv("DS4_MEMGOV_STATIC", "enforce", 1);
    ds4_gov_modes_init();
    TEST_ASSERT(ds4_gov_governed_check("unit", &cl, DS4_GOV_ADMIT) == want);
    /* off: legacy rules, zero governor activity. */
    setenv("DS4_MEMGOV_STATIC", "off", 1);
    ds4_gov_modes_init();
    TEST_ASSERT(ds4_gov_governed_check("unit", &cl, DS4_GOV_ADMIT)
                == DS4_GOV_ADMIT);
    /* malformed pair: fault counted, legacy rules. */
    const uint64_t f0 = ds4_metric_read(&ds4_metrics_get()->memgov_faults);
    TEST_ASSERT(ds4_gov_governed_check("unit", NULL, DS4_GOV_ADMIT)
                == DS4_GOV_ADMIT);
    TEST_ASSERT(ds4_metric_read(&ds4_metrics_get()->memgov_faults) == f0 + 1);
    unsetenv("DS4_MEMGOV_STATIC");
    ds4_gov_modes_init();
}

/* memgov D2-5 stage close: ORDER INDEPENDENCE.  Lease publications are
 * absolute replacements (sec 6.2), so every permutation of the same
 * final publications must yield an identical quote for a frozen claim
 * -- the property that makes the seqlock's single-writer discipline
 * sufficient (no ordering law needed beyond it).  Republication
 * idempotence rides the same harness (replace, never accumulate). */
static void test_mem_gov_order_independence(void) {
    static const int cons[3] = { DS4_GOVC_ENGINE_BOOT,
                                 DS4_GOVC_BATCH_BANK_PLAN,
                                 DS4_GOVC_SERIAL_SESSION };
    static const uint64_t vals[3][3] = {   /* intent, resident, reservation */
        { 1000, 800, 0 }, { 500, 200, 0 }, { 300, 0, 128 },
    };
    static const int perms[6][3] = { {0,1,2},{0,2,1},{1,0,2},
                                     {1,2,0},{2,0,1},{2,1,0} };
    ds4_mem_observation obs;
    memset(&obs, 0, sizeof(obs));
    obs.status = DS4_MEMOBS_OK;
    obs.source = DS4_MEMOBS_SRC_MEMINFO_AVAILABLE;
    obs.free_bytes = 4096;
    obs.total_bytes = 65536;
    ds4_gov_claim cl = {0};
    cl.requester = DS4_GOVC_SERIAL_SESSION;
    cl.memc = DS4_MEMC_SESSION_TENSORS;
    cl.domain = DS4_MEMD_UNIFIED_DEVICE;
    cl.proposed_outstanding = 900;
    cl.operation_transient = 64;
    ds4_gov_quote q0;
    memset(&q0, 0, sizeof(q0));
    for (int p = 0; p < 7; p++) {           /* 6 permutations + republish */
        ds4_gov_ledger lg;
        memset(&lg, 0, sizeof(lg));
        lg.floor_bytes = 512;
        lg.substrate_outstanding = 32;
        uint64_t faults = 0;
        const int *ord = perms[p < 6 ? p : 0];
        for (int i = 0; i < 3; i++) {
            const int k = ord[i];
            TEST_ASSERT(ds4_gov_lease_publish(&lg, cons[k], vals[k][0],
                                              vals[k][1], vals[k][2],
                                              &faults));
        }
        if (p == 6)   /* idempotence: republish one lease verbatim */
            TEST_ASSERT(ds4_gov_lease_publish(&lg, cons[1], vals[1][0],
                                              vals[1][1], vals[1][2],
                                              &faults));
        TEST_ASSERT(faults == 0);
        const ds4_gov_quote q = ds4_gov_evaluate(&lg, &obs, &cl);
        if (p == 0) {
            q0 = q;
            TEST_ASSERT(q.status == DS4_GOV_ADMIT);   /* sanity: fundable */
        } else {
            TEST_ASSERT(q.status == q0.status);
            TEST_ASSERT(q.available == q0.available);
            TEST_ASSERT(q.required == q0.required);
            TEST_ASSERT(q.deficit == q0.deficit);
            TEST_ASSERT(q.other_reservations == q0.other_reservations);
            TEST_ASSERT(q.total_prospective_intent ==
                        q0.total_prospective_intent);
        }
    }
}

/* memgov D1a-1: model-source table (pure logic from ds4_mem_census.h --
 * the exact bind/containment resolution the CUDA backend attributes
 * every WEIGHT_* census note with). */
static void test_mem_src_table_bind_find(void) {
    /* One backing arena with guard gaps: adjacent static arrays would make
     * one-past-end of a map alias the NEXT map's base, which containment
     * legitimately resolves (mmaps in production are never adjacent). */
    static char backing[16384];
    char *base_map = backing;              /* [0, 4096)     */
    char *mtp_map = backing + 6144;        /* [6144, 6656)  */
    char *drafter_map = backing + 8192;    /* [8192, 8448)  */
    const uint64_t base_len = 4096, mtp_len = 512, drafter_len = 256;
    ds4_model_source_table t;
    uint64_t faults = 0;
    memset(&t, 0, sizeof t);

    /* Bad descriptors fault and refuse. */
    TEST_ASSERT(ds4_model_source_bind(&t, NULL, 10, 0, -1,
                                      DS4_RESIDENCY_EAGER_DEVICE,
                                      "x", "p", &faults) == -1);
    TEST_ASSERT(ds4_model_source_bind(&t, base_map, 0, 0, -1,
                                      DS4_RESIDENCY_EAGER_DEVICE,
                                      "x", "p", &faults) == -1);
    TEST_ASSERT(faults == 2 && t.count == 0);

    const int b = ds4_model_source_bind(&t, base_map, base_len,
                                        DS4_MSRC_ROLE_PRIMARY, 7,
                                        DS4_RESIDENCY_EAGER_DEVICE,
                                        "base", "/models/base.gguf", &faults);
    const int m = ds4_model_source_bind(&t, mtp_map, mtp_len,
                                        DS4_MSRC_ROLE_AUXILIARY, 8,
                                        DS4_RESIDENCY_LAZY_COPY_DEVICE,
                                        "mtp", "/models/mtp.gguf", &faults);
    const int d = ds4_model_source_bind(&t, drafter_map, drafter_len,
                                        DS4_MSRC_ROLE_DRAFTER, 9,
                                        DS4_RESIDENCY_HOST_MAPPED,
                                        "drafter", NULL, &faults);
    TEST_ASSERT(b == 0 && m == 1 && d == 2 && t.count == 3 && faults == 2);
    TEST_ASSERT(t.v[b].fd == 7 && t.v[d].path[0] == '\0');
    TEST_ASSERT(strcmp(t.v[m].name, "mtp") == 0);
    /* memgov D3-2: the handle carries the resolved residency. */
    TEST_ASSERT(t.v[b].residency == DS4_RESIDENCY_EAGER_DEVICE &&
                t.v[m].residency == DS4_RESIDENCY_LAZY_COPY_DEVICE &&
                t.v[d].residency == DS4_RESIDENCY_HOST_MAPPED);

    /* Resolution: base equality, interior containment, one-past-end and
     * unrelated pointers miss. */
    TEST_ASSERT(ds4_model_source_find(&t, base_map) == b);
    TEST_ASSERT(ds4_model_source_find(&t, base_map + 1) == b);
    TEST_ASSERT(ds4_model_source_find(&t, base_map + base_len - 1) == b);
    TEST_ASSERT(ds4_model_source_find(&t, mtp_map + 100) == m);
    TEST_ASSERT(ds4_model_source_find(&t, drafter_map + drafter_len) == -1);
    TEST_ASSERT(ds4_model_source_find(&t, &faults) == -1);
    TEST_ASSERT(ds4_model_source_find(&t, NULL) == -1);

    /* Rebind refreshes in place: the handle (= ledger row key) is stable. */
    TEST_ASSERT(ds4_model_source_bind(&t, mtp_map, mtp_len,
                                      DS4_MSRC_ROLE_AUXILIARY, 12,
                                      DS4_RESIDENCY_EAGER_DEVICE,
                                      "mtp", "/models/mtp-v2.gguf", &faults) == m);
    TEST_ASSERT(t.count == 3 && t.v[m].fd == 12);
    TEST_ASSERT(t.v[m].residency == DS4_RESIDENCY_EAGER_DEVICE);
    TEST_ASSERT(strcmp(t.v[m].path, "/models/mtp-v2.gguf") == 0);

    /* Overflow faults and refuses; the table keeps its bound entries.
     * Gapped 16-byte strides in the arena tail, 8-byte lengths. */
    int accepted = 0;
    for (int i = 0; i < DS4_MSRC_MAX; i++)
        if (ds4_model_source_bind(&t, backing + 12288 + 16 * i, 8, 0, -1,
                                  DS4_RESIDENCY_EAGER_DEVICE,
                                  "extra", NULL, &faults) >= 0)
            accepted++;
    TEST_ASSERT(t.count == DS4_MSRC_MAX);
    TEST_ASSERT(accepted == DS4_MSRC_MAX - 3);
    TEST_ASSERT(faults == 2 + 3);

    /* Role names are total over the enum (publication-shape discipline). */
    TEST_ASSERT(strcmp(ds4_model_source_role_name(DS4_MSRC_ROLE_PRIMARY), "primary") == 0);
    TEST_ASSERT(strcmp(ds4_model_source_role_name(DS4_MSRC_ROLE_AUXILIARY), "auxiliary") == 0);
    TEST_ASSERT(strcmp(ds4_model_source_role_name(DS4_MSRC_ROLE_DRAFTER), "drafter") == 0);
    TEST_ASSERT(strcmp(ds4_model_source_role_name(99), "unknown") == 0);
}

/* memgov D1a-2: the semantic tensor classifier (ds4_model_catalog.h) --
 * the exact suffix/type/dims rules the engine builds every model's
 * catalog with, pinned against the binder names and the repack
 * candidacy mirrors. */
static uint32_t test_tcat(const char *name, uint32_t ndim, uint32_t type,
                          uint64_t d0, uint64_t d1, uint64_t d2,
                          uint64_t bytes) {
    const uint64_t dims[4] = {d0, d1, d2, 1};
    return ds4_tensor_catalog_classify(name, strlen(name), ndim, type,
                                       dims, bytes);
}

static void test_model_catalog_classify(void) {
    /* Routed 3-D expert stacks; artifact-replaced when the repack rules
     * hold (IQ2_XXS gate/up, Q2_K down). */
    TEST_ASSERT(test_tcat("blk.7.ffn_gate_exps.weight", 3, 16, 2048, 1024, 256, 66 * 1000) ==
                (DS4_TCAT_ROUTED_EXPERT | DS4_TCAT_ARTIFACT_REPLACED));
    TEST_ASSERT(test_tcat("mtp.0.ffn_down_exps.weight", 3, 10, 2560, 2048, 256, 84 * 500) ==
                (DS4_TCAT_ROUTED_EXPERT | DS4_TCAT_ARTIFACT_REPLACED));
    /* Routed but NOT replaced: bad alignment / wrong type / wrong stack. */
    TEST_ASSERT(test_tcat("dspark.1.ffn_up_exps.weight", 3, 16, 1000, 1024, 64, 66 * 10) ==
                DS4_TCAT_ROUTED_EXPERT);
    TEST_ASSERT(test_tcat("blk.7.ffn_down_exps.weight", 3, 16, 2048, 1024, 256, 66 * 1000) ==
                DS4_TCAT_ROUTED_EXPERT);   /* IQ2 down is not a candidate */
    TEST_ASSERT(test_tcat("blk.7.ffn_gate_exps.weight", 2, 16, 2048, 1024, 0, 66 * 1000) == 0);
    /* Shared experts are NOT routed; a big aligned Q8_0 one is an
     * aligned-dense additive candidate exactly like the repack rule. */
    TEST_ASSERT(test_tcat("blk.3.ffn_gate_shexp.weight", 2, 8, 4096, 2048, 0, 34u * 100000u) ==
                DS4_TCAT_ARTIFACT_ADDITIVE);
    /* token_embd is excluded from the aligned-dense tier. */
    TEST_ASSERT(test_tcat("token_embd.weight", 2, 8, 4096, 129280, 0, 34u * 100000u) == 0);
    /* attn_output_a rides the f16 prebuild tier even under the 2 MiB
     * dense floor. */
    TEST_ASSERT(test_tcat("blk.2.attn_output_a.weight", 2, 8, 4096, 512, 0, 34u * 30000u) ==
                DS4_TCAT_ARTIFACT_ADDITIVE);
    /* Optional bind (exp_probs bias). */
    TEST_ASSERT(test_tcat("blk.9.exp_probs_b.bias", 1, 0, 256, 0, 0, 1024) ==
                DS4_TCAT_OPTIONAL);

    /* TRIPWIRE RELATION PIN: over the real name shapes, the catalog's
     * ROUTED bit must equal the legacy memmem("_exps.") predicate -- the
     * exact cross-check the pre-cache site runs for this one stage. */
    static const struct { const char *nm; uint32_t nd; } corpus[] = {
        {"blk.0.ffn_gate_exps.weight", 3}, {"blk.0.ffn_up_exps.weight", 3},
        {"blk.0.ffn_down_exps.weight", 3}, {"mtp.0.ffn_gate_exps.weight", 3},
        {"dspark.2.ffn_down_exps.weight", 3},
        {"blk.0.ffn_gate_shexp.weight", 2}, {"blk.0.ffn_up_shexp.weight", 2},
        {"blk.0.ffn_down_shexp.weight", 2}, {"blk.0.exp_probs_b.bias", 1},
        {"blk.0.attn_kv.weight", 2}, {"blk.0.indexer.proj.weight", 2},
        {"token_embd.weight", 2}, {"output.weight", 2},
    };
    for (size_t i = 0; i < sizeof(corpus) / sizeof(corpus[0]); i++) {
        const uint32_t tr = test_tcat(corpus[i].nm, corpus[i].nd, 16, 2048, 1024, 256, 66);
        const int legacy = ds4_tcat_contains(corpus[i].nm, strlen(corpus[i].nm), "_exps.");
        TEST_ASSERT(((tr & DS4_TCAT_ROUTED_EXPERT) != 0) == (legacy != 0));
    }

    /* Counts render helper. */
    {
        const uint8_t traits[] = {0, DS4_TCAT_ROUTED_EXPERT,
                                  DS4_TCAT_ROUTED_EXPERT | DS4_TCAT_ARTIFACT_REPLACED,
                                  DS4_TCAT_ARTIFACT_ADDITIVE, DS4_TCAT_OPTIONAL};
        ds4_model_catalog_counts cc;
        ds4_model_catalog_count(traits, 5, &cc);
        TEST_ASSERT(cc.tensors == 5 && cc.routed == 2 && cc.replaced == 1 &&
                    cc.additive == 1 && cc.optional == 1);
        ds4_model_catalog_count(NULL, 3, &cc);
        TEST_ASSERT(cc.tensors == 3 && cc.routed == 0);
    }
}

/* memgov D1a-3: unit-compiler property tests (ds4_model_catalog.h).
 * Every invariant the boot build reconciles is pinned here on synthetic
 * layouts: exact coverage, no overlap/split, policy homogeneity,
 * merge/cap rules, rounding exactness, slice exclusion, import rules. */
/* memgov D3-2: the residency resolver's full truth table.  The resolver
 * is pure -- no env reads -- so every legacy alias shape and every strict
 * conflict is pinned here exactly as the engine-open block feeds it. */
static void test_residency_resolver(void) {
    const char *why = NULL;
    ds4_residency_inputs in;

    /* Legacy alias table: the historical shapes keep their meaning. */
    memset(&in, 0, sizeof in);
    TEST_ASSERT(ds4_residency_resolve(&in, &why) == DS4_RESIDENCY_EAGER_DEVICE);
    in.legacy_no_hbm = 1;
    TEST_ASSERT(ds4_residency_resolve(&in, &why) == DS4_RESIDENCY_LAZY_COPY_DEVICE);
    in.legacy_no_fd = 1;
    TEST_ASSERT(ds4_residency_resolve(&in, &why) == DS4_RESIDENCY_HOST_MAPPED);
    memset(&in, 0, sizeof in);
    in.legacy_no_fd = 1;                 /* mechanism-only lever: EAGER */
    TEST_ASSERT(ds4_residency_resolve(&in, &why) == DS4_RESIDENCY_EAGER_DEVICE);
    memset(&in, 0, sizeof in);
    in.legacy_direct = 1;                /* raw-direct: terminal mapped */
    TEST_ASSERT(ds4_residency_resolve(&in, &why) == DS4_RESIDENCY_HOST_MAPPED);
    in.legacy_no_hbm = 1;                /* legacy-only mixes stay legal */
    TEST_ASSERT(ds4_residency_resolve(&in, &why) == DS4_RESIDENCY_HOST_MAPPED);

    /* Explicit knob owns the decision. */
    memset(&in, 0, sizeof in);
    in.explicit_val = "eager";
    TEST_ASSERT(ds4_residency_resolve(&in, &why) == DS4_RESIDENCY_EAGER_DEVICE);
    in.explicit_val = "lazy";
    TEST_ASSERT(ds4_residency_resolve(&in, &why) == DS4_RESIDENCY_LAZY_COPY_DEVICE);
    in.explicit_val = "mapped";
    TEST_ASSERT(ds4_residency_resolve(&in, &why) == DS4_RESIDENCY_HOST_MAPPED);

    /* Strict conflicts: explicit + ANY legacy lever refuses with a
     * reason; unknown values refuse; empty string = unset. */
    in.explicit_val = "mapped"; in.legacy_no_hbm = 1;
    TEST_ASSERT(ds4_residency_resolve(&in, &why) == -1 && why != NULL);
    memset(&in, 0, sizeof in);
    in.explicit_val = "eager"; in.legacy_direct = 1; why = NULL;
    TEST_ASSERT(ds4_residency_resolve(&in, &why) == -1 && why != NULL);
    memset(&in, 0, sizeof in);
    in.explicit_val = "lazy"; in.legacy_no_fd = 1; why = NULL;
    TEST_ASSERT(ds4_residency_resolve(&in, &why) == -1 && why != NULL);
    memset(&in, 0, sizeof in);
    in.explicit_val = "device"; why = NULL;   /* unknown vocabulary */
    TEST_ASSERT(ds4_residency_resolve(&in, &why) == -1 && why != NULL);
    memset(&in, 0, sizeof in);
    in.explicit_val = "";                     /* empty = unset -> alias */
    in.legacy_no_hbm = 1;
    TEST_ASSERT(ds4_residency_resolve(&in, &why) == DS4_RESIDENCY_LAZY_COPY_DEVICE);
    TEST_ASSERT(ds4_residency_resolve(NULL, &why) == -1);

    /* Names are total (publication-shape discipline). */
    TEST_ASSERT(strcmp(ds4_residency_name(DS4_RESIDENCY_EAGER_DEVICE), "eager") == 0);
    TEST_ASSERT(strcmp(ds4_residency_name(DS4_RESIDENCY_LAZY_COPY_DEVICE), "lazy") == 0);
    TEST_ASSERT(strcmp(ds4_residency_name(DS4_RESIDENCY_HOST_MAPPED), "mapped") == 0);
    TEST_ASSERT(strcmp(ds4_residency_name(99), "unknown") == 0);
}

static void test_unit_compiler_properties(void) {
    ds4_unit_compile_params p;
    memset(&p, 0, sizeof p);
    p.merge_gap = 64;
    p.max_unit_bytes = 4096;
    p.vmm_granularity = 256;
    p.device_promote = 1;
    p.replaces_complete = 0;

    /* Merge within gap + policy split + coverage/verify green. */
    {
        const ds4_unit_tensor_in ts[] = {
            {0, 100, 0, 1},                                /* hot          */
            {150, 100, 0, 1},                              /* hot, gap 50  */
            {300, 500, DS4_TCAT_ROUTED_EXPERT, 1},         /* expert       */
            {820, 100, 0, 1},                              /* hot, gap 20
                                                              from expert  */
        };
        ds4_phys_unit u[4];
        const int nu = ds4_units_compile(ts, 4, &p, u);
        TEST_ASSERT(nu == 3);
        TEST_ASSERT(u[0].src_off == 0 && u[0].src_bytes == 250 && u[0].n_tensors == 2);
        TEST_ASSERT(u[0].policy == DS4_UPOL_DEVICE_PROMOTE);
        TEST_ASSERT(u[0].allocator == DS4_UALLOC_VMM_ARENA);
        TEST_ASSERT(u[0].planned_bytes == 256);            /* 250 -> 256   */
        TEST_ASSERT(u[1].policy == DS4_UPOL_EXPERT_COLD && u[1].n_tensors == 1);
        TEST_ASSERT(u[1].allocator == DS4_UALLOC_NONE && u[1].planned_bytes == 500);
        TEST_ASSERT(u[2].src_off == 820);                  /* no cross-
                                                              policy merge */
        TEST_ASSERT(ds4_units_verify(ts, 4, &p, u, nu) == 0);
        ds4_unit_table_counts uc;
        ds4_units_count(u, nu, &uc);
        TEST_ASSERT(uc.units == 3 && uc.covered_bytes == 250 + 500 + 100);
        TEST_ASSERT(uc.promote_bytes == 350 && uc.cold_bytes == 500);
    }

    /* Gap beyond merge_gap splits; oversized tensor is its own intact
     * unit and nothing merges into it past the cap. */
    {
        const ds4_unit_tensor_in ts[] = {
            {0, 100, 0, 1},
            {200, 100, 0, 1},          /* gap 100 > 64: new unit          */
            {310, 8000, 0, 1},         /* > max_unit_bytes: own unit      */
            {8320, 100, 0, 1},         /* would exceed cap if merged      */
        };
        ds4_phys_unit u[4];
        const int nu = ds4_units_compile(ts, 4, &p, u);
        TEST_ASSERT(nu == 4);
        TEST_ASSERT(u[2].src_bytes == 8000 && u[2].n_tensors == 1);
        TEST_ASSERT(u[3].src_off == 8320);
        TEST_ASSERT(ds4_units_verify(ts, 4, &p, u, nu) == 0);
    }

    /* Slice exclusion: inactive tensors join no unit; actives on both
     * sides stay covered. */
    {
        const ds4_unit_tensor_in ts[] = {
            {0, 100, 0, 1},
            {110, 100, 0, 0},          /* inactive (out of slice)         */
            {220, 100, 0, 1},
        };
        ds4_phys_unit u[3];
        const int nu = ds4_units_compile(ts, 3, &p, u);
        TEST_ASSERT(nu == 2);
        TEST_ASSERT(u[0].n_tensors == 1 && u[1].n_tensors == 1);
        TEST_ASSERT(ds4_units_verify(ts, 3, &p, u, nu) == 0);
    }

    /* replaces_complete flips only REPLACED-trait experts. */
    {
        ds4_unit_compile_params pr = p;
        pr.replaces_complete = 1;
        const ds4_unit_tensor_in ts[] = {
            {0, 100, DS4_TCAT_ROUTED_EXPERT | DS4_TCAT_ARTIFACT_REPLACED, 1},
            {1000, 100, DS4_TCAT_ROUTED_EXPERT, 1},
        };
        ds4_phys_unit u[2];
        const int nu = ds4_units_compile(ts, 2, &pr, u);
        TEST_ASSERT(nu == 2);
        TEST_ASSERT(u[0].policy == DS4_UPOL_ARTIFACT_REPLACED);
        TEST_ASSERT(u[1].policy == DS4_UPOL_EXPERT_COLD);
        TEST_ASSERT(ds4_units_verify(ts, 2, &pr, u, nu) == 0);
    }

    /* mapped residency: hot tensors plan HOST_MAPPED with no allocator. */
    {
        ds4_unit_compile_params ph = p;
        ph.device_promote = 0;
        const ds4_unit_tensor_in ts[] = {{0, 100, 0, 1}};
        ds4_phys_unit u[1];
        TEST_ASSERT(ds4_units_compile(ts, 1, &ph, u) == 1);
        TEST_ASSERT(u[0].policy == DS4_UPOL_HOST_MAPPED &&
                    u[0].allocator == DS4_UALLOC_NONE &&
                    u[0].planned_bytes == 100);
    }

    /* Unsorted / overlapping input refuses. */
    {
        const ds4_unit_tensor_in bad1[] = {{100, 50, 0, 1}, {0, 50, 0, 1}};
        const ds4_unit_tensor_in bad2[] = {{0, 100, 0, 1}, {50, 100, 0, 1}};
        ds4_phys_unit u[2];
        TEST_ASSERT(ds4_units_compile(bad1, 2, &p, u) == -1);
        TEST_ASSERT(ds4_units_compile(bad2, 2, &p, u) == -1);
    }

    /* Import satisfaction: ONE device interval must fully cover; two
     * adjacent halves do not; exact-boundary cover does. */
    {
        ds4_phys_unit u;
        memset(&u, 0, sizeof u);
        u.src_off = 1000;
        u.src_bytes = 500;
        const ds4_unit_import_iv full = {900, 700};
        const ds4_unit_import_iv exact = {1000, 500};
        const ds4_unit_import_iv half_a = {1000, 250};
        const ds4_unit_import_iv half_b = {1250, 250};
        const ds4_unit_import_iv halves[] = {{1000, 250}, {1250, 250}};
        TEST_ASSERT(ds4_unit_import_satisfied(&u, &full, 1) == 1);
        TEST_ASSERT(ds4_unit_import_satisfied(&u, &exact, 1) == 1);
        TEST_ASSERT(ds4_unit_import_satisfied(&u, &half_a, 1) == 0);
        TEST_ASSERT(ds4_unit_import_satisfied(&u, &half_b, 1) == 0);
        TEST_ASSERT(ds4_unit_import_satisfied(&u, halves, 2) == 0);
        TEST_ASSERT(ds4_unit_import_satisfied(&u, NULL, 0) == 0);
    }

    /* Verify catches a corrupted table: shrink a unit so its member
     * tensor is split across the boundary. */
    {
        const ds4_unit_tensor_in ts[] = {{0, 100, 0, 1}};
        ds4_phys_unit u[1];
        TEST_ASSERT(ds4_units_compile(ts, 1, &p, u) == 1);
        u[0].src_bytes = 50;
        TEST_ASSERT(ds4_units_verify(ts, 1, &p, u, 1) != 0);
    }
}

/* memgov D1a-4: the publication funnel's unit-span stamp.  Table units:
 * [100,200) [250,350) [1000,2000) -- gaps before, between, and after. */
static void test_unit_span_lookup(void) {
    ds4_phys_unit u[3];
    memset(u, 0, sizeof u);
    u[0].src_off = 100;  u[0].src_bytes = 100;
    u[1].src_off = 250;  u[1].src_bytes = 100;
    u[2].src_off = 1000; u[2].src_bytes = 1000;
    int lo, hi;

    ds4_units_span_of(u, 3, 120, 10, &lo, &hi);        /* interior of one  */
    TEST_ASSERT(lo == 0 && hi == 0);
    ds4_units_span_of(u, 3, 100, 100, &lo, &hi);       /* exact unit       */
    TEST_ASSERT(lo == 0 && hi == 0);
    ds4_units_span_of(u, 3, 150, 200, &lo, &hi);       /* spans the gap    */
    TEST_ASSERT(lo == 0 && hi == 1);
    ds4_units_span_of(u, 3, 0, 4096, &lo, &hi);        /* covers them all  */
    TEST_ASSERT(lo == 0 && hi == 2);
    ds4_units_span_of(u, 3, 0, 100, &lo, &hi);         /* ends AT first    */
    TEST_ASSERT(lo == -1 && hi == -1);
    ds4_units_span_of(u, 3, 200, 50, &lo, &hi);        /* gap between      */
    TEST_ASSERT(lo == -1 && hi == -1);
    ds4_units_span_of(u, 3, 2000, 50, &lo, &hi);       /* past the last    */
    TEST_ASSERT(lo == -1 && hi == -1);
    ds4_units_span_of(u, 3, 350, 700, &lo, &hi);       /* gap up to last   */
    TEST_ASSERT(lo == 2 && hi == 2);
    ds4_units_span_of(u, 3, 120, 0, &lo, &hi);         /* empty interval   */
    TEST_ASSERT(lo == -1 && hi == -1);
    ds4_units_span_of(NULL, 0, 120, 10, &lo, &hi);     /* no table         */
    TEST_ASSERT(lo == -1 && hi == -1);
    ds4_units_span_of(u, 3, UINT64_MAX - 10, 100, &lo, &hi);  /* overflow  */
    TEST_ASSERT(lo == -1 && hi == -1);
}

/* v0.6.3 Inc 5: whole-prompt depth fence predicate.  Pure env+arith --
 * pin the default-config immunity, the fenced shapes, the boundary, and
 * the escape hatch. */
static void test_prefill_depth_fence(void) {
    const char *old_chunk = getenv("DS4_METAL_PREFILL_CHUNK");
    const char *old_nofence = getenv("DS4_PREFILL_NOFENCE");
    char *saved_chunk = old_chunk ? xstrdup(old_chunk) : NULL;
    char *saved_nofence = old_nofence ? xstrdup(old_nofence) : NULL;
    uint32_t w = 0, f = 0;

    /* Default config: chunked at 4096; the fence is unreachable. */
    unsetenv("DS4_METAL_PREFILL_CHUNK");
    unsetenv("DS4_PREFILL_NOFENCE");
    TEST_ASSERT(ds4_prefill_fence_rows() == 8192u);
    TEST_ASSERT(!ds4_serial_prefill_fenced(32768, 20000, &w, &f));
    TEST_ASSERT(w == 4096u && f == 8192u);

    /* Whole-prompt mode: the cap pins to ctx; a deep prompt trips it. */
    setenv("DS4_METAL_PREFILL_CHUNK", "0", 1);
    TEST_ASSERT(ds4_serial_prefill_fenced(32768, 20000, &w, &f));
    TEST_ASSERT(w == 20000u && f == 8192u);
    /* Boundary is inclusive: exactly 8192 rows is proven territory. */
    TEST_ASSERT(!ds4_serial_prefill_fenced(32768, 8192, &w, &f));
    TEST_ASSERT(w == 8192u);
    /* An explicit wide chunk trips it too (the chunked branch submits
     * cap-wide forwards). */
    setenv("DS4_METAL_PREFILL_CHUNK", "16384", 1);
    TEST_ASSERT(ds4_serial_prefill_fenced(1048576, 100000, &w, &f));
    TEST_ASSERT(w == 16384u);

    /* The escape hatch lifts the fence entirely. */
    setenv("DS4_PREFILL_NOFENCE", "1", 1);
    TEST_ASSERT(ds4_prefill_fence_rows() == 0u);
    setenv("DS4_METAL_PREFILL_CHUNK", "0", 1);
    TEST_ASSERT(!ds4_serial_prefill_fenced(1048576, 1000000, &w, &f));
    TEST_ASSERT(w == 1000000u && f == 0u);

    if (saved_chunk) { setenv("DS4_METAL_PREFILL_CHUNK", saved_chunk, 1); free(saved_chunk); }
    else unsetenv("DS4_METAL_PREFILL_CHUNK");
    if (saved_nofence) { setenv("DS4_PREFILL_NOFENCE", saved_nofence, 1); free(saved_nofence); }
    else unsetenv("DS4_PREFILL_NOFENCE");
}

/* v0.6.3 Inc 6: the best-fit final-victim pick is pure arithmetic -- the
 * v0.6.2 victim-order precedent (synthetic scenarios pin the policy; the
 * ladder's disclosure lines carry field engagement evidence, since live
 * small-ctx legs cannot exercise it: VMM page-phase alignment leaves only
 * phase-aligned banks with interior pages there). */
static void test_trim_bestfit_pick(void) {
    /* the receipt scenario: the default (deep, oldest) covers, but a
     * smaller covering victim sits later in the order */
    {
        const uint64_t est[]  = {2896, 1700, 900};
        const uint8_t  val[]  = {1, 1, 1};
        const uint32_t hist[] = {200000, 90000, 40000};
        /* want 1646: est 900 does not cover; 1700 does and beats 2896 */
        TEST_ASSERT(ds4_trim_bestfit_pick(est, val, hist, 3, 1646) == 1u);
    }
    /* equal covering estimates: prefer the shallower victim */
    {
        const uint64_t est[]  = {42, 42, 42};
        const uint8_t  val[]  = {1, 1, 1};
        const uint32_t hist[] = {13823, 3562, 9000};
        TEST_ASSERT(ds4_trim_bestfit_pick(est, val, hist, 3, 13) == 1u);
    }
    /* class guard: never trade an invalid-history default up into a
     * valid bank (and vice versa) */
    {
        const uint64_t est[]  = {42, 20, 41};
        const uint8_t  val[]  = {0, 1, 0};
        const uint32_t hist[] = {0, 500, 0};
        TEST_ASSERT(ds4_trim_bestfit_pick(est, val, hist, 3, 13) == 2u);
    }
    /* non-covering candidates are skipped even if smaller */
    {
        const uint64_t est[]  = {42, 12, 41};
        const uint8_t  val[]  = {1, 1, 1};
        const uint32_t hist[] = {9000, 100, 8000};
        TEST_ASSERT(ds4_trim_bestfit_pick(est, val, hist, 3, 13) == 2u);
    }
    /* nothing beats the default -> 0 */
    {
        const uint64_t est[]  = {42, 5, 6};
        const uint8_t  val[]  = {1, 1, 1};
        const uint32_t hist[] = {9000, 10, 20};
        TEST_ASSERT(ds4_trim_bestfit_pick(est, val, hist, 3, 13) == 0u);
    }
    /* single candidate and degenerate inputs */
    {
        const uint64_t est[]  = {42};
        const uint8_t  val[]  = {1};
        const uint32_t hist[] = {9000};
        TEST_ASSERT(ds4_trim_bestfit_pick(est, val, hist, 1, 13) == 0u);
        TEST_ASSERT(ds4_trim_bestfit_pick(NULL, val, hist, 1, 13) == 0u);
        TEST_ASSERT(ds4_trim_bestfit_pick(est, val, hist, 0, 13) == 0u);
    }
}

/* Launch-default generation detection keys off the base file NAME only:
 * a Vision-Exp base never picks up a 0731 drafter (the engine would refuse
 * the pairing anyway), and gating directories never leak into the verdict. */
static void test_launch_generation_names(void) {
    const char *vis = "/home/x/gguf/" LAUNCH_BASE_GGUF_VISION;
    const char *old = "/home/x/gguf/" LAUNCH_BASE_GGUF_0731;
    const char *legacy = "/home/x/gguf/" LAUNCH_BASE_GGUF;
    TEST_ASSERT(launch_gen_vision(vis));
    TEST_ASSERT(!launch_gen_0731(vis));
    TEST_ASSERT(launch_gen_0731(old));
    TEST_ASSERT(!launch_gen_vision(old));
    TEST_ASSERT(!launch_gen_0731(legacy) && !launch_gen_vision(legacy));
    /* Directory names carry no generation. */
    TEST_ASSERT(!launch_gen_vision("/home/x/gguf-Vision-Exp/" LAUNCH_BASE_GGUF_0731));
    TEST_ASSERT(!launch_gen_0731("/home/x/gguf0731/" LAUNCH_BASE_GGUF_VISION));
    TEST_ASSERT(launch_gen_vision(LAUNCH_DSPARK_GGUF_VISION) == false); /* drafter name is not a base */
    TEST_ASSERT(strstr(LAUNCH_DSPARK_GGUF_VISION, "vision-exp") != NULL);

    /* A symlinked base (./ds4flash.gguf -> <dir>/<Vision-Exp base>): the
     * link name says nothing, the resolved name carries the generation. */
    {
        char tmpl[] = "/tmp/ds4-launch-XXXXXX";
        char *dir = mkdtemp(tmpl);
        TEST_ASSERT(dir != NULL);
        if (dir) {
            char *target = launch_join(dir, LAUNCH_BASE_GGUF_VISION);
            char *link = launch_join(dir, "ds4flash.gguf");
            FILE *fp = target ? fopen(target, "wb") : NULL;
            TEST_ASSERT(fp != NULL);
            if (fp) fclose(fp);
            TEST_ASSERT(target && link && symlink(target, link) == 0);
            char *real = launch_realpath(link);
            TEST_ASSERT(real != NULL);
            TEST_ASSERT(!launch_gen_vision(link) && !launch_gen_0731(link));
            TEST_ASSERT(real && launch_gen_vision(real) && !launch_gen_0731(real));
            TEST_ASSERT(launch_realpath("/nonexistent/ds4flash.gguf") == NULL);
            /* A drafter kept beside the LINK (a different directory from
             * the resolved base) is still found: resolved dir first, then
             * the typed dir. */
            char *linkdir = launch_join(dir, "linkdir");
            char *link2 = linkdir ? launch_join(linkdir, "ds4flash.gguf") : NULL;
            char *drafter = linkdir ? launch_join(linkdir, LAUNCH_DSPARK_GGUF_VISION) : NULL;
            TEST_ASSERT(linkdir && mkdir(linkdir, 0700) == 0);
            TEST_ASSERT(link2 && symlink(target, link2) == 0);
            FILE *dfp = drafter ? fopen(drafter, "wb") : NULL;
            TEST_ASSERT(dfp != NULL);
            if (dfp) fclose(dfp);
            char *real2 = launch_realpath(link2);
            char *rdir = real2 ? launch_dirname(real2) : NULL;
            char *dir_real = launch_realpath(dir);   /* macOS: /tmp -> /private/tmp */
            TEST_ASSERT(rdir && dir_real && !strcmp(rdir, dir_real));
            free(dir_real);
            char *found = launch_join2(rdir ? rdir : dir, linkdir, LAUNCH_DSPARK_GGUF_VISION);
            TEST_ASSERT(found && launch_file_ok(found) && !strcmp(found, drafter));
            char *missing = launch_join2(rdir ? rdir : dir, linkdir, "nope.gguf");
            TEST_ASSERT(missing && !launch_file_ok(missing) && strstr(missing, "linkdir") == NULL);
            free(found);
            free(missing);
            free(rdir);
            free(real2);
            if (drafter) unlink(drafter);
            if (link2) unlink(link2);
            if (linkdir) rmdir(linkdir);
            free(drafter);
            free(link2);
            free(linkdir);
            free(real);
            if (link) unlink(link);
            if (target) unlink(target);
            rmdir(dir);
            free(target);
            free(link);
        }
    }
}

/* The drafter / MTP decision matrix (09-02 review ask): every row the
 * launch defaults can take, enumerated without touching the filesystem. */
static void test_launch_spec_decision_matrix(void) {
    /* Drafter names: the generation picks the stamped extraction; env
     * names the file; any disabling flag, an explicit drafter, or no
     * sibling directory means no probe at all. */
    launch_drafter_plan p;
    p = launch_drafter_names(false, false, false, true, true, false, NULL);
    TEST_ASSERT(p.preferred && !strcmp(p.preferred, LAUNCH_DSPARK_GGUF_VISION) && p.fallback == NULL);
    p = launch_drafter_names(false, false, false, true, false, true, NULL);
    TEST_ASSERT(p.preferred && !strcmp(p.preferred, LAUNCH_DSPARK_GGUF_0731));
    TEST_ASSERT(p.fallback && !strcmp(p.fallback, LAUNCH_DSPARK_GGUF));
    p = launch_drafter_names(false, false, false, true, false, false, NULL);
    TEST_ASSERT(p.preferred && !strcmp(p.preferred, LAUNCH_DSPARK_GGUF) && p.fallback == NULL);
    p = launch_drafter_names(false, false, false, true, true, false, "custom.gguf");
    TEST_ASSERT(p.preferred && !strcmp(p.preferred, "custom.gguf") && p.fallback == NULL);
    p = launch_drafter_names(false, false, false, true, true, false, "");   /* empty env = unset */
    TEST_ASSERT(p.preferred && !strcmp(p.preferred, LAUNCH_DSPARK_GGUF_VISION));
    TEST_ASSERT(launch_drafter_names(true, false, false, true, true, false, NULL).preferred == NULL);   /* --no-spec */
    TEST_ASSERT(launch_drafter_names(false, true, false, true, true, false, NULL).preferred == NULL);   /* --no-dspark */
    TEST_ASSERT(launch_drafter_names(false, false, true, true, true, false, NULL).preferred == NULL);   /* explicit --dspark / DS4_DSPARK_MODEL */
    TEST_ASSERT(launch_drafter_names(false, false, false, false, true, false, NULL).preferred == NULL); /* relative -m under --chdir */

    /* Arming: DS4_CONT_DSPARK=0 or "" disarms; unset or "1" keeps it. */
    TEST_ASSERT(launch_drafter_armed(false, false, true, NULL));
    TEST_ASSERT(launch_drafter_armed(false, false, true, "1"));
    TEST_ASSERT(!launch_drafter_armed(false, false, true, "0"));
    TEST_ASSERT(!launch_drafter_armed(false, false, true, ""));
    TEST_ASSERT(!launch_drafter_armed(false, false, false, NULL));
    TEST_ASSERT(!launch_drafter_armed(true, false, true, NULL));
    TEST_ASSERT(!launch_drafter_armed(false, true, true, NULL));

    /* MTP: (no_spec, no_mtp, mtp_set, has_sib, gen_0731, gen_vision, drafter_armed, preset_spark) */
    TEST_ASSERT(launch_mtp_decide(false, false, false, true,  false, true,  true,  false) == LAUNCH_MTP_RETIRED); /* Vision-Exp + drafter */
    TEST_ASSERT(launch_mtp_decide(false, false, false, true,  false, true,  false, true)  == LAUNCH_MTP_RETIRED); /* Vision-Exp, --preset spark, no drafter */
    TEST_ASSERT(launch_mtp_decide(false, false, false, true,  true,  false, true,  false) == LAUNCH_MTP_RETIRED); /* 0731 + drafter */
    TEST_ASSERT(launch_mtp_decide(false, false, false, true,  true,  false, false, true)  == LAUNCH_MTP_RETIRED); /* 0731 + --preset spark */
    TEST_ASSERT(launch_mtp_decide(false, false, false, true,  false, false, true,  false) == LAUNCH_MTP_DROPPED); /* legacy + armed drafter */
    TEST_ASSERT(launch_mtp_decide(false, false, false, true,  false, false, true,  true)  == LAUNCH_MTP_PROBE);   /* legacy + armed + --preset spark = full stack */
    TEST_ASSERT(launch_mtp_decide(false, false, false, true,  false, false, false, false) == LAUNCH_MTP_PROBE);   /* legacy, no drafter */
    TEST_ASSERT(launch_mtp_decide(true,  false, false, true,  false, false, false, false) == LAUNCH_MTP_SKIP);    /* --no-spec */
    TEST_ASSERT(launch_mtp_decide(false, true,  false, true,  false, false, false, false) == LAUNCH_MTP_SKIP);    /* --no-mtp */
    TEST_ASSERT(launch_mtp_decide(false, false, true,  true,  false, false, false, false) == LAUNCH_MTP_SKIP);    /* explicit --mtp wins */
    TEST_ASSERT(launch_mtp_decide(false, false, true,  true,  true,  false, false, false) == LAUNCH_MTP_SKIP);    /* explicit --mtp on 0731: the pairing guard floors it */
    TEST_ASSERT(launch_mtp_decide(false, false, false, false, false, false, false, false) == LAUNCH_MTP_SKIP);    /* no sibling dir */
}

